(window.GIM_TS=window.GIM_TS||{})["Ketubot.5"]={"from":120,"a":[["\u0003אורחא דמילתא\u0004 \u0005[דרך ארץ]\u0006 \u0003כמה?\u0004 מה ההתנהגות הראויה בענין זה? \u0003אמר רב: חדש כאן\u0004 בבית המדרש, \u0003וחדש בבית.\u0004 ורמז לדבר, ממה \u0003שנאמר\u0004 בשרות הצבא של דוד: \u0003\"לכל דבר המחלקות הבאה והיצאת חדש בחדש לכל חדשי השנה\"\u0004 (דברי הימים א' כז, א). \u0003ור' יוחנן אמר: חדש כאן\u0004 בבית המדרש \u0003ושנים בביתו, שנאמר\u0004 בפועלים שעבדו לצורך בנין בית המקדש: \u0003\"חדש יהיו בלבנון שנים חדשים בביתו\"\u0004 (מלכים א' ה, כח).","ושואלים: \u0003ורב נמי מאי טעמא\u0004 \u0005[גם כן מה טעם]\u0006 \u0003לא אמר מ\u0004הראיה \u0003ההיא\u0004 שאמר ר' יוחנן? ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003בנין בית המקדש,\u0004 ש\u0003אפשר\u0004 לעשותו \u0003על ידי אחרים,\u0004 שהיו אנשים מרובים שהיו עסוקים בכך, אבל בדבר שאי אפשר לעשותו על ידי אחרים, נותנים לו רשות להיות חודש כאן וחודש שם. ושואלים עוד: \u0003ור' יוחנן מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר מההיא\u0004 \u0005[מאותה]\u0006 ראיה שהביא רב? ומשיבים: \u0003שאני התם דאית ליה הרווחה\u0004 \u0005[שונה שם\u0006 אצל דוד \u0005שיש לו\u0006 בכך \u0005רווח,\u0006 שכר\u0005]\u0006 בעבודת המלך, שכיון שיש בכך רווח — שמא האשה מוותרת לו על שהותו עמה, אבל בדבר שאין בו רווח, כגון תלמוד תורה — רוצה האשה שיהיה הבעל רוב הזמן בביתו.","כיון שהוזכרה מחלוקת רב ור' יוחנן בענין בית המקדש, מביאים מחלוקת נוספת ביניהם, \u0003אמר רב: אנחה שוברת חצי גופו של אדם, שנאמר: \"ואתה בן אדם האנח בשברון מתנים ובמרירות תאנח\"\u0004 (יחזקאל כא, יא), משמע שהאנחה שוברת חצי הגוף עד המתניים. \u0003ור' יוחנן אמר: אף כל גופו של אדם, שנאמר: \"והיה כי יאמרו אליך על מה אתה נאנח ואמרת אל שמועה כי באה ונמס כל לב ורפו כל ידים וכהתה כל רוח וכל ברכים תלכנה מים\"\u0004 (יחזקאל כא, יב), משמע שבאנחה יש שברון כל הגוף כולו.","ושואלים: \u0003ור' יוחנן נמי הכתיב\u0004 \u0005[גם כן הרי נאמר]\u0006 \u0003\"בשברון מתנים\",\u0004 משמע שאין האנחה שוברת את כל גופו! ומשיבים: אין הכוונה שהשברון הוא רק עד המתניים, אלא \u0003ההיא דכי מתחלא\u0004 \u0005[שכאשר מתחילה]\u0006 האנחה להשפיע — \u0003מ\u0004ן ה\u0003מתנים מתחלא\u0004 \u0005[\u0006היא \u0005מתחילה].\u0006 ושואלים: \u0003ורב נמי הכתיב\u0004 \u0005[גם כן הרי נאמר]\u0006 \u0003\"ונמס כל לב ורפו כל ידים וכהתה כל רוח\",\u0004 משמע שבאנחה יש שברון כל הגוף כולו! ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003שמועה\u0004 של \u0003בית המקדש דתקיפא טובא\u0004 \u0005[שחזקה ביותר]\u0006 והיא גורמת צער גדול, אבל סתם אנחה אינה גורמת אלא שברון חצי הגוף.","מסופר: \u0003ההוא ישראל וגוי דהוו קאזלי באורחא בהדי הדדי\u0004 \u0005[שהיו הולכים בדרך יחד].\u0006 \u0003לא אימצי\u0004 \u0005[יכול]\u0006 היה ה\u0003גוי לסגויי בהדי\u0004 \u0005[ללכת יחד עם]\u0006 ה\u0003ישראל,\u0004 שהיה מהלך מהר יותר. \u0003אדכריה\u0004 \u0005[הזכיר לו]\u0006 את \u0003חורבן בית המקדש\u0004 כדי לצערו ולעכבו. \u0003נגיד ואיתנח\u0004 \u0005[נאנק ונאנח]\u0006 היהודי, \u0003ואפילו הכי\u0004 \u0005[כך]\u0006 \u0003לא אימצי\u0004 \u0005[יכול]\u0006 היה ה\u0003גוי לסגויי בהדיה\u0004 \u0005[ללכת איתו],\u0006 שעדיין היהודי הלך מהר יותר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 הגוי: \u0003לאו אמריתו\u0004 \u0005[\u0006האם \u0005אין אתם אומרים]\u0006 ש\u0003אנחה שוברת חצי גופו של אדם,\u0004 ואם כן מדוע לא השפיע עליך הדבר? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הני מילי מילתא חדתי\u0004 \u0005[דברים אלה\u0006 אמורים ב\u0005דבר,\u0006 בצער, \u0005חדש]\u0006 \u0003אבל הא דשנן\u0004 \u0005[זו ש\u0006כבר \u0005שנינו\u0006 והתרגלנו\u0005]\u0006 \u0003בה — לא\u0004 משפיעה עלינו כל כך. \u0003דאמרי אינשי\u0004 \u0005[שאומרים אנשים]\u0006 כפתגם: \u0003דמלפי תכלי לא בהתה\u0004 \u0005[\u0006זו \u0005שרגילה\u0006 ב\u0005שכול\u0006 ילדיה \u0005איננה פוחדת]\u0006 כשמת אחד מן הילדים, וכך הוא הדבר במי שמתרגל לצרות.","בשנינו במשנה ש\u0003הטיילין\u0004 עונתם \u0003בכל יום.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"טיילין\"? אמר רבא: בני פירקי\u0004 \u0005[תלמידים\u0006 ההולכים לשנות \u0005פרקם\u0006 בישיבה שבמקומם\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרבא, והקשה על דבריו: \u0003מאן דכתיב בהו\u0004 \u0005[מי\u0006 הם אלו \u0005שנאמר בהם]\u0006 \u0003\"שוא לכם משכימי קום מאחרי שבת אכלי לחם העצבים כן יתן לידידו שנא\"\u0004 (תהלים קכז, ב), \u0003ואמר רב יצחק: אלו נשותיהן של תלמידי חכמים שמנדדות שינה מעיניהם בעולם הזה ובאות לחיי העולם הבא,\u0004 משמע מכאן שתלמידי חכמים מתייגעים הרבה בתורתם, ואינם מצויים בערב בבית, \u0003ואת אמרת בני פירקי\u0004 \u0005[ואתה אומר שתלמידים\u0006 השונים \u0005פרקם\u0006 בישיבה\u0005]\u0006 הם הקרויים \"טיילים\"?!","\u0003אלא אמר אביי:\u0004 יש לומר \u0003כ\u0004פי שפירש זאת \u0003רב,\u0004 ש\u0003אמר רב:\u0004 הכוונה היא \u0003כגון רב שמואל בר שילת, דאכיל מדידיה, ושתי מדידיה, וגני בטולא דאפדניה, ולא חליף פריסתקא דמלכא אבביה\u0004 \u0005[שאוכל משלו, ושותה משלו, וישן בצל ביתו, ואין שליח גובה המיסים של המלך עובר על פתחו],\u0006 משום שלא ידעו שהוא אמיד, ואדם כזה שיש לו פרנסה ואין לו דאגות הוא הקרוי \"טייל\". \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר: כגון מפנקי דמערבא\u0004 \u0005[\u0006ה\u0005מפונקים של ארץ ישראל]\u0006 הם הקרויים \"טיילים\".","ומסופר על כוחם של בני ארץ ישראל: \u0003ר' אבהו הוה קאי בי באני\u0004 \u0005[היה עומד\u0006 ב\u0005בית המרחץ],\u0006 \u0003הוו סמכי ליה תרי עבדי\u0004 \u0005[\u0006ו\u0005היו סומכים אותו\u0006 בהליכתו \u0005שני עבדים],\u0006 \u0003איפחית בי באני מתותיה\u0004 \u0005[נפחת בית המרחץ מתחתיו\u0006 ונהרס\u0005],\u0006 \u0003איתרמי ליה עמודא\u0004 \u0005[הזדמן לו עמוד]\u0006 שעמד עליו, \u0003סליק ואסקינהו\u0004 \u0005[עלה\u0006 בעצמו \u0005והעלה\u0006 ביחד עימו את שניהם\u0005],\u0006 שכל כך היה גיבור כוח. וכיוצא בזה מסופר: \u0003ר' יוחנן הוה קסליק בדרגא\u0004 \u0005[היה עולה במדרגות],\u0006 \u0003הוו סמכי ליה\u0004 \u0005[היו סומכים אותו]\u0006 \u0003רב אמי ורב אסי. איפחתא דרגא תותיה\u0004 \u0005[נשברה המדרגה שמתחתיו],\u0006 \u0003סליק ואסקינהו\u0004 \u0005[עלה והעלה אותם].\u0006 \u0003אמרי ליה רבנן\u0004 \u0005[אמרו לו חכמים]:\u0006 \u0003וכי מאחר דהכי\u0004 \u0005[שכך],\u0006 שאתה חזק כל כך, \u0003למה ליה למיסמכיה\u0004 \u0005[למה\u0006 צריך \u0005לסמוך אותו]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אם כן\u0004 אעשה ואוציא כוחי עתה \u0003מה אניח לעת זקנה?\u0004","שנינו במשנה: \u0003והפועלים\u0004 עונתם \u0003שתים\u0004 (פעמיים) \u0003בשבת\u0004 (בשבוע). ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הפועלים\u0004 עונתם \u0003אחת בשבת! אמר ר' יוסי בר' חנינא: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003כאן\u0004 במשנה שאמרנו שעונת הפועלים פעמיים בשבוע, הרי זה \u0003בעושין מלאכה בעירן, כאן\u0004 בברייתא שאמרנו שעונתם פעם בשבוע, הרי זה \u0003בעושין מלאכה בעיר אחרת. תניא נמי הכי\u0004 \u0005[שנויה ברייתא גם כן כך]\u0006 כדבריו: \u0003הפועלים\u0004 עונתם \u0003שתים בשבת, במה דברים אמורים — בעושין מלאכה בעירן, אבל בעושין מלאכה בעיר אחרת —\u0004 עונתם \u0003אחת בשבת.\u0004","שנינו במשנה כי עונת \u0003החמרים אחת בשבת\u0004 ויש אחרים שעונתם עוד פחות מזה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה בר רב חנן לאביי: איכפל תנא לאשמועינן\u0004 \u0005[חזר\u0006 וטרח \u0005התנא\u0006 ברישא \u0005להשמיע לנו\u0006 דין\u0005]\u0006 \u0003טייל ו\u0004דין \u0003פועל?\u0004 שהרי לפי סדר העונה הזה יוצא שההלכה שנאמרה במדיר אשתו מתשמיש שבוע יקיים ולאחר מכן יוציא, אינה אלא בטייל ופועל שעונה שלהם פעמיים בשבוע אבל לרוב בני האדם שעונתם אחת בשבת או בפרקי זמן רחוקים יותר — אין בכך כל פגם, שהרי הנדר אינו פוגע בחיוב העונה שלהם! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא,\u0004"],["\u0003אכולהו\u0004 \u0005[על כולם]\u0006 ולא רק על טייל ופועל נאמר הדבר, שאם מדיר את אשתו יותר משבוע — צריך לגרשה. הקשה לו: \u0003והא\u0004 \u0005[והרי]\u0006 בספן \u0003ששה חדשים קאמר\u0004 \u0005[אמר],\u0006 ומדוע כשמדירה לשבוע בלבד יצטרך להוציאה? ענה לו: הלא ידוע כי \u0003אינו דומה מי שיש לו פת בסלו למי שאין לו פת בסלו,\u0004 שמי שאין לו פת מזומנת בסלו בזמן תענית סובל יותר ממי שיש לו מה לאכול, שמתוך העובדה שהוא יודע שיש לו מה לאכול אין הוא סובל כל כך, ואף כאן: האשה, כיון שהיא יודעת שהדבר אסור לה מחמת הנדר — יש לה צער יותר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה בר רב חנן לאביי: חמר ונעשה גמל מאי\u0004 \u0005[מה]\u0006 דינו, האם רשאי הוא לשנות את מקצועו, ולהרוויח יותר בעבודתו, למרות שהוא ממעט בעונתה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003רוצה אשה בקב ותיפלות\u0004 שיהיה בעלה איתה, יותר \u0003מעשרה קבין\u0004 של פרנסה \u0003ופרישות,\u0004 ולכן אין לו רשות לשנות את מקצועו שלא בהסכמתה.","ועוד שנינו במשנה: עונת \u0003הספנים\u0004 — \u0003אחת לששה חדשים,\u0004 אלו \u0003דברי ר' אליעזר. אמר רב ברונא אמר רב: הלכה כר' אליעזר\u0004 בהלכות אלה. \u0003אמר רב אדא בר אהבה אמר רב:\u0004 כל הלכה \u0003זו\u0004 היא כ\u0003דברי ר' אליעזר, אבל חכמים אומרים: התלמידים יוצאין לתלמוד תורה שתים ושלש שנים שלא ברשות\u0004 נשותיהם, אף שנמנעים בשל כך מתשמיש. \u0003אמר רבא: סמכו רבנן\u0004 \u0005[חכמים]\u0006 על דברי \u0003רב אדא בר אהבה ועבדי עובדא בנפשייהו\u0004 \u0005[ועשו מעשה בעצמם]\u0006 לצאת מן הבית וללמוד ולא תמיד היו לכך תוצאות טובות.","\u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003רב רחומי הוה שכיח קמיה\u0004 \u0005[היה מצוי לפני]\u0006 \u0003רבא ב\u0004עיר \u0003מחוזא, הוה\u0004 \u0005[היה]\u0006 \u0003רגיל דהוה אתי לביתיה\u0004 \u0005[שהיה בא לביתו]\u0006 \u0003כל מעלי יומא דכיפורי\u0004 \u0005[ערב יום כיפור].\u0006 \u0003יומא חד משכתיה שמעתא\u0004 \u0005[יום אחד משכה אותו הסוגיה]\u0006 ונשאר במקום, ולא בא. \u0003הוה מסכיא דביתהו\u0004 \u0005[היתה מצפה אשתו]\u0006 באותו יום ואמרה בלבה: \u0003השתא אתי, השתא אתי\u0004 \u0005[עכשיו\u0006 הוא \u0005בא, עכשיו\u0006 הוא \u0005בא],\u0006 ולבסוף \u0003לא אתא\u0004 \u0005[בא],\u0006 שהרי נמשך בלימודו ונשאר בבית המדרש. \u0003חלש\u0004 \u0005[חלשה]\u0006 \u0003דעתה,\u0004 הצטערה, \u0003אחית דמעתא\u0004 \u0005[\u0006ו\u0005הורידה דמעה]\u0006 \u0003מעינה.\u0004 באותה שעה \u0003הוה יתיב באיגרא\u0004 \u0005[היה יושב\u0006 רב רחומי \u0005על גג],\u0006 \u0003אפחית איגרא מתותיה ונח נפשיה\u0004 \u0005[נפחת הגג מתחתיו ונחה נפשו,\u0006 נפטר\u0005].\u0006 ללמד כמה צריך אדם להיזהר שלא לצער את אשתו ואפילו שלא בכוונה.","ומבררים: \u0003עונה של תלמידי חכמים אימת\u0004 \u0005[מתי]?\u0006 \u0003אמר רב יהודה אמר שמואל:\u0004 הזמן הראוי להם הוא \u0003מערב שבת לערב שבת.\u0004 ובדומה לזה נאמר על הכתוב \u0003\"אשר פריו יתן בעתו\"\u0004 (תהלים א, ג) \u0003אמר רב יהודה ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003רב הונא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003רב נחמן: זה המשמש מטתו\u0004 (שאז עושה \"פריו\") \u0003מערב שבת לערב שבת.\u0004","ועוד מסופר: \u0003יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא, חתניה\u0004 \u0005[חתנו]\u0006 של \u0003ר' ינאי, הוה אזיל ויתיב בבי\u0004 \u0005[היה הולך ויושב בבית]\u0006 ה\u0003רב, וכל בי שמשי\u0004 \u0005[בין השמשות]\u0006 של ערב שבת \u0003הוה אתי לביתיה\u0004 \u0005[היה בא לביתו],\u0006 \u0003וכי הוה אתי, הוה קא חזי קמיה עמודא דנורא\u0004 \u0005[וכאשר היה בא, היה רואה\u0006 ר' ינאי \u0005לפניו עמוד של אש]\u0006 מפני קדושתו. \u0003יומא חד משכתיה שמעתא\u0004 \u0005[יום אחד משכה אותו הסוגיה]\u0006 ונשאר בבית הרב ולא הגיע הביתה. \u0003כיון\u0004 ש\u0003לא חזי\u0004 \u0005[ראה]\u0006 ר' ינאי \u0003ההוא סימנא\u0004 \u0005[את הסימן ההוא],\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' ינאי\u0004 חותנו לבני המשפחה: \u0003כפו\u0004 (היפכו) את \u0003מטתו,\u0004 כפי שעושים בזמן אבל, שבודאי מת. \u0003ש\u0004כן \u0003אילמלי\u0004 (אילו) היה \u0003יהודה קיים\u0004 (חי) \u0003לא ביטל עונתו,\u0004 ובודאי היה מגיע לביתו. \u0003הואי\u0004 \u0005[היה]\u0006 הדבר הזה שאמר \u0003\"כשגגה שיצא מלפני השליט\"\u0004 (קהלת י, ה), ונתקיים הדבר \u0003ונח נפשיה\u0004 \u0005[ונפטר]\u0006 יהודה בר' חייא.","מסופר: \u0003רבי איעסק ליה לבריה\u0004 \u0005[היה עסוק ל\u0006השיא את \u0005בנו]\u0006 \u0003בי\u0004 \u0005[\u0006לבת מ\u0005בית]\u0006 \u0003ר' חייא, כי מטא למיכתב\u0004 \u0005[כאשר הגיע לכתוב]\u0006 את ה\u0003כתובה נח נפשה דרביתא\u0004 \u0005[נפטרה הנערה]\u0006 בתו של ר' חייא. \u0003אמר רבי:\u0004 וכי \u0003חס ושלום פסולא איכא\u0004 \u0005[יש\u0006 איזה \u0005פסול]\u0006 במשפחות? שרואים שמשמים מעכבים את הזיווג, \u0003יתיבו\u0004 \u0005[ישבו]\u0006 \u0003ועיינו במשפחות,\u0004 ומצאו כי \u0003רבי אתי\u0004 \u0005[בא,\u0006 מוצאו\u0005]\u0006 \u0003משפטיה בן אביטל\u0004 אשת דוד, \u0003ור' חייא אתי\u0004 \u0005[בא]\u0006 \u0003משמעי אחי דוד,\u0004 אם כן כיון שמשפחת רבי באה ממש מבית המלוכה, אף על פי שמשפחת ר' חייא היא משפחה קרובה לה, מכל מקום אין לה ייחוס מלכותי כזה ואין זה זיווג מתאים מכל הצדדים.","\u0003אזיל איעסק ליה לבריה\u0004 \u0005[הלך\u0006 רבי ו\u0005עסק ל\u0006השיא את \u0005בנו]\u0006 \u0003בי\u0004 \u0005[\u0006לבת מ\u0005בית]\u0006 \u0003ר' יוסי בן זימרא. פסקו ליה\u0004 \u0005[לו],\u0006 כלומר, היתנו ביניהם שהם יפרנסוהו \u0003תרתי סרי שנין למיזל בבי\u0004 \u0005[שתים עשרה שנה ללכת לבית]\u0006 ה\u0003רב,\u0004 וההנחה היתה שקודם כל ילמד, ואחר כך יישאנה. \u0003אחלפוה קמיה\u0004 \u0005[העבירו אותה,\u0006 את הנערה, \u0005לפני\u0006 החתן\u0005]\u0006 וכשראה אותה \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003ניהוו שית שנין\u0004 \u0005[שיהיו\u0006 אלה רק \u0005שש שנים].\u0006 \u0003אחלפוה קמיה\u0004 \u0005[העבירו אותה לפניו],\u0006 שוב \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003איכניס והדר איזיל\u0004 \u0005[\u0006קודם \u0005אכנוס\u0006 אותה \u0005ואחר כך אלך\u0006 ללמוד\u0005].\u0006 \u0003הוה קא מכסיף מאבוה\u0004 \u0005[היה מתבייש מאביו],\u0006 שיאמר לו שמפני שראה את הנערה חשק בה ולא יכול היה להמתין. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביו לפייסו: \u0003בני, דעת קונך יש בך,\u0004 שאתה נוהג כדרך שעשה הקדוש ברוך הוא.","וראיה לדבר: \u0003מעיקרא כתיב\u0004 \u0005[מתחילה נאמר]:\u0006 \u0003\"תבאמו ותטעמו\u0004 בהר נחלתך מכון לשבתך פעלת\u0003\"\u0004 (שמות טו, יז), משמע שתחילה היתה הכוונה שייבנה מקדש לישראל רק לאחר כניסתם לארץ ישראל, \u0003ולבסוף כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"ועשו לי מקדש ושכנתי בתוכם\"\u0004 (שמות כה, ח) עוד בהיותם במדבר, משמע שעל ידי הקירבה נעשית חיבה יתירה ומקדימים את מה שהיה צריך להיות מאוחר יותר.","לאחר נישואיו \u0003אזיל יתיב תרתי סרי שני בבי\u0004 \u0005[הלך\u0006 ו\u0005ישב שתים עשרה שנה בבית]\u0006 ה\u0003רב. עד דאתא\u0004 \u0005[שבא]\u0006 לביתו, \u0003איעקרא דביתהו\u0004 \u0005[\u0006נעשתה \u0005אשתו עקרה],\u0006 כפי שאמרו שקורה לאשה שהיתה שנים רבות בלא בעל. \u0003אמר רבי: היכי נעביד\u0004 \u0005[איך נעשה\u0006 עכשיו\u0005],\u0006 אם \u0003נגרשה\u0004 \u0005[יגרש אותה]\u0006 — אם כן \u0003יאמרו: ענייה\u0004 (מסכנה) \u0003זו לשוא שימרה\u0004 (ציפתה). \u0003נינסיב איתתא אחריתי\u0004 \u0005[ישא אשה אחרת]\u0006 כדי שיזכה לבנים — אם כן \u0003יאמרו: זו\u0004 האשה היולדת בנים היא \u0003אשתו, וזו\u0004 שהיא רק נמצאת אצלו היא \u0003זונתו.\u0004 לבסוף \u0003בעי עלה רחמי ואיתסיאת\u0004 \u0005[ביקש עליה\u0006 בעלה \u0005רחמים\u0006 משמים \u0005והתרפאה].\u0006","ועוד מסופר: \u0003ר' חנניה בן חכינאי הוה קאזיל לבי\u0004 \u0005[היה הולך לבית]\u0006 ה\u0003רב בשילהי הלוליה\u0004 \u0005[בסוף\u0006 זמן \u0005חתונתו]\u0006 של \u0003ר' שמעון בן יוחאי, אמר ליה\u0004 \u0005[לו]\u0006 ר' שמעון: \u0003איעכב\u0004 \u0005[המתן]\u0006 \u0003לי עד דאתי בהדך\u0004 \u0005[שאבוא אתך]\u0006 אחרי ימי חופתי. אך בשל רצונו העז ללמוד \u0003לא איעכבא ליה\u0004 \u0005[המתין לו].\u0006 \u0003אזל יתיב תרי סרי שני בבי\u0004 \u0005[הלך\u0006 ו\u0005ישב שתים עשרה שנה בבית]\u0006 ה\u0003רב. עד דאתי\u0004 \u0005[שבא]\u0006 לביתו \u0003אישתנו\u0004 \u0005[השתנו]\u0006 \u0003שבילי דמתא\u0004 \u0005[העיר]\u0006 \u0003ולא ידע\u0004 עוד את הדרך \u0003למיזל לביתיה\u0004 \u0005[ללכת לביתו].\u0006","\u0003אזל יתיב אגודא דנהרא\u0004 \u0005[הלך ישב על גדת הנהר].\u0006 \u0003שמע לההיא רביתא דהוו קרו\u0004 \u0005[שמע לנערה אחת שהיו קוראים]\u0006 \u0003לה: \"בת חכינאי, בת חכינאי, מלי קולתך ותא ניזיל\u0004 \u0005[מלאי\u0006 את \u0005כדך ובואי נלך]\u0006 \u0003\". אמר: שמע מינה האי רביתא דידן\u0004 \u0005[למד מכאן\u0006 ש\u0005זוהי הנערה שלנו],\u0006 כלומר בתו. שהרי הוא לא הכירה לאחר כל אותן השנים. \u0003אזל בתרה\u0004 \u0005[הלך אחריה]\u0006 כדי להגיע לביתו. \u0003הוה יתיבא דביתהו קא נהלה קמחא\u0004 \u0005[היתה יושבת אשתו\u0006 ו\u0005מנפה קמח],\u0006 \u0003דל עינה חזיתיה, סוי לבה\u0004 \u0005[הרימה\u0006 את \u0005עיניה, ראתה אותו, ראה ליבה],\u0006 הכירה אותו, ו\u0003פרח רוחה\u0004 ומתה מרוב התרגשות, \u0003אמר\u0004 ר' חנניה \u0003לפניו: רבונו של עולם, ענייה זו זה שכרה?! בעא רחמי עלה וחייה\u0004 \u0005[ביקש רחמים עליה וחייתה].\u0006","ועוד מסופר: \u0003ר' חמא בר ביסא אזיל יתיב תרי סרי שני בבי מדרשא\u0004 \u0005[הלך\u0006 ו\u0005ישב שתים עשרה שנה בבית המדרש].\u0006 \u0003כי אתא\u0004 \u0005[כאשר בא\u0006 לביתו\u0005],\u0006 \u0003אמר: לא איעביד\u0004 \u0005[אעשה]\u0006 \u0003כדעביד\u0004 \u0005[כמו שעשה]\u0006 \u0003בן חכינאי,\u0004 שבא פתאום הביתה וגרם לאשתו אסון. \u0003עייל יתיב במדרשא\u0004 \u0005[הלך וישב ב\u0006בית \u0005המדרש].\u0006 ו\u0003שלח לביתיה\u0004 \u0005[לביתו]\u0006 להודיע שבא. בעודו יושב בבית המדרש \u0003אתא\u0004 \u0005[בא]\u0006 \u0003ר' אושעיא בריה\u0004 \u0005[בנו]\u0006 שאותו לא הכיר ו\u0003יתיב קמיה\u0004 \u0005[\u0006ו\u0005ישב לפניו].\u0006 \u0003הוה קא משאיל ליה שמעתא\u0004 \u0005[\u0006ו\u0005היה שואל אותו\u0006 ר' אושעיא \u0005הלכות],\u0006 \u0003חזא דקא מתחדדי שמעתיה\u0004 \u0005[ראה ששמועותיו\u0006 של ר' אושעיא \u0005מחודדות,\u0006 שהוא חריף מאד\u0005],\u0006 \u0003חלש דעתיה\u0004 \u0005[חלשה דעתו,\u0006 הצטער\u0005]\u0006 ו\u0003אמר: אי הואי הכא הוה\u0004 \u0005[אם הייתי כאן\u0006 ומלמד את בני \u0005היה]\u0006 \u0003לי זרע כי האי\u0004 \u0005[כזה,\u0006 כמו נער זה\u0005].\u0006","\u0003על לביתיה, על בריה\u0004 \u0005[נכנס לביתו\u0006 ו\u0005נכנס\u0006 גם \u0005בנו],\u0006 \u0003קם קמיה\u0004 \u0005[עמד\u0006 האב \u0005לפניו]\u0006 לתת כבוד לתלמיד חכם, כי \u0003הוא סבר למשאליה שמעתתא קא בעי\u0004 \u0005[חשב\u0006 ש\u0005לשאול אותו\u0006 דבר הלכה \u0005הוא רוצה],\u0006 \u0003אמרה ליה דביתהו\u0004 \u0005[אמרה לו אשתו]\u0006 לר' חמא: \u0003מי איכא אבא דקאים מקמי ברא\u0004 \u0005[האם יש אב שעומד מפני בנו]?\u0006 ומעירים: \u0003קרי עליה\u0004 \u0005[קרא עליו]\u0006 \u0003רמי בר חמא\u0004 את הכתוב: \u0003\"\u0004ו\u0003החוט המשלש לא במהרה ינתק\"\u0004 (קהלת ד, יב) — \u0003זה ר' אושעיא, בנו של ר' חמא בר ביסא,\u0004 שהיו במשפחה זו שלושה דורות כאחד של תלמידי חכמים.","ועוד מסופר: \u0003ר' עקיבא רעיא\u0004 \u0005[רועה]\u0006 של \u0003בן כלבא שבוע הוה\u0004 \u0005[היה],\u0006 \u0003חזיתיה ברתיה דהוה צניע ומעלי\u0004 \u0005[ראתה אותו בתו\u0006 של כלבא שבוע \u0005שהוא צנוע ומעולה],\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003אי מקדשנא\u0004 \u0005[אם אתקדש]\u0006 \u0003לך, אזלת לבי\u0004 \u0005[תלך לבית]\u0006 ה\u0003רב\u0004 ללמוד? \u0003אמר לה: אין\u0004 \u0005[כן],\u0006 \u0003איקדשא ליה\u0004 \u0005[התקדשה לו]\u0006 \u0003בצינעה ושדרתיה\u0004 \u0005[ושלחה אותו\u0006 ללמוד\u0005].\u0006 \u0003שמע אבוה\u0004 \u0005[אביה]\u0006 את הדבר, \u0003אפקה מביתיה אדרה\u0004 \u0005[הוציאה מביתו\u0006 ו\u0005הדיר אותה]\u0006 \u0003הנאה מנכסיה\u0004 \u0005[מנכסיו].\u0006 \u0003אזיל יתיב תרי סרי שנין בבי\u0004 \u0005[הלך\u0006 ר' עקיבא ו\u0005ישב שתים עשרה שנה בבית]\u0006 ה\u0003רב. כי אתא, אייתי בהדיה תרי סרי אלפי תלמידי\u0004 \u0005[כאשר בא\u0006 שוב לביתו, \u0005הביא איתו שנים עשר אלף תלמידים].\u0006 ובינתיים, \u0003שמעיה לההוא סבא דקאמר\u0004 \u0005[שמע זקן אחד שאומר]\u0006 \u0003לה,\u0004 לאשתו: \u0003עד כמה\u0004"],["\u0003קא מדברת\u0004 \u0005[את נוהגת]\u0006 כ\u0003אלמנות חיים,\u0004 שהרי בעלך נמצא במקום אחר, ואת חיה כאלמנה בחייו?! \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003אי לדידי ציית\u0004 \u0005[אם לי היה מקשיב] —\u0006 \u0003יתיב תרי סרי שני אחריני\u0004 \u0005[היה יושב\u0006 עוד \u0005שתים עשרה שנים אחרות].\u0006 \u0003אמר\u0004 ר' עקיבא כששמע זאת: \u0003ברשות קא עבידנא\u0004 \u0005[אני עושה].\u0006 \u0003הדר אזיל ויתיב תרי סרי שני אחריני בבי\u0004 \u0005[הלך\u0006 ו\u0005ישב\u0006 ללמוד תורה \u0005שתים עשרה שנה אחרות בבית]\u0006 ה\u0003רב. כי אתא אייתי בהדיה\u0004 \u0005[כאשר בא, הביא איתו]\u0006 \u0003עשרין וארבעה אלפי תלמידי\u0004 \u0005[תלמידים],\u0006 \u0003שמעה דביתהו\u0004 \u0005[אשתו],\u0006 \u0003הות קא נפקא לאפיה\u0004 \u0005[\u0006ו\u0005יצאה לקראתו\u0006 לקבל פניו\u0005].\u0006 \u0003אמרו לה שיבבתא\u0004 \u0005[השכנות]:\u0006 \u0003שאילי מאני לבוש ואיכסאי\u0004 \u0005[שאלי בגד ללבוש והתכסי\u0006 בו\u0005],\u0006 שלבושך אינו מתאים לקבל פני אדם גדול. \u0003אמרה להו\u0004 \u0005[להן]:\u0006 \u0003\"יודע צדיק נפש בהמתו\"\u0004 (משלי יב, י). \u0003כי מטיא לגביה, נפלה על אפה, קא מנשקא ליה לכרעיה\u0004 \u0005[כאשר הגיעה אליו, נפלה על פניה\u0006 ו\u0005נישקה את רגליו].\u0006 \u0003הוו קא מדחפי לה שמעיה\u0004 \u0005[היו דוחפים אותה שמשיו],\u0006 שלא ידעו מי היא. \u0003אמר להו\u0004 \u0005[להם]\u0006 ר' עקיבא: \u0003שבקוה\u0004 \u0005[הניחו לה],\u0006 כי כל התורה \u0003שלי ושלכם — שלה הוא.\u0004","בינתיים \u0003שמע אבוה\u0004 \u0005[אביה]\u0006 \u0003דאתא גברא רבה למתא\u0004 \u0005[שבא אדם גדול לעיר]\u0006 \u0003אמר: איזיל לגביה, אפשר דמפר נדראי\u0004 \u0005[אלך אליו, אולי יפר\u0006 את \u0005נדרי]\u0006 ואוכל לפרנס את בתי. \u0003אתא לגביה\u0004 \u0005[בא אליו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' עקיבא: \u0003אדעתא דגברא רבה מי\u0004 \u0005[על דעת ש\u0006יהא עקיבא זה \u0005אדם גדול האם]\u0006 \u0003נדרת? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אפילו\u0004 אם היה יודע \u0003פרק אחד, ואפילו הלכה אחת\u0004 לא הייתי מקפיד. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003הוא. נפל\u0004 חותנו \u0003על אפיה\u0004 \u0005[פניו]\u0006 \u0003ונשקיה\u0004 \u0005[ונשקו]\u0006 \u0003על כרעיה\u0004 \u0005[רגליו]\u0006 \u0003ויהיב ליה פלגא ממוניה\u0004 \u0005[ונתן לו\u0006 את \u0005חצי ממונו].\u0006 ומספרים: \u0003ברתיה\u0004 \u0005[בתו]\u0006 של \u0003ר' עקיבא עבדא ליה\u0004 \u0005[עשתה לו]\u0006 \u0003לבן עזאי הכי\u0004 \u0005[כך],\u0006 שהיה איש פשוט והיא גרמה לו שילמד תורה. \u0003והיינו דאמרי אינשי\u0004 \u0005[והוא שאומרים בני אדם\u0006 בפתגם מקובל\u0005]:\u0006 \u0003רחילא בתר רחילא אזלא\u0004 \u0005[כבשה אחר כבשה הולכת],\u0006 \u0003כעובדי אמה כך עובדי ברתא\u0004 \u0005[כמעשי האם כך מעשי הבת].\u0006","ועוד באותו נושא: \u0003רב יוסף בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא שדריה אבוהי לבי\u0004 \u0005[שלח אותו אביו לבית]\u0006 ה\u0003רב,\u0004 שילמד \u0003לקמיה\u0004 \u0005[לפני]\u0006 \u0003רב יוסף. פסקו ליה שית שני\u0004 \u0005[קצבו לו שש שנים]\u0006 שיישב בבית הרב. \u0003כי הוה תלת שני\u0004 \u0005[כאשר היו,\u0006 עברו, \u0005שלוש שנים]\u0006 \u0003מטא מעלי יומא דכפורי\u0004 \u0005[הגיע ערב יום כיפור],\u0006 \u0003אמר\u0004 הבן: \u0003איזיל ואיחזינהו לאינשי\u0004 \u0005[אלך ואראה את אנשי]\u0006 \u0003ביתי,\u0004 כלומר, אלך אל אשתי. \u0003שמע אבוהי\u0004 \u0005[אביו],\u0006 \u0003שקל מנא ונפק לאפיה\u0004 \u0005[לקח כלי\u0006 זין כיוצא למלחמה, \u0005ויצא לקראתו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 לפי גירסה אחת: וכי ב\u0003זונתך נזכרת,\u0004 שאתה עוזב את לימודך והולך לאשה? \u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003יונתך נזכרת?\u0004 ומתוך שהיו האב והבן במריבה, \u0003איטרוד\u0004 \u0005[נטרדו]\u0006 \u0003לא מר\u0004 \u0005[חכם\u0006 זה\u0005]\u0006 \u0003איפסיק\u0004 \u0005[הפסיק,\u0006 אכל סעודה מפסקת\u0005],\u0006 \u0003ולא מר\u0004 \u0005[חכם\u0006 זה\u0005]\u0006 \u0003איפסיק\u0004 \u0005[הפסיק]\u0006 באותו יום.","\u0003המורדת על בעלה\u0004 — קונסים אותה בכך ש\u0003פוחתין לה מכתובתה שבעה דינרין ב\u0004כל \u0003שבת\u0004 (שבוע). \u0003ר' יהודה אומר: שבעה טרפעיקין\u0004 (חצאי דינרים). \u0003עד מתי הוא פוחת — עד כנגד כתובתה,\u0004 עד שיגיע הקנס כדי סכום הכתובה שלה. \u0003ר' יוסי אומר: לעולם הוא פוחת והולך\u0004 אפילו יותר מכדי הכתובה, \u0003עד שאם תפול לה ירושה ממקום אחר, גובה הימנה. וכן\u0004 עושים אם אירע להיפך, \u0003המורד על אשתו\u0004 — קונסים אותו ו\u0003מוסיפין על כתובתה שלשה דינרין ב\u0004כל \u0003שבת\u0004 (שבוע). \u0003ר' יהודה אומר: שלשה טרפעיקין.\u0004","שואלים: \u0003מורדת ממאי\u0004 \u0005[ממה],\u0006 באיזה ענין מורדת על בעלה? \u0003רב הונא אמר: מתשמיש המטה. ר' יוסי ברבי חנינא אמר:\u0004 מורדת \u0003ממלאכה,\u0004 שאינה רוצה לעשות מלאכה עבורו. \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003וכן המורד על אשתו. בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 כי מרידה זו היא \u0003מתשמיש — לחיי\u0004 \u0005[בסדר],\u0006 שמובן מהו ענין מורד גם לגבי הבעל, \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שמורד \u0003ממלאכה, מי\u0004 \u0005[האם]\u0006 \u0003משועבד לה\u0004 הבעל לעשות מלאכה? ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 מדובר \u0003באומר \"איני זן ואיני מפרנס\",\u0004 שמורד בחובתו לפרנסה.","ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב: האומר \"איני זן ואיני מפרנס\u0004 את אשתי \u0003\"\u0004— \u0003יוציא\u0004 מיד \u0003ויתן כתובה!\u0004 ומשיבים: \u0003ולאו לאמלוכי ביה בעי\u0004 \u0005[ו\u0006כי \u0005אין\u0006 צורך \u0005להמלך בו]\u0006 אם חוזר בו? ובאותו זמן שדנים עמו ומסבירים לו שהוא צריך לגרש את אשתו, קונסים אותו בינתיים שיוסיף לה על כתובתה.","\u0003מיתבי\u0004 \u0005[שואלים]\u0006 ממה ששנינו בברייתא לענין מורדת: \u0003אחת לי\u0004 (כלומר, אותו דין) אם היתה זו \u0003ארוסה\u0004 שמרדה, או \u0003נשואה, ואפילו\u0004 היתה \u0003נדה, ואפילו חולה, ואפילו שומרת יבם.\u0004","ונברר במה מדובר, \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 ש\"מורדת\" משמעו \u0003ממלאכה — שפיר\u0004 \u0005[יפה]\u0006 ומובן הדבר. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שמורדת \u0003מתשמיש,\u0004 וכי \u0003נדה בת תשמיש היא?\u0004 ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]:\u0006 \u0003אינו דומה מי שיש לו פת בסלו למי שאין לו,\u0004 שמי שאין לו פת מזומנת בסלו בזמן תענית סובל יותר ממי שיש לו מה לאכול, שמתוך העובדה שהוא יודע שיש לו מה לאכול אין הוא סובל כל כך, ואף כאן, כיון שהיא אומרת לו שאינה רוצה בתשמיש, הריהו מצטער יותר במניעתו אפילו כשהיא נדה או חולה.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שהקושיה היתה באופן אחר: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 שמשמעות \"מורדת\" הוא \u0003מתשמיש — היינו דקתני\u0004 \u0005[הוא ששנה]\u0006 ברשימת הנקנסות גם \u0003חולה,\u0004 שאף שאינה מסוגלת לעבוד, הריהי יכולה להיות מורדת לענין תשמיש."],["\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שמורדת \u0003ממלאכה,\u0004 וכי \u0003חולה בת מלאכה היא?\u0004 שמאחר שהיא חולה אין עליה כל חובה לעשות מלאכה, ואין זו מרידה כלל. \u0003אלא,\u0004 כך יש לפרש את הדברים: אם מורדת \u0003מתשמיש — כולי עלמא לא פליגי דהויא\u0004 \u0005[הכל אינם חלוקים שהיא]\u0006 \u0003מורדת. כי פליגי\u0004 \u0005[כאשר נחלקו],\u0006 הרי הוא לגבי מורדת \u0003ממלאכה; מר\u0004 \u0005[חכם\u0006 זה, רב הונא\u0005]\u0006 \u0003סבר\u0004 אם מורדת \u0003ממלאכה — לא הויא\u0004 \u0005[אינה\u0006 נחשבת\u0005]\u0006 \u0003מורדת, ומר\u0004 \u0005[וחכם\u0006 זה, רב יוסי בר חנינא\u0005]\u0006 \u0003סבר\u0004 שמורדת \u0003ממלאכה נמי הויא\u0004 \u0005[גם כן היא]\u0006 נידונת כ\u0003מורדת.\u0004","\u0003גופא\u0004 \u0005[לגופה]\u0006 של ההלכה, שנינו: \u0003המורדת על בעלה פוחתין לה מכתובתה שבעה דינרים בשבת\u0004 (בשבוע). \u0003ר' יהודה אומר:\u0004 אין פוחתים לה אלא \u0003שבעה טרפעיקין. רבותינו חזרו ונמנו\u0004 (הצביעו, והגיעו להחלטה) שאין מפחיתים לה מכתובתה כל שבוע, אלא \u0003שיהו מכריזין עליה\u0004 ברבים \u0003ארבע שבתות זו אחר זו, ושולחין לה בית דין\u0004 ומודיעים לה: \u0003הוי יודעת שאפילו כתובתיך מאה מנה — הפסדת\u0004 הכל. ואם בכל זאת לא חזרה בה — מפסידה את כל הכתובה. \u0003אחת לי\u0004 לענין זה אם היא \u0003ארוסה,\u0004 או \u0003נשואה,\u0004 ו\u0003אפילו\u0004 היא \u0003נדה, אפילו חולה, ואפילו שומרת יבם.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חייא בר יוסף לשמואל:\u0004 וכי \u0003נדה בת תשמיש היא? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אינו דומה מי שיש לו פת בסלו למי שאין לו פת בסלו,\u0004 שמי שאין לו פת מזומנת בסלו בזמן תענית סובל יותר ממי שיש לו מה לאכול, שמתוך העובדה שהוא יודע שיש לו מה לאכול אין הוא סובל כל כך, ואף כאן, כיון שהיא אומרת לו שאינה רוצה בתשמיש, הריהו מצטער יותר במניעתו אפילו כאשר היא נדה.","\u0003אמר רמי בר חמא: אין מכריזין עליה אלא בבתי כנסיות ובבתי מדרשות\u0004 ולא ברחוב. \u0003אמר רבא: דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 הדבר מלשון הברייתא, \u0003דקתני\u0004 \u0005[ששונה]:\u0006 \u0003ארבע שבתות זו אחר זו,\u0004 שהם ימים שאין בהם מלאכה, ואין אנשים מצויים ברחובות, אלא בבתי כנסיות ובבתי מדרשות. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכך הוא. \u0003אמר רמי בר חמא: פעמים שולחין לה מבית דין\u0004 לדבר עמה; \u0003אחת קודם הכרזה, ואחת לאחר הכרזה.\u0004","\u0003דרש רב נחמן בר רב חסדא\u0004 בענין זה: \u0003הלכה כרבותינו. אמר רבא: האי בורכא\u0004 \u0005[זו שטות].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן בר יצחק: מאי בורכתיה\u0004 \u0005[מה השטות\u0006 בזה\u0005]?\u0006 \u0003אנא אמריתה ניהליה, ומשמיה דגברא רבה אמריתה ניהליה\u0004 \u0005[אני אמרתי לו\u0006 את הדבר, \u0005ומשמו של אדם גדול אמרתי לו זאת],\u0006 \u0003ומנו\u0004 \u0005[ומיהו]\u0006 אדם גדול זה שפסק הלכה כך, \u0003ר' יוסי בר' חנינא.\u0004","ושואלים: \u0003ואיהו\u0004 \u0005[והוא,\u0006 רבא\u0005]\u0006 \u0003כמאן סבר\u0004 \u0005[כ\u0006דעת \u0005מי סבור]?\u0006 ומשיבים: \u0003כי הא דאתמר\u0004 \u0005[כמו זו שנאמר]\u0006 שאמר \u0003רבא אמר רב ששת: הלכה, נמלכין בה,\u0004 שמדברים איתה ומסבירים לה ובינתיים מפחיתים לה מכתובתה. \u0003רב הונא בר יהודה אמר רב ששת: הלכה, אין נמלכין בה.\u0004 ולדעת שניהם אינה מפסידה בבת אחת כרבותינו, אלא מפחיתים לה כל שבוע.","לעצם ההלכה מבררים: \u0003היכי דמיא\u0004 \u0005[כיצד היא בדיוק]\u0006 \u0003מורדת? אמר אמימר: דאמרה\u0004 \u0005[שאומרת]:\u0006 \u0003\"בעינא ליה ומצערנא ליה\u0004 \u0005[אני רוצה אותו\u0006 וחפצה להיות נשואה לו, אבל אני רוצה \u0005לצער אותו]\u0006 \u0003\"\u0004בגלל סכסוך שביניהם. \u0003אבל\u0004 אם \u0003אמרה\u0004 \u0005[\u0006היא \u0005אומרת]\u0006 \u0003\"מאיס\u0004 \u0005[מאוס]\u0006 הוא \u0003עלי\" — לא כייפינן לה\u0004 \u0005[אין כופין אותה],\u0006 שאין כופים אדם להיות עם מי שמאוס עליו. \u0003מר זוטרא אמר: כייפינן לה\u0004 \u0005[כופים אותה]\u0006 להישאר אתו.","ומספרים: \u0003הוה עובדא\u0004 \u0005[היה מעשה]\u0006 באשה שמרדה בטענת \"מאוס עלי\" \u0003ואכפה\u0004 \u0005[וכפה אותה]\u0006 \u0003מר זוטרא\u0004 להישאר עם בעלה, \u0003ונפק מיניה\u0004 \u0005[ויצא ממנו]\u0006 מזיווג זה \u0003ר' חנינא מ\u0004העיר \u0003סורא.\u0004 ומכאן שיכולה כפיה כזו להביא ברכה. אבל מסכמים: \u0003ולא היא,\u0004 אין לעשות כן. \u0003התם סייעתא דשמיא הוה\u0004 \u0005[שם היה\u0006 זה \u0005סיוע משמים],\u0006 אבל בדרך כלל אין יוצאים וולדות טובים מזיווג שאין האשה רוצה בו.","מסופר: \u0003כלתיה\u0004 \u0005[כלתו]\u0006 של \u0003רב זביד אימרדא\u0004 \u0005[מרדה]\u0006 בבעלה, \u0003הוה תפיסא חד שירא\u0004 \u0005[\u0006ו\u0005היתה תופסת\u0006 בידה \u0005בגד אחד].\u0006 \u0003יתיב\u0004 \u0005[ישבו]\u0006 \u0003אמימר ומר זוטרא ורב אשי, ויתיב\u0004 \u0005[וישב]\u0006 \u0003רב גמדא גבייהו\u0004 \u0005[איתם].\u0006 \u0003יתבי וקאמרי\u0004 \u0005[ישבו ואמרו]:\u0006 אשה ש\u0003מרדה\u0004 בבעלה — \u0003הפסידה\u0004 גם את \u0003בלאותיה\u0004 ה\u0003קיימין,\u0004 שאפילו הבגדים שהביאה איתה בנדונייתה ואפילו קיימים עדיין — גם אותם היא מפסידה. \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב גמדא: משום\u0004 ש\u0003רב זביד גברא רבה\u0004 \u0005[אדם גדול]\u0006 הוא, \u0003מחניפיתו ליה\u0004 \u0005[מחניפים אתם לו\u0006 בהלכה\u0005]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב כהנא: מיבעיא בעי\u0004 \u0005[שאל,\u0006 הסתפק\u0005]\u0006 \u0003רבא\u0004 בבעיה זו אם היא מפסידה בלאותיה אם לא, \u0003ולא פשיט\u0004 \u0005[פתר],\u0006 ואתם מגיעים להחלטה רק בגלל כבודו של רב זביד? \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שאותו מעשה היה באופן אחר, ש\u0003יתבי וקאמרי\u0004 \u0005[ישבו\u0006 שלושה חכמים אלה \u0005ואמרו],\u0006 שזו ש\u0003מרדה לא הפסידה\u0004 את \u0003בלאותיה\u0004 ה\u0003קיימין. אמר להו\u0004 \u0005[להם]\u0006 \u0003רב גמדא:\u0004"],["\u0003משום\u0004 ש\u0003רב זביד גברא רבה\u0004 \u0005[אדם גדול]\u0006 \u0003הוא\u0004 ולא יבוא לערער על פסק הדין, \u0003אפכיתו ליה לדינא עילויה\u0004 \u0005[הופכים אתם את הדין עליו]?\u0006 \u0003האמר\u0004 \u0005[\u0006ו\u0005הרי אמר]\u0006 \u0003רב כהנא: מיבעיא בעי לה\u0004 \u0005[שאל,\u0006 הסתפק\u0005]\u0006 \u0003רבא\u0004 בענין הזה, \u0003ולא פשיט\u0004 \u0005[פתר],\u0006 ואיך פסקתם אתם שאין מוציאים ממנה?! ומסכמים: \u0003השתא,\u0004 ש\u0003לא אתמר\u0004 \u0005[נאמר]\u0006 ולא סוכם \u0003לא הכי\u0004 \u0005[כך]\u0006 \u0003ולא הכי\u0004 \u0005[כך],\u0006 אם \u0003תפסה\u0004 בידה דבר מרכושה — \u0003לא מפקינן מינה\u0004 \u0005[אין מוציאים ממנה],\u0006 אך אם \u0003לא תפסה — לא יהבינן\u0004 \u0005[נותנים]\u0006 \u0003לה.\u0004","ומוסיפים עוד הלכה בענין מורדת: \u0003ומשהינן לה תריסר ירחי שתא אגיטא\u0004 \u0005[ומשהים אותה שנים עשר חודשי שנה על הגט],\u0006 שאין נותנים לה את הגט עד אז, \u0003ובהנך תריסר ירחי שתא לית\u0004 \u0005[ובאותם שנים עשר חודש אין]\u0006 \u0003לה מזוני\u0004 \u0005[מזונות]\u0006 \u0003מ\u0004ן ה\u0003בעל.\u0004","\u0003אמר רב טובי בר קיסנא אמר שמואל: כותבין אגרת מרד\u0004 (פסק בית דין הגורע מכתובתה) \u0003על ארוסה\u0004 המורדת על בעלה, \u0003ואין כותבין אגרת מרד על שומרת יבם\u0004 שאינה רוצה להיבעל על ידו. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 מן הברייתא: \u0003אחת לי\u0004 בענין דין אשה המורדת אם היא \u0003ארוסה\u0004 או \u0003נשואה,\u0004 ו\u0003אפילו\u0004 היא \u0003נדה,\u0004 ו\u0003אפילו חולה, ואפילו שומרת יבם,\u0004 שלכל אלה דין מורדת!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 כי אפשר לומר כך: \u0003כאן\u0004 שאמרנו שיש לה דין מורדת, הרי זה באופן \u0003שתבע הוא,\u0004 היבם, והיא מורדת ואינה רוצה להיבעל, ואילו \u0003כאן\u0004 שאמרנו שאינה נחשבת כמורדת, הרי זה באופן \u0003שתבעה היא\u0004 והוא מורד ואינו רוצה לכונסה. ש\u0003אמר רב תחליפא בר אבימי אמר שמואל:\u0004 אם \u0003תבע הוא והיא מסרבת — נזקקין לו\u0004 ויש לה דין מורדת, ואם \u0003תבעה היא\u0004 והוא מסרב — \u0003אין נזקקין לה,\u0004 ואין מוסיפים על כתובתה.","ומבררים: \u0003במאי אוקימתא להא\u0004 \u0005[במה,\u0006 באיזה מקרה, \u0005העמדת את זו]\u0006 שאמר \u0003שמואל\u0004 שכותבים אגרת מרד על ארוסה ואין כותבים לשומרת יבם, אם \u0003ב\u0004מקרה \u0003שתבעה היא\u0004 להינשא והוא אינו רוצה, אם כן מדוע \u0003האי\u0004 \u0005[זה]\u0006 הניסוח \u0003\"כותבין אגרת מרד על ארוסה\"\u0004 שמשמעו שכותבים דבר כנגדה? במקום זה \u0003\"\u0004כותבין אגרת מרד \u0003לארוסה\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 ודוחים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה],\u0006 אכן \u0003תני\u0004 \u0005[שנה]\u0006 וגרוס שכותבים \u0003\"לארוסה\".\u0004","ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003שומרת יבם דלא\u0004 \u0005[שאין]\u0006 כותבים לזכותה אגרת מרד על בעלה — משום \u0003דאמרינן\u0004 \u0005[שאנו אומרים]\u0006 \u0003לה: זיל, לא מפקדת\u0004 \u0005[לכי, אין את מצווה]\u0006 על פריה ורביה, ואף שאינה יכולה להינשא, אי אפשר לכפותו לעשות דבר שאינו קשור במצוה. ושואלים: אם אכן זה הטעם, הרי \u0003ארוסה נמי נימא\u0004 \u0005[גם כן נאמר]\u0006 \u0003לה: זיל, לא מפקדת\u0004 \u0005[לכי, אינך מצווה]\u0006 בפריה ורביה, ואם כן מדוע כותבים לה אגרת מרד? \u0003אלא\u0004 מדובר פה \u0003בבאה מחמת טענה, דאמרה\u0004 \u0005[ש\u0006היא \u0005אומרת]:\u0006 \u0003בעינא חוטרא לידא\u0004 \u0005[רוצה אני מקל ליד]\u0006 \u0003ומרה\u0004 \u0005[ומעדר]\u0006 \u0003לקבורה,\u0004 כלומר, רוצה אני שיהיו לי ילדים, שיתמכו בי בזקנתי ויטפלו בקבורתי לאחר מותי, ובשל טענה זו כופין אותו.","אם כן \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 \u0003שומרת יבם, בבאה מחמת טענה\u0004 זו, ומדוע לא ישמעו לה?! \u0003אלא\u0004 חוזרים מן ההסבר שמדובר כשהיא תובעת, וצריך לומר כי \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 מדובר באופן \u0003שתבע הוא\u0004 והיא מורדת, \u0003ולא קשיא\u0004 \u0005[ואינו קשה]\u0006 מן הברייתא על דברי שמואל; \u0003כאן\u0004 שאמרה הברייתא שכותבים אגרת מרד על שומרת יבם הוא לענין שתבע אותה היבם \u0003לחלוץ,\u0004 והיא מסרבת, \u0003וכאן\u0004 שאמר שמואל שאין כותבים, הוא לענין שתבע \u0003לייבם.\u0004 ש\u0003אמר ר' פדת אמר ר' יוחנן:\u0004 אם \u0003תבע\u0004 היבם \u0003לחלוץ\u0004 והיא אינה רוצה — \u0003נזקקין לו. תבע לייבם — אין נזקקין לו.\u0004","ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003לייבם\u0004 ש\u0003לא\u0004 כותבים עליה בשל סירובה אגרת מרד, משום \u0003דאמרינן ליה\u0004 \u0005[שאנו אומרים לו]:\u0006 \u0003זיל ונסיב איתתא אחריתי\u0004 \u0005[לך ושא\u0006 לך \u0005אשה אחרת],\u0006 שאינך חייב דווקא לשאת את זו אם אינה רוצה. אולם אם כן \u0003לחלוץ נמי נימא ליה\u0004 \u0005[גם כן נאמר לו]:\u0006 \u0003זיל ונסיב איתתא אחריתי\u0004 \u0005[לך ושא\u0006 לך \u0005אשה אחרת]\u0006 ואל תחלוץ לה!","\u0003אלא\u0004 יש לומר שהטעם הוא משום \u0003דאמר\u0004 \u0005[שאומר]:\u0006 \u0003\"כיון דאגידא\u0004 \u0005[ש\u0006זו \u0005קשורה]\u0006 \u0003בי, לא קא יהבו\u0004 \u0005[נותנים]\u0006 \u0003לי אחריתי\u0004 \u0005[\u0006אשה \u0005אחרת]\u0006\u0003\",\u0004 שכל עוד לא חלץ, מפריע לו הדבר במציאת אשה אחרת, שיאמרו שיש לו אשה שקשורה בו, ושמא לבסוף תתייבם לו, וזו טענה טובה, ולפיכך כותבין לו אגרת מרד כנגדה.","ושואלים: אם כן \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 אפילו כאשר הוא תובע לייבם אי אפשר לומר לו שישא אחרת שהרי הוא אומר \u0003\"כיון דאגידא\u0004 \u0005[שקשורה]\u0006 \u0003בי לא קא יהבו\u0004 \u0005[נותנים]\u0006 \u0003לי אחריתי\u0004 \u0005[אחרת]\u0006 \u0003\"!\u0004 ומדוע כאן אין כותבים עליה אגרת מרד? \u0003אלא\u0004 ודאי צריך לומר כי \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 מדובר באופן \u0003שתבע לייבם, ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה];\u0006 \u0003כאן\u0004 שכותבים אגרת מרד — מדובר \u0003כ\u0004שיטת \u0003משנה ראשונה,\u0004 ואילו \u0003כאן\u0004 שאין כותבים — \u0003כמשנה אחרונה.\u0004","ומה עניינם — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מצות יבום קודמת למצות חליצה,\u0004 מתי — \u0003בראשונה, שהיו מתכוונין\u0004 לעשות את הייבום \u0003לשום\u0004 (לשם) \u0003מצוה\u0004 ואז היו כופים את האשה להתייבם, ואם אינה רוצה כותבים עליה אגרת מרד. \u0003עכשיו שאין מתכוונין\u0004 בייבום \u0003לשום מצוה,\u0004 ואנו חוששים שמא מתכוונים לדברים אחרים, \u0003אמרו: מצות חליצה קודמת למצות יבום\u0004 ולכן אין כופים אותה, ודברי שמואל שאין כותבים אגרת מרד על שומרת יבם הם כשיטת משנה אחרונה.","שנינו במשנה: \u0003עד מתי הוא פוחת וכו'.\u0004 ונאמר שם שלדעת ר' יהודה הסכומים הם בטרפעיקין, ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הם\u0005]\u0006 \u0003טרפעיקין? אמר רב ששת: אסתירא\u0004 (מטבע קטנה). \u0003וכמה\u0004 הוא \u0003אסתירא — פלגא דזוזא\u0004 \u0005[חצי זוז].\u0006 \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 \u0003ר' יהודה אומר: שלשה טרפעיקין, שהן תשע מעין\u0004 (מעות כסף), \u0003מעה וחצי לכל יום\u0004 כפול שש לשישה ימים בשבוע — הרי הם תשע.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חייא בר יוסף לשמואל: מאי שנא איהו\u0004 \u0005[\u0006ב\u0005מה שונה הוא]\u0006 כאשר היא מורדת \u0003דיהבינן ליה\u0004 \u0005[שאנו נותנים לו]\u0006 גם את של \u0003שבת,\u0004 שהרי פוחתים מכתובתה שבעה זוז לשבוע, ומסתבר שעל כל יום ויום פוחתים מכתובתה זוז, ויום השבת בכלל. \u0003ומאי שנא איהי\u0004 \u0005[ו\u0006ב\u0005מה שונה היא]\u0006 ש\u0003לא יהבינן\u0004 \u0005[נותנים]\u0006 \u0003לה\u0004 גם כנגד יום ה\u0003שבת\u0004 אלא רק כנגד שישה ימים בלבד? ומסבירים: \u0003איהי דמיפחת קא פחית, לא מיחזי\u0004 \u0005[היא\u0006 שנקנסת, \u0005שמפחיתים\u0006 מכתובתה, \u0005אין\u0006 זה \u0005נראה]\u0006 \u0003כשכר שבת,\u0004 שהרי אינו מקבל כסף נוסף, אלא רק מפחית מחובו, ואולם \u0003איהו דאוסופי קא מוספא\u0004 \u0005[הוא שמוסיף]\u0006 בכל יום על כתובתה,"],["\u0003מיחזי\u0004 \u0005[נראה]\u0006 דבר זה \u0003כשכר שבת\u0004 ולכן תיקנו שלא יתן עבור יום השבת.","ועוד באותו נושא, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חייא בר יוסף לשמואל: מה\u0004 הטעם להבדל \u0003בין מורד למורדת,\u0004 שלכל הדעות המורד על אשתו נותן פחות מאשר המורדת? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003צא ולמד משוק של זונות, מי שוכר את מי?\u0004 משמע שצערו של האיש במניעת תשמיש מרובה יותר. \u0003דבר אחר: זה\u0004 האיש כשהוא מתאווה \u0003יצרו מבחוץ\u0004 שנוסף לצער הוא מתגנה בכך, \u0003וזו יצרה מבפנים,\u0004 ואינו ניכר בחוץ.","\u0003המשרה את אשתו על ידי שליש,\u0004 שהניח את פרנסת אשתו בידי אדם שלישי, שנעשה לה מאיזשהו טעם כאפוטרופוס — \u0003לא יפחות לה\u0004 ממזונותיה \u0003משני קבין חטין, או מארבעה קבין שעורין\u0004 לכל שבוע. \u0003אמר ר' יוסי: לא פסק לה שעורין\u0004 בשיעור כפול מחיטים \u0003אלא ר' ישמעאל שהיה\u0004 חי \u0003סמוך ל\u0004ארץ \u0003אדום. ונותן לה\u0004 נוסף לכך \u0003חצי קב\u0004 של \u0003קיטנית, וחצי לוג שמן, וקב גרוגרות\u0004 (תאנים יבשות) \u0003או\u0004 משקל \u0003מנה\u0004 של \u0003דבילה\u0004 (תאנים כבושות). \u0003ואם אין לו\u0004 פירות אלה — \u0003פוסק לעומתן פירות ממקום אחר. ו\u0004כן","\u0003נותן לה מטה, מפץ\u0004 (מחצלת רכה) \u0003ומחצלת\u0004 קשה. \u0003ונותן לה\u0004 ללבושה \u0003כפה לראשה, וחגור למתניה, ומנעלים ממועד למועד,\u0004 שבכל אחד מן הרגלים קונה לה מנעלים, \u0003וכלים\u0004 (בגדים) \u0003של\u0004 (ששוויים) \u0003חמשים זוז משנה לשנה.\u0004 ומעירים: \u0003ואין נותנין לה לא\u0004 בגדים \u0003חדשים\u0004 שהם עבים \u0003בימות החמה,\u0004 משום שמחממים, \u0003ולא שחקים\u0004 בגדים שחוקים \u0003בימות הגשמים,\u0004 שמפני שנשחקו הם דקים, וקר לה. \u0003אלא נותן לה כלים של חמשים זוז בימות הגשמים, והיא מתכסה בבלאותיהן\u0004 גם \u0003בימות החמה. והשחקים\u0004 הבגדים השחוקים שנשארו — \u0003שלה\u0004 הם.","ו\u0003נותן לה\u0004 נוסף לכל זה עוד \u0003מעה כסף לצורכה,\u0004 לשאר צרכיה. \u0003ואוכלת עמו מלילי שבת ללילי שבת,\u0004 שאף שבמשך השבוע הריהי ניזונת באמצעות שליש ואינה מצויה עמו, אבל בלילי שבת היא עמו ממש. \u0003ואם אין נותן לה מעה כסף לצורכה\u0004 — הרי \u0003מעשה ידיה שלה\u0004 ולא שלו.","\u0003ומה היא עושה לו,\u0004 מה הדבר הקצוב שהיא צריכה לעשות לו? — הריהי טווה \u0003משקל חמש סלעים\u0004 של חוטי \u0003שתי ביהודה, שהן עשר סלעים ב\u0004מידות \u0003גליל. או משקל עשר סלעים\u0004 של חוטי \u0003ערב\u0004 (שקל יותר לעשותם) \u0003ביהודה, שהן עשרים סלעים ב\u0004מידות \u0003גליל. ואם היתה\u0004 באותו זמן \u0003מניקה — פוחתין לה ממעשה ידיה, ומוסיפין לה על מזונותיה. במה דברים אמורים\u0004 כל השיעורים והסכומים והקיצבות שנמנו כאן — \u0003בעני שבישראל,\u0004 שאלה הם השיעורים הפחותים של נתינה, \u0003אבל במכובד — הכל לפי כבודו\u0004 מוסיף ונותן.","תחילה שואלים: \u0003מני מתניתין\u0004 \u0005[\u0006של \u0005מי היא משנתנו\u0006 זו\u0005],\u0006 לכאורה אינה \u0003לא\u0004 כדעת \u0003ר' יוחנן בן ברוקא, ולא\u0004 כדעת \u0003ר' שמעון. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003וכמה שיעורו\u0004 של עירוב תחומים — \u0003מזון שתי סעודות לכל אחד ואחד\u0004 מן המשתמשים בעירוב זה. ונחלקו בענין זה, שיש אומרים: צריך לקבוע ענין זה לפי \u0003מזונו\u0004 שרגיל \u0003ל\u0004אכול ביום \u0003חול ולא לשבת,\u0004 אלו \u0003דברי ר' מאיר,\u0004 ו\u0003ר' יהודה אומר:\u0004 מזונו \u0003לשבת, ולא לחול.\u0004 ומעירים: \u0003וזה וזה מתכוונין להקל,\u0004 אלא שנחלקו אם אדם אוכל בשבת יותר או פחות מאשר בימות החול.","\u0003ר' יוחנן בן ברוקא אומר:\u0004 יש לשתי סעודות האמורות שיעור קצוב, והוא \u0003ככר הלקוח\u0004 (הנקנה) \u0003בפונדיון\u0004 (שני איסרים, והוא אחד משנים עשר של הדינר) כאשר ניתן לקנות \u0003ארבע סאין\u0004 ב\u0003סלע\u0004 שהוא ארבעה דינרים. ולפי חשבון זה מדובר בככר לחם ששיעורה חצי קב (חלק אחד משנים עשר של הסאה), ומזון סעודה אחת הוא איפוא רבע הקב. \u0003ר' שמעון אומר:\u0004 שיעור שתי סעודות הוא \u0003שתי ידות\u0004 (שני שלישים) \u0003לככר,\u0004 שגודלם \u0003משלש ככרות לקב.\u0004 ונמצא שמזון סעודה אחת הוא תשיעית הקב.","ומעירים: \u0003חציה\u0004 של ככר כזו הוא השיעור \u0003ל\u0004ענין \u0003בית המנוגע\u0004 בצרעת, שהשוהה בבית המנוגע שיעור זמן הראוי לאכילת חצי ככר (\"פרס\") מיטמאים גם בגדיו. \u0003וחצי חציה,\u0004 רבע ככר כזו, הוא השיעור של אוכל \u0003לפסול את הגוייה.\u0004 שהאוכל שיעור זה של אוכל טמא, גזרו חכמים שיטמא גופו. \u0003וחצי חצי חציה,\u0004 שמינית ככר כזו, הוא השיעור הקטן ביותר של אוכל הראוי \u0003לקבל טומאת אוכלין.\u0004","ומעתה נברר, משנתנו כאן \u0003מני\u0004 \u0005[\u0006כדעת \u0005מי היא]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 תאמר שהיא כשיטת \u0003ר' יוחנן בן ברוקא,\u0004 שלדעתו מזון סעודה אחת הוא רבע קב, הרי רק \u0003תמני הויין\u0004 \u0005[שמונה\u0006 סעודות \u0005הן]\u0006 בשני קבי חיטים, והרי האשה צריכה לפחות ארבע עשרה סעודות בשבוע! \u0003ואי\u0004 \u0005[ואם]\u0006 היא כשיטת \u0003ר' שמעון\u0004 ששיעור מזון סעודה אחת הוא תשיעית הקב, הלא בשני קבין \u0003תמני סרי הויין\u0004 \u0005[שמונה עשרה\u0006 סעודות \u0005הן]\u0006 יותר מכדי צורכה!","ומשיבים: \u0003לעולם\u0004 יש לומר שמשנתנו כשיטת \u0003ר' יוחנן בן ברוקא, וכדאמר\u0004 \u0005[וכפי שאמר]\u0006 \u0003רב חסדא\u0004 בענייננו: שאף שאמר שיעור מסויים, הרי זה הוא המחיר הסיטונאי, ואילו הלוקח יש לו בפעל פחות, כי \u0003צא\u0004 (הפחת) \u0003מהן שליש לחנווני.\u0004 וכן, \u0003הכא נמי אייתי תילתא שדי עלייהו\u0004 \u0005[כאן גם כן הבא שליש\u0006 לחשבון הסעודות שיש בשיעור זה \u0005והוסף עליהן].\u0006 ומקשים: \u0003אכתי תרתי סרי הויין\u0004 \u0005[עדיין שתים עשרה הן]\u0006 אם מוסיפים שליש (מבחוץ, שהוא מחצית השיעור), על שמונה סעודות. והרי היא צריכה ארבע עשרה! ומשיבים: הרי \u0003אוכלת עמו לילי שבת\u0004 משלו ואין סעודה זו מן החשבון.","ומקשים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 ומפרש את הביטוי הזה במשנה שכוונתו היא \u0003אכילה ממש. אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003אכילה\u0004 זו בלילי שבת היא לשון נקיה להגדרת \u0003תשמיש, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 \u0003ועוד,\u0004 אף אם היא אוכלת סעודה אחת משלו בלילי שבת, הלא \u0003תליסר הויין\u0004 \u0005[שלוש עשרה הן]\u0006 ועדיין חסרה לה סעודה אחת! \u0003אלא\u0004 צריכים לומר \u0003כדאמר\u0004 \u0005[כפי שאמר]\u0006 \u0003רב חסדא\u0004 שם בהסבר דברי ר' יוחנן בן ברוקה, \u0003צא מהן\u0004 לא שליש אלא \u0003מחצה לחנווני. הכי נמי\u0004 \u0005[כך גם כן]\u0006 \u0003אתיא פלגא ושדי עלייהו\u0004 \u0005[הבא חצי והטל עליהן],\u0006 ונמצא שיש כאן לא שמונה אלא שש עשרה סעודות.","ומעירים: \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003רב חסדא\u0004 על דברי \u0003רב חסדא,\u0004 שפעם אחת הוא אומר שמוסיפים שליש, ופעם אחרת שמוסיפים חצי! ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003הא באתרא דיהבי ציבי\u0004 \u0005[זה במקום שנותנים\u0006 גם דמי \u0005עצים]\u0006 עבור אפיית הלחם, \u0003הא באתרא\u0004 \u0005[זה במקום]\u0006 ש\u0003לא יהבי ציבי\u0004 \u0005[נותנים\u0006 דמי \u0005עצים].\u0006","אחרי שיישבנו את דברי ר' חסדא, חוזרים לשיטת ר' יוחנן בן ברוקא ומקשים: \u0003אי הכי\u0004 \u0005[אם כן]\u0006 בפונדיון אחד במחיר סיטונאי, מספר הסעודות לדברי ר' יוחנן לפי הערתו של רב חסדא \u0003שיתסרי הויין\u0004 \u0005[שש עשרה\u0006 סעודות \u0005הן]\u0006 וזהו יותר מן השיעור שהוקצב במשנתנו. ולפי זה משנתנו \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 האם \u0003כ\u0004דעת \u0003ר' חידקא,\u0004 ש\u0003אמר: ארבע סעודות חייב אדם לאכול בשבת.\u0004 ונמצא שיש שתים עשרה סעודות בימות השבוע, ועוד ארבע לשבת?","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כדעת \u0003רבנן\u0004 \u0005[חכמים],\u0006 אלא \u0003דל חדא לארחי ופרחי\u0004 \u0005[הורד אחת בשביל אורחים ומזדמנים],\u0006 שבכל זאת אי אפשר לצמצם לה רק כדי מזונה שלה בדיוק.","ואומרים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שהגעת לכך]\u0006 להסבר זה שאין נותנים לה רק כפי מזונה בצמצום, \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו כדעת \u0003ר' שמעון\u0004 שיש בשני קבים מזון שמונה עשרה סעודות, ונפרש כי \u0003לרבנן\u0004 \u0005[ל\u0006דברי \u0005חכמים]\u0006 האומרים שיש שלוש סעודות בשבת, מכל מקום עדיין ניתן לקבל את דבריהם ולומר כי \u0003דל תלת לארחי ופרחי\u0004 \u0005[הורד שלוש\u0006 מהסעודות \u0005בשביל אורחים ומזדמנים],\u0006 ו\u0003ל\u0004דעת \u0003ר' חידקא\u0004 שחייבת בארבע סעודות בשבת \u0003דל תרתי לארחי ופרחי\u0004 \u0005[הורד שתים לאורחים ומזדמנים],\u0006 ואם כן אפשר לפרש את הדברים לכל השיטות.","שנינו במשנה ש\u0003אמר ר' יוסי: לא פסק שעורין\u0004 אלא ר' ישמעאל שהיה סמוך לאדום. ותוהים: \u0003אלא באדום הוא דאכלין\u0004 \u0005[שאוכלים]\u0006 \u0003שעורים, בכולי עלמא\u0004 \u0005[בכל העולם]\u0006 \u0003לא אכלי\u0004 \u0005[אוכלים],\u0006 והרי היה זה מאכל עניים בכל מקום! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003לא פסק שעורים\u0004 בשיעור \u0003כפלים\u0004 מן השיעור שנאמר \u0003בחטין אלא ר' ישמעאל שהיה סמוך לאדום, מפני ששעורין אדומיות רעות הן,\u0004 ואילו במקום אחר ההבדל בין שעורים לחיטים אינו גדול כל כך.","עוד שנינו במשנה: \u0003ונותן לה\u0004 עוד \u0003חצי קב קיטנית\u0004 ושמן וכו'. ומעירים: \u0003ואילו יין לא קתני\u0004 \u0005[שנה],\u0006 שאינו חייב לתת לה. הרי זה \u0003מסייע ליה\u0004 \u0005[לו]\u0006 ל\u0003ר' אלעזר,\u0004 ש\u0003אמר ר' אלעזר\u0004"],["\u0003אין פוסקין יינות לאשה, ואם תאמר:\u0004 והרי נאמר \u0003\"אלכה אחרי מאהבי נתני לחמי ומימי צמרי ופשתי שמני ושקויי\"\u0004 (הושע ב, ז), ולכאורה \"שיקויי\" אלה יין הם, ומשמע לכאורה שהאשה מקבלת כרגיל יין — יש לפרש כי \"שיקויי\" הם \u0003דברים שהאשה משתוקקת עליהן, ומאי נינהו\u0004 \u0005[ומה הם] —\u0006 \u0003תכשיטין,\u0004 ולא שיקויים כמשמעם.","\u0003דרש ר' יהודה איש כפר נביריא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003איש כפר נפור חיל: מנין שאין פוסקין יינות לאשה — שנאמר: \"ותקם חנה אחרי אכלה בשילה ואחרי שתה\"\u0004 (שמואל א' א, ט), נאמר \u0003\"שתה\" ולא \"שתת\",\u0004 כלומר, שהיא אכלה אבל לא שתתה יין, ו\"שתה\" משמעו — שבעלה הוא ששתה.","ותוהים: \u0003אלא מעתה\u0004 לפי דיוק זה \u0003\"אכלה\" — ולא אכל,\u0004 שמשמע שרק היא אכלה, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר?! ומשיבים: \u0003אנן מדשני קרא בדבוריה קאמרינן\u0004 \u0005[אנחנו מ\u0006פני \u0005ששינה הכתוב בדיבורו אנו אומרים]\u0006 ומזה אנו מדייקים. \u0003מכדי בגוה קא עסיק ואתי\u0004 \u0005[הרי בה עוסק\u0006 הכתוב \u0005והולך]\u0006 \u0003מאי טעמא שני\u0004 \u0005[מה טעם שינה]\u0006 ולא אמר \"אכלה ושתותה\", אלא \u0003שמע מינה\u0004 \u0005[למד ממנה],\u0006 מדיוק הלשון \u0003\"שתה\"\u0004 שהיה זמן שתיה, \u0003ולא שתת\u0004 \u0005[שתתה]\u0006 היא בעצמה.","\u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 היתה האשה \u0003רגילה\u0004 בשתיית יין — \u0003נותנין לה,\u0004 והרי שפוסקים יינות לאשה! ודוחים: אשה ה\u0003רגילה\u0004 בשתיית יין \u0003שאני\u0004 \u0005[שונה],\u0006 ש\u0003אמר רב חיננא בר כהנא אמר שמואל:\u0004 אם אשה \u0003רגילה\u0004 לשתות יין — \u0003נותנין לה כוס אחד. שאינה רגילה — נותנין לה שני כוסות.\u0004","ותוהים: \u0003מאי קאמר\u0004 \u0005[מה אומר]?!\u0006 הרי זה היפך הסברה! \u0003אמר אביי: הכי קאמר\u0004 \u0005[כך אומר]:\u0006 אם היתה \u0003רגילה\u0004 בשתיה, אזי \u0003בפני בעלה\u0004 — נותנים לה \u0003שני כוסות, שלא בפני בעלה — נותנין לה כוס אחד\u0004 בלבד. ואם \u0003אינה רגילה\u0004 בשתיית יין, אזי \u0003בפני בעלה\u0004 — אין נותנים לה \u0003אלא כוס אחד\u0004 בלבד, \u0003שלא בפני בעלה — אין נותנין לה\u0004 יין \u0003כל עיקר.\u0004","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 שמה שנאמר בברייתא, כוונתו: \u0003רגילה — נותנין לה\u0004 יין, לא כדי לשתות, אלא \u0003לציקי קדירה.\u0004 ש\u0003אמר ר' אבהו אמר ר' יוחנן: מעשה בכלתו של נקדימון בן גוריון שפסקו לה חכמים סאתים יין לציקי קדרה מערב שבת לערב שבת.\u0004 ברכה אותם ו\u0003אמרה להן: כך תפסקו לבנותיכם,\u0004 כמות מרובה שכזו. \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 כלתו זו של נקדימון בן גוריון \u0003שומרת יבם היתה, ולא ענו אחריה אמן,\u0004 משום שלא רצו לענות אמן שיגיעו בנותיהן למצב זה שיש בו צד פורענות.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003כוס אחד\u0004 של יין — \u0003יפה לאשה. שנים — ניוול הוא\u0004 לה, שמתחילה להשתכר. \u0003שלשה\u0004 — מגיעה לתאווה ואז אף \u0003תובעת\u0004 תשמיש \u0003בפה.\u0004 שתתה \u0003ארבעה\u0004 כוסות יין — הריהי מגיעה למצב ש\u0003אפילו חמור תובעת בשוק ואינה מקפדת\u0004 עוד למי תיבעל. \u0003אמר רבא: לא שנו\u0004 שאין נותנים יין לאשה \u0003אלא\u0004 כ\u0003שאין בעלה עמה, אבל\u0004 כאשר \u0003בעלה עמה, לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 צד איסור, שאם תתאוה הרי בעלה עמה.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003חנה\u0004 ש\u0003בעלה עמה הואי\u0004 \u0005[היה]\u0006 ובכל זאת ממנה למדים שאין האשה שותה! ומשיבים: \u0003אכסנאי שאני\u0004 \u0005[אורח\u0006 דינו \u0005שונה].\u0006 ש\u0003אמר רב הונא: מנין לאכסנאי שאסור בתשמיש המטה — שנאמר: \"וישכמו בבקר וישתחוו לפני ה' וישבו ויבאו אל ביתם הרמתה וידע אלקנה את חנה אשתו ויזכרה ה'\"\u0004 (שמואל א' א, יט), משמע: \u0003השתא\u0004 \u0005[עכשיו]\u0006 כשבאו הביתה — \u0003אין\u0004 \u0005[כן]\u0006 ידע אותה, אבל \u0003מעיקרא\u0004 \u0005[מתחילה] —\u0006 \u0003לא,\u0004 משמע שאין זה ראוי לאכסנאי לשמש מטתו, ולכן לא שתתה שם יין, כדי שלא תבוא לידי תביעת תשמיש.","מסופר: \u0003חומא דביתהו\u0004 \u0005[אשתו,\u0006 אלמנתו\u0005]\u0006 של \u0003אביי, אתאי לקמיה\u0004 \u0005[באה לפני]\u0006 \u0003רבא\u0004 שהיה דיין בעיר, \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003פסוק לי מזוני\u0004 \u0005[מזונות]\u0006 המגיעים לי מן היורשים! \u0003פסק לה\u0004 מזונות. אמרה לו: \u0003פסוק לי\u0004 גם \u0003חמרא\u0004 \u0005[יין]!\u0006 \u0003אמר לה: ידענא ביה\u0004 \u0005[יודע אני בו]\u0006 \u0003בנחמני,\u0004 אביי בעלך, ש\u0003לא הוה שתי חמרא\u0004 \u0005[היה שותה יין],\u0006 ולכן, כיון שבחייו לא היית רגילה בכך — אין נותנים לך גם אחרי מותו. \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003חיי דמר\u0004 \u0005[\u0006ב\u0005חיי אדוני]\u0006 \u0003דהוי משקי ליה בשופרזי כי האי\u0004 \u0005[שהיה משקה אותי בכוסות\u0006 גדולות \u0005כמו זה]\u0006 והראתה לו בידיה כמה גדולות היו הכוסות. \u0003בהדי דקא מחויא ליה\u0004 \u0005[תוך שהיתה מראה לו]\u0006 בידיה את גודל הכוסות \u0003איגלי דרעא\u0004 \u0005[התגלתה זרועה]\u0006 מן הבגד, והיתה יפה כל כך ש\u0003נפל נהורא בבי דינא\u0004 \u0005[נעשה אור בבית הדין].\u0006","\u0003קם רבא, על לביתיה\u0004 \u0005[נכנס לביתו]\u0006 \u0003תבעה ל\u0004אשתו \u0003בת רב חסדא\u0004 לתשמיש. \u0003אמרה ליה\u0004 \u0005[לו]\u0006 \u0003בת רב חסדא,\u0004 אשתו: \u0003מאן הוי האידנא בבי דינא\u0004 \u0005[מי היה עכשיו בבית הדין]?\u0006 שהבינה שאין הדבר רגיל, ובודאי אירע משום שראה איזושהי אשה בבית הדין. \u0003אמר לה: חומא דביתהו\u0004 \u0005[אשתו]\u0006 של \u0003אביי\u0004 היתה בבית הדין. קינאה בה וחששה, \u0003נפקא אבתרה\u0004 \u0005[יצאה\u0006 בת רב חסדא \u0005אחריה]\u0006 אחרי חומא, \u0003מחתא לה בקולפי דשידא\u0004 \u0005[הכתה אותה במנעול של ארגז]\u0006 \u0003עד דאפקה לה מכולי\u0004 \u0005[שהוציאה אותה מכל\u0006 העיר\u0005]\u0006 \u0003מחוזא.\u0004 וכך \u0003אמרה לה: קטלת ליך תלתא\u0004 \u0005[הרגת לך שלושה\u0006 גברים\u0005],\u0006 כי אביי היה בעלה השלישי, אחר שמתו שני בעליה הראשונים, \u0003ואתת למיקטל אחרינא\u0004 \u0005[ובאת להרוג אחר]\u0006 גם את רבא בעלי?! שהראית לו את יופיך, ויבוא לשאת אותך.","כעין זה מסופר: \u0003דביתהו\u0004 \u0005[אשתו]\u0006 של \u0003רב יוסף בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא אתאי לקמיה\u0004 \u0005[באה לפני]\u0006 \u0003רב נחמיה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף\u0004 לדין. \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003פסוק לי מזוני\u0004 \u0005[מזונות]!\u0006 \u0003פסק לה\u0004 כמה שפסק. אמרה לו: \u0003פסוק לי\u0004 גם \u0003חמרא\u0004 \u0005[יין]!\u0006 \u0003פסק לה. אמר לה: ידענא בהו\u0004 \u0005[יודע אני בהם]\u0006 \u0003בבני\u0004 העיר \u0003מחוזא דשתו חמרא\u0004 \u0005[ש\u0006נוהגים \u0005לשתות יין]\u0006 ומגיע גם לך לקבל יין.","בדומה לזה \u0003דביתהו\u0004 \u0005[אשתו]\u0006 של \u0003רב יוסף בריה\u0004 \u0005[בנו]\u0006 של \u0003רב מנשיא מ\u0004העיר \u0003דויל אתאי לקמיה\u0004 \u0005[באה לפני]\u0006 \u0003רב יוסף. אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003פסוק לי מזוני\u0004 \u0005[מזונות]\u0006 מנכסי בעלי! \u0003פסק לה.\u0004 אמרה לו: \u0003פסוק לי חמרא\u0004 \u0005[יין]!\u0006 \u0003פסק לה.\u0004 הוסיפה ואמרה: \u0003פסוק לי שיראי\u0004 \u0005[\u0006כלי \u0005משי]!\u0006 \u0003אמר לה: שיראי למה\u0004 לך? \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003לך ולחברך ולחברורך\u0004 \u0005[ולחברי חבריך],\u0006 שגם אחרי שהתאלמנתי איני צריכה להתבזות ממך ומחבריך.","שנינו במשנה: \u0003ונותן לה מטה ומפץ\u0004 (מחצלת רכה) ומחצלת קשה. שואלים: \u0003מפץ ומחצלת למה לה דיהב\u0004 \u0005[שנותן]\u0006 \u0003לה,\u0004 לשם מה צריכה היא אותם אם יש לה מיטה? \u0003אמר רב פפא:\u0004 מדובר \u0003באתרא דנהיגי דמלו פוריא בחבלי\u0004 \u0005[במקום שנוהגים שממלאים\u0006 את \u0005המיטה,\u0006 יוצרים את המיטה, על ידי \u0005חבלים],\u0006 \u0003דמבגר לה\u0004 \u0005[ש\u0006הם מצערים אותה ו\u0005מזקינים אותה],\u0006 ולכן מכסה את החבלים במפץ, כעין מזרון, ועליו יכולה לישון.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין נותנין לה כר וכסת\u0004 לעניה שבישראל. \u0003משום ר' נתן אמרו: נותנין לה כר וכסת.\u0004 ומבררים: \u0003היכי דמי\u0004 \u0005[במה מדובר],\u0006 \u0003אי דאורחה\u0004 \u0005[אם שדרכה\u0006 בכר וכסת\u0005],\u0006 \u0003מאי טעמא\u0004 \u0005[מה\u0006 אם כן \u0005הטעם]\u0006 של ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 שאמר שאין נותנים? \u0003ואי דלאו אורחה\u0004 \u0005[ואם שאין\u0006 זו \u0005דרכה]\u0006 בכר וכסת, \u0003מאי טעמא\u0004 \u0005[מה\u0006 אם כן \u0005הטעם]\u0006 של \u0003ר' נתן\u0004 שנותנים?","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003כגון דאורחיה דידיה ולאו אורחה דידה\u0004 \u0005[שדרכו\u0006 לישון כך \u0005ואין דרכה\u0006 בכך\u0005].\u0006 ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003סבר\u0004 כי הבעל \u0003אמר\u0004 \u0005[\u0006יכול \u0005לומר]\u0006 \u0003לה: כי אזילנא שקילנא להו, וכי אתינא, מייתינא להו בהדאי\u0004 \u0005[כאשר אני הולך\u0006 ממך \u0005אקח אותם\u0006 את המצעים שלי, \u0005וכאשר אבוא, אביא אותם אתי].\u0006 \u0003ור' נתן סבר: אמרה ליה\u0004 \u0005[\u0006יכולה היא \u0005לומר לו]:\u0006 \u0003זימנין דמיתרמי\u0004 \u0005[פעמים שמזדמן]\u0006 שאתה מגיע בשעת \u0003בין השמשות ולא מצית מייתי להו\u0004 \u0005[תוכל להביא אותם]\u0006 \u0003ושקלת להו לדידי ומגנית לי על ארעא\u0004 \u0005[ותיקח\u0006 את המצעים \u0005שלי ואותי תשכיב על הארץ]\u0006 ולכן צריכה אני כר וכסת נוספים.","שנינו במשנה כי בין השאר \u0003נותן לה כפה,\u0004 ונותן לה מנעלים בכל חג, ובגדים אחת לשנה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי:\u0004"],["\u0003האי תנא\u0004 \u0005[תנא זה]\u0006 יוצר מצב מוזר של \u0003שליח ערטלאי ורמי מסאני\u0004 \u0005[\u0006מופשט \u0005עירום ונועל נעליים],\u0006 שהרי בגדים נותנים לה רק פעם בשנה ונעליים שלוש פעמים! \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: ה\u0003תנא, במקום הרים קאי\u0004 \u0005[עומד,\u0006 מדבר\u0005],\u0006 ש\u0003לא סגיא\u0004 \u0005[דיה]\u0006 \u0003בלא תלתא זוגי מסאני\u0004 \u0005[שלושה זוגות נעליים],\u0006 שבהרים הם בלים מהר. \u0003ואגב אורחיה קא משמע לן\u0004 \u0005[ודרך אגב השמיע לנו]\u0006 \u0003דניתבינהו ניהלה\u0004 \u0005[שייתן לה אותם]\u0006 \u0003במועד כי היכי דניהוי\u0004 \u0005[כדי שתהיה]\u0006 \u0003לה שמחה בגוייהו\u0004 \u0005[בהם]\u0006 בחג. אמרנו שנותן לה \u0003כלים של חמשים זוז. אמר אביי:\u0004 הכוונה היא \u0003חמשים זוזי פשיטי\u0004 \u0005[זוזים פשוטים\u0006 של מדינה\u0005],\u0006 ששווים רק שמינית הזוז הרגיל. \u0003ממאי\u0004 \u0005[ממה]\u0006 מסיק הוא את זה? \u0003מדקתני\u0004 \u0005[מ\u0006מה \u0005ששנה]\u0006 \u0003במה דברים אמורים — בעני שבישראל, אבל במכובד — הכל לפי כבודו. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר \u0003חמשים זוז ממש\u0004 — \u0003עני, חמשים זוז מנא ליה\u0004 \u0005[מניין לו]?\u0006 שהרי עני מוגדר כמי שאין לו מאתיים זוז פשוטים, וכיצד יכול לתת חמישים זוז ממש לאשתו? \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 שמדובר ב\u0003חמשים זוזי פשיטי\u0004 \u0005[זוזים פשוטים\u0006 של מדינה\u0005].\u0006","","שנינו במשנה: \u0003ואין נותנין לה לא\u0004 בגדים \u0003חדשים\u0004 בקיץ ולא בלויים בחורף, אלא נותן לה חדשים בימות החורף ומשתמשת בבלאותיהם בחורף, והבגדים השחוקים שלה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מותר מזונות\u0004 שלא אכלה הם \u0003לבעל,\u0004 ואינם נשארים ביד האשה. \u0003מותר בלאות — לאשה.\u0004 ושואלים: \u0003מותר בלאות לאשה, למה לה\u0004 בלאות אלה? \u0003אמר רחבה: שמתכסה בהן בימי נדתה, כדי שלא תתגנה על בעלה,\u0004 שאם לובשת אותם בגדים הרגילים גם בזמן הנידות מתגנה היא בעיניו לאחר מכן.","\u0003אמר אביי: נקטינן\u0004 \u0005[מוחזק לנו]\u0006 \u0003מותר בלאות אלמנה — ליורשיו\u0004 של הבעל. כי \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 שאמרנו שהטעם ש\u0003לא תתגני באפיה\u0004 \u0005[תתגנה בפניו],\u0006 \u0003הכא\u0004 \u0005[כאן,\u0006 כשמת\u0005] —\u0006 \u0003תתגני ותתגני\u0004 \u0005[תתגנה ותתגנה]\u0006 שהרי אין אנו צריכים לדאוג שתמצא חן בעיני היורשים.","שנינו במשנה ש\u0003נותן לה מעה כסף ו\u0004אוכלת עמו משבת לשבת. ושאלו: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אוכלת\"\u0004 האמור כאן? \u0003רב נחמן אמר: אוכלת ממש,\u0004 שסועדת אתו פעם אחת בשבוע. \u0003רב אשי אמר:\u0004 הכוונה היא \u0003תשמיש.\u0004","\u0003תנן\u0004 \u0005[שנינו]:\u0006 \u0003אוכלת עמו\u0004 ב\u0003לילי שבת. בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 כי הכוונה ל\u0003אכילה\u0004 ממש — \u0003היינו דקתני\u0004 \u0005[הוא ששנה]\u0006 \u0003\"אוכלת\", אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שהכוונה היא ל\u0003תשמיש, מאי\u0004 \u0005[מה\u0006 לשון\u0005]\u0006 \u0003\"אוכלת\"?\u0004 מסבירים: \u0003לישנא מעליא\u0004 \u0005[לשון מעולה,\u0006 נקיה, היא\u0005],\u0006 לגבי תשמיש, \u0003כדכתיב\u0004 \u0005[כפי שנאמר]:\u0006 \u0003\"\u0004כן דרך אשה מנאפת \u0003אכלה ומחתה פיה ואמרה לא פעלתי און\"\u0004 (משלי ל, כ).","\u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 \u0003רבן שמעון בן גמליאל אומר\u0004 וחולק על משנתנו: \u0003אוכלת בלילי שבת ושבת. בשלמא למאן דאמר\u0004 \u0005[נניח למי שאומר]\u0006 כי הכוונה ל\u0003אכילה\u0004 ממש — \u0003היינו דקתני\u0004 \u0005[זה ששנה]\u0006 \u0003\"ושבת\",\u0004 שאוכלת אתו גם סעודת יום השבת. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי הכוונה ל\u0003תשמיש\u0004 — \u0003תשמיש ב\u0004יום ה\u0003שבת מי איכא\u0004 \u0005[האם יש]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב הונא: ישראל קדושים הן, ואין משמשין מטותיהן ביום!\u0004 ומשיבים: \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003רבא:\u0004 שאפילו ביום — \u0003בבית אפל מותר.\u0004","שנינו במשנה: \u0003ואם היתה מניקה,\u0004 פוחתים לה מעבודתה, ומוסיפים על מזונותיה. \u0003דרש ר' עולא רבה\u0004 \u0005[הגדול]\u0006 \u0003אפיתחא דבי נשיאה\u0004 \u0005[על פתח בית הנשיא]:\u0006 \u0003אף על פי שאמרו אין\u0004 חובה על \u0003אדם\u0004 שיהא \u0003זן את בניו ובנותיו כשהן קטנים, אבל זן קטני קטנים,\u0004 שלגביהם בודאי יש לו חיוב.","ו\u0003עד כמה\u0004 נקראים \"קטני קטנים\" — \u0003עד בן שש, כ\u0004דברי \u0003רב אסי.\u0004 ש\u0003אמר רב אסי: קטן בן שש יוצא בעירוב אמו\u0004 אם עשתה עירוב לצד מסויים, ולא בעירוב שעשה אביו משום שהוא נחשב כטפל לאמו.","\u0003ממאי\u0004 \u0005[ממה,\u0006 מהיכן\u0005]\u0006 אנו יודעים את ההלכה הזו של ר' עולא? \u0003מדקתני\u0004 \u0005[ממה ששנה]\u0006 \u0003היתה\u0004 האשה \u0003מניקה — פוחתין לה ממעשה ידיה ומוסיפין לה על מזונותיה. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003משום דבעי למיכל בהדה\u0004 \u0005[ש\u0006הוא, התינוק, \u0005צריך לאכול\u0006 יחד \u0005איתה]?\u0006 משמע שלצורך התינוק הקטן חייב הבעל לתת! ודוחים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 מוסיף לה מזונות לא משום התינוק אלא \u0003משום\u0004 ש\u0003חולה היא\u0004 מפני חולשתה בזמן ההנקה.","ודוחים: \u0003אם כן ליתני\u0004 \u0005[שישנה]\u0006 \u0003אם היתה חולה, מאי\u0004 \u0005[מה]\u0006 טעם תלה בזה ש\u0003אם היתה מניקה?\u0004 אלא ודאי משום התינוק הוא. ודוחים: \u0003ודלמא הא קא משמע לן\u0004 \u0005[ושמא זה\u0006 בא \u0005להשמיע לנו]\u0006 ש\u0003סתם מניקות חולות נינהו\u0004 \u0005[הן],\u0006 וכל שכן חולה ממש שמוסיף לה, ואין מכאן הוכחה שהתינוק טפל לאמו. \u0003איתמר\u0004 \u0005[נאמר]\u0006 \u0003אמר ר' יהושע בן לוי: מוסיפין לה\u0004 למניקה \u0003יין,\u0004 לפי \u0003שהיין יפה לחלב.\u0004","","\u0003מציאת האשה ומעשה ידיה\u0004 שייכים \u0003לבעלה. וירושתה,\u0004 אם נפלה לה ירושה — \u0003הוא אוכל פירות\u0004 נכסי הירושה \u0003בחייה. בושתה,\u0004 אם ביישו אותה ונתחייב המבייש לשלם, \u0003ו\u0004כן \u0003פגמה\u0004 אם הזיק אותה אדם ופגם בה — הרי הוא \u0003שלה.\u0004 \u0003ר' יהודה בן בתירא אומר: בזמן\u0004 שהיה זה פגם \u0003שבסתר\u0004 (בחלק גוף לא חשוף) — מגיעים \u0003לה שני חלקים\u0004 מתשלומי הפגם, \u0003ולו\u0004 חלק \u0003אחד,\u0004 שהרי פגם זה פוגע גם בו. \u0003ובזמן ש\u0004היה זה \u0003ב\u0004מקום \u0003גלוי — לו שני חלקים,\u0004 שהוא מתבייש בה ברבים, \u0003ולה\u0004 רק חלק \u0003אחד.\u0004 החלק \u0003שלו — ינתן מיד\u0004 לידו, \u0003ושלה — ילקח\u0004 (ייקנה) \u0003בהן קרקע\u0004 שיהיה רכושה, \u0003והוא אוכל פירות\u0004 קרקע זו.","","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 במשנה זו? הלא \u0003תנינא\u0004 \u0005[שנינו]\u0006 כבר במשנה קודמת ש\u0003האב זכאי בבתו בקידושיה: בכסף, בשטר ובביאה,\u0004 וכן \u0003זכאי במציאתה ובמעשה ידיה ובהפרת נדריה. מקבל את גיטה, ואינו אוכל פירות\u0004 נכסיה \u0003בחייה.\u0004 אם \u0003נישאת\u0004 האשה לבעל — \u0003יתר עליו הבעל\u0004 בזכויותיו, \u0003ש\u0004מלבד כל אלו \u0003הוא אוכל פירות\u0004 נכסיה \u0003בחייה.\u0004 ואם כן הדברים האמורים במשנה כבר נאמרו קודם!","ומשיבים: משום \u0003בושתה ופגמה איצטריכא ליה\u0004 \u0005[הוצרכה לו]\u0006 לשנות, מכיון שיש כאן חידוש, לגבי \u0003פלוגתא\u0004 \u0005[מחלוקת]\u0006 של \u0003ר' יהודה בן בתירא ורבנן\u0004 \u0005[וחכמים]\u0006 שבמשנתנו, כיצד מתחלק סכום זה בין הבעל והאשה.","\u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003רבא\u0004 ברייתא זו: \u0003מציאת האשה לעצמה. ר' עקיבא אומר: לבעלה. אמר ליה\u0004 \u0005[לו]\u0006 רבא: הברייתא הזו תמוהה, \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003ומה העדפה,\u0004 אם האשה עושה מלאכה יותר מן השיעור שקצבו לה חכמים,"],["\u0003מעשה ידיה היא\u0004 ויש לבעל זכות בה, ובכל זאת \u0003אמר ר' עקיבא\u0004 שהיא \u0003לעצמה\u0004 — \u0003מציאתה\u0004 שאין לה קשר למעשה ידיה האם \u0003לא כל שכן\u0004 שהיא שלה?!","וראיה שזו היא שיטת ר' עקיבא בהעדפה — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 אמרה אשה לבעלה \u0003\"קונם\u0004 (נדר איסור, כעין הקדש) כל מה \u0003שאני עושה\u0004 יהא אסור \u0003לפיך\" — אינו צריך להפר\u0004 נדר זה, משום שאינו חל כלל, כי אין האשה יכולה לאסור על בעלה את הדברים שהיא מחוייבת לעשות עבורו. \u0003ר' עקיבא אומר: יפר, שמא תעדיף עליו יותר מן הראוי לו\u0004 ועל תוספת זו, שאיננה חייבת לעשות לו, חל נדרה של האשה. ומכאן משמע שמה שנחשב כהעדפה שייך לאשה! \u0003אלא איפוך\u0004 \u0005[הפוך]\u0006 את השיטות ושנה כך: \u0003מציאת האשה לבעלה. ר' עקיבא אומר: לעצמה.\u0004","ושואלים: \u0003והא כי אתא\u0004 \u0005[והרי כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יוחנן: בהעדפה שלא על ידי הדחק,\u0004 כאשר האשה עושה מלאכה יותר מן השיעור הקצוב מפני שבטבעה היא זריזה וחרוצה ואינו דורש ממנה מאמץ יתר — \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 שהעדפה כזו של ה\u0003בעל הוי\u0004 \u0005[היא],\u0006 \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003בהעדפה שעל ידי הדחק,\u0004 שהיא מתאמצת יותר מן הרגיל ועושה יותר; ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003סבר\u0004 שמותר זה שייך \u0003לבעלה, ור' עקיבא סבר\u0004 שהמותר שייך \u0003לעצמה.\u0004 ולפי זה אף בהעדפה אין ר' עקיבא סבור שהיא שייכת תמיד לאשה ואין צורך להפוך את השיטות! (רי\"ד). ומשיבים, \u0003אמר רב פפא: מציאתה — כהעדפה שעל ידי הדחק דמי\u0004 \u0005[נחשבת]\u0006 מאחר שהיא מגיעה לידיה רק בהזדמנות מיוחדת, יש לראותה כעין העדפה שבאה מתוך מאמץ מיוחד. וזוהי \u0003פלוגתא\u0004 \u0005[מחלוקת]\u0006 של \u0003ר' עקיבא ורבנן\u0004 \u0005[וחכמים].\u0006","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא: עשתה לו שתים\u0004 (שתי מלאכות) \u0003בבת אחת מהו?\u0004 האם דינן כהעדפה על ידי הדחק או לא? וכן \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבינא:\u0004 עשתה \u0003שלשה או ארבעה\u0004 דברים \u0003בבת אחת מהו?\u0004 השאלות הללו לא נפתרו, והריהן \u0003תיקו\u0004 \u0005[תעמודנה\u0006 במקומן.","שנינו במשנה ש\u0003בושתה ופגמה\u0004 שלה, ור' יהודה בן בתירא אומר שיש גם לבעל חלק בו. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא בר רב חנן\u0004 על שיטת ר' יהודה בן בתירא: \u0003אלא מעתה,\u0004 אם \u0003בייש סוסתו של חבירו, הכי נמי דבעי למיתן ליה\u0004 \u0005[כך גם כן\u0006 הוא \u0005שצריך לתת לו]\u0006 \u0003בושת?\u0004 על שאלה זו תוהים: \u0003ו\u0004כי \u0003סוס בר\u0004 \u0005[בן]\u0006 \u0003בושת הוא,\u0004 וכי אפשר לבייש אותו?! ומה הדמיון לאשה ששייך בה בושת! \u0003אלא\u0004 כך יש לנסח את השאלה: אם \u0003רקק בבגדו של חבירו הכי נמי דבעי למיתן ליה\u0004 \u0005[כך גם כן שצריך לתת לו]\u0006 \u0003בושת?\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הכי נמי\u0004 \u0005[כך\u0006 הוא \u0005גם כן],\u0006 שצריך לתת לו — \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003רקק, והגיע בו\u0004 בחבר \u0003הרוק,\u0004 או ש\u0003פרע\u0004 (חשף את שער) \u0003ראש האשה,\u0004 או ש\u0003העביר\u0004 (הוריד) את \u0003טליתו\u0004 (בגדו) של חבירו \u0003ממנו — חייב ליתן לו\u0004 קנס של \u0003ארבע מאות זוז,\u0004 משום שזו בושת מרובה. \u0003ואמר רב פפא:\u0004 לגבי רקיקה, \u0003לא שנו אלא\u0004 כשפגע הרוק \u0003בו, אבל\u0004 אם פגע הרוק \u0003בבגדו — פטור\u0004 היורק, ומדוע חייב לשלם לבעל כאשר ירק על את אשתו, והרי לא פגע הרוק בו! ודוחים: אין הדברים דומים, \u0003בבגדו לית ליה זילותא\u0004 \u0005[אין לו\u0006 בכך \u0005בושת],\u0006 אבל אם מביישים את \u0003אשתו אית\u0004 \u0005[יש]\u0006 \u0003לה זילותא\u0004 \u0005[זלזול]\u0006 הגורם גם לבעל להתבייש.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: אלא מעתה, בייש עני בן טובים\u0004 (ממשפחה מכובדת), \u0003דאית להו זילותא לכולהו\u0004 \u0005[שיש להם זלזול לכל]\u0006 \u0003בני משפחה, הכי נמי דבעי למיתן להו\u0004 \u0005[כך גם כן שצריך לתת להם]\u0006 \u0003בושת לכל בני משפחה?\u0004 שהרי לפי אותו עקרון, גם הם שותפים בכך. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם לאו גופייהו\u0004 \u0005[שם,\u0006 בן המשפחה \u0005אינו גופם]\u0006 ואינם יכולים לומר שהם עצמם נפגעו, ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003אשתו גופיה הואי\u0004 \u0005[\u0006כ\u0005גופו היא]\u0006 ודינם הוא כאדם אחד, ובושתה היא איפוא גם בושת לבעלה.","\u0003הפוסק\u0004 (הקוצב) סכום מסויים של \u0003מעות\u0004 כנדוניה \u0003לחתנו, ומת חתנו\u0004 לפני שקיבל את הנדוניה, ונפלה האשה לייבום לפני יבם, \u0003אמרו חכמים: יכול הוא\u0004 החותן \u0003שיאמר\u0004 ליבם: \u0003לאחיך הייתי רוצה ליתן\u0004 נדוניה זו, \u0003ולך אי אפשי ליתן\u0004 (אין רצוני לתת).","ומכאן ממשיכה המשנה בדרך חישובי הנדוניה והכתובה: \u0003פסקה\u0004 האשה \u0003להכניס לו\u0004 בנדונייתה \u0003אלף דינר\u0004 בכספים — \u0003הוא פוסק כנגדן\u0004 וכותב בכתובתה סכום של \u0003חמש עשרה מנה\u0004 (אלף וחמש מאות דינר), שהוא מוסיף עוד מחצית מן הסכום שקיבל, כיון שהוא יכול להשתמש בכסף זה, \u0003ו\u0004אילו \u0003כנגד השום\u0004 (דבר הניתן על פי הערכה), כלים וחפצים שהכלה מכניסה בנדוניה, והיו נוהגים בדרך כלל להגזים ולהפריז קצת בהערכת הדברים שהיא מביאה, לא רק שאינו מוסיף על סכום זה בכתובה, שהרי בחפצים אלה אינו יכול להרוויח דבר, אלא \u0003הוא פוסק פחות חומש\u0004 מן הסכום שהעריכו בו את החפצים, שהדרך היתה להפריז כדי חמישית על המחיר.","אולם אם היה החפץ \u0003שום\u0004 (מוערך) \u0003במנה ושוה\u0004 באמת \u0003מנה — אין לו אלא מנה\u0004 ואינו פוחת ממנו. אם היה \u0003שום במנה,\u0004 כלומר, שהוא כותב בכתובה מנה כנגד חפצים שהיא מביאה בנדוניה, \u0003היא נותנת שלשים ואחד סלע ודינר\u0004 (שהם מאה עשרים וחמישה דינרים) לפי ההערכה שעושים בביתה, שכפי שאמרנו שמוסיפים כדי חמישית — שוויים הוא באמת מנה. \u0003ו\u0004כן אם הוא פוסק \u0003בארבע מאות\u0004 דינר כנגד חפציה, \u0003היא נותנת חמש מאות\u0004 לפי ההערכה, השווים ארבע מאות לפי הערך האמיתי. ולעומת זאת \u0003מה\u0004"],["\u0003שחתן פוסק,\u0004 אם הוא פוסק כנגד הנדוניה שהביאה הכלה — \u0003הוא פוסק פחות חומש\u0004 בשטר הכתובה, שכותב בכתובה רק כנגד הערך הממשי של מה שהכניסה לו.","לגבי האמור במשנה שאין האב חייב לתת לחתן השני מה שהבטיח לחתן הראשון, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין צריך לומר\u0004 אם היה ה\u0003ראשון תלמיד חכם ו\u0004ה\u0003שני עם הארץ,\u0004 שיש לו טעם מדוע איננו רוצה לתת לשני כמו שנתן לראשון, \u0003אלא אפילו\u0004 היה ה\u0003ראשון עם הארץ ו\u0004ה\u0003שני תלמיד חכם, יכול\u0004 החותן \u0003לומר: לאחיך הייתי רוצה ליתן, לך אי אפשי\u0004 (אין רצוני) \u0003ליתן,\u0004 שהרי ההתחייבות היתה לגבי אדם מסויים.","שנינו במשנה מה היחס בין הנדוניה שמכניסה האשה והכסף שכותב הבעל בכתובה, ונשנו שם מקרים שונים: ש\u0003פסקה להכניס לו אלף דינר כו'.\u0004 ושואלים: אותם מקרים אחרונים \u0003היינו רישא\u0004 \u0005[הרי הם ההתחלה]\u0006 ודיינו בדוגמא שהביאו לגבי אלף דינר! ומסבירים: \u0003תנא שומא רבה וקתני שומא זוטא\u0004 \u0005[שנה,\u0006 אמר, \u0005שומה\u0006 הערכה \u0005גדולה\u0006 של ערך רב \u0005ושנה שומה קטנה,\u0006 של ערך מועט\u0005]\u0006 ללמדנו שאין הבדל בדין. שאף על פי שלכאורה היה מקום לומר שרק בשומה גדולה נוהגים השמאים להוסיף על השומה כדי חומש ולא על הקטנה, על כן השמיע לנו שהוא הדין גם בשומה קטנה. וכן \u0003תנא שומא דידיה\u0004 \u0005[שנה שומה\u0006 שהוא עושה מ\u0005שלו]\u0006 וכיצד צריכים להעריך לפי זה מה שהיא חייבת לתת, ולהיפך, \u0003וקתני שומא דידה\u0004 \u0005[ושנה\u0006 את \u0005השומה שלה]\u0006 שהיא נותנת תחילה ומה הוא צריך לכתוב כנגד זה.","\u0003פסקה להכניס לו כספים\u0004 ולא חפצים, בנדוניה — הרי \u0003סלעה\u0004 (שהוא ארבעה דינרים) \u0003נעשה\u0004 לגבי התחייבות הבעל בכתובה \u0003ששה דינרין.\u0004 כפי ששנינו שהבעל מוסיף כדי חצי, משום שהוא מרויח בכספים אלה. ועוד: \u0003החתן מקבל עליו\u0004 לתת \u0003עשרה דינרים לקופה\u0004 לצרכי האשה \u0003לכל מנה ומנה\u0004 שהיא מכניסה לו. \u0003רבן שמעון בן גמליאל אומר: הכל כמנהג המדינה.\u0004","על הקטע הראשון שסלעה נעשה שישה דינרים תוהים: \u0003היינו\u0004 \u0005[הרי זה]\u0006 זהה למה ששנינו במשנה הקודמת, שאם היא מביאה בנדוניה אלף דינר הוא \u0003פוסק כנגדם חמשה עשר מנה\u0004 שהם אלף וחמש מאות דינר!","ומשיבים: \u0003תנא עסקא רבה, ותנא עסקא זוטא\u0004 \u0005[שנה עסק גדול, ושנה עסק קטן].\u0006 \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שייאמרו שניהם. \u0003דאי תנא עסקא רבה\u0004 \u0005[שאילו היה שונה עסק גדול] —\u0006 היינו חושבים שרק בכגון זה מוסיפים משום \u0003דנפיש רווחא\u0004 \u0005[שמרובה הרווח\u0006 בו\u0005],\u0006 \u0003אבל עסקא זוטא דזוטר רווחא\u0004 \u0005[עסק קטן שקטן\u0006 בו \u0005הרווח] —\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמר הדבר גם במשנה שלנו. ומצד שני, \u0003ואי אשמעינן עסקא זוטא\u0004 \u0005[ואם היה השמיע לנו\u0006 רק ב\u0005עסק קטן]\u0006 במשנתנו, היינו אומרים \u0003דזוטר זיונא\u0004 \u0005[שמועטת ההוצאה]\u0006 לגביו, לפיכך מוסיפים כדי מחציתו, \u0003אבל עסקא רבה דנפיש זיונא\u0004 \u0005[עסק גדול שמרובות ההוצאות\u0006 עליו\u0005]\u0006 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יוסיף הבעל כל כך, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שניהם, לומר שהוא הדין, ובכל מקרה מוסיפים מחצית על השומה.","שנינו במשנה ש \u0003החתן מקבל עליו עשרה דינר לקופה.\u0004 שואלים: \u0003מאי\u0004 \u0005[מה היא]\u0006 \u0003קופה\u0004 זו? \u0003אמר רב אשי: קופה של בשמים,\u0004 כלומר, להוצאות על תמרוקים ומיני בשמים. \u0003ואמר רב אשי: לא נאמרו דברים הללו אלא בירושלים,\u0004 ששם היו הנשים נוהגות להתקשט בהרבה בשמים.","אולם הדברים האמורים במשנה לכל מנה ומנה סתומים הם ולכן \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי\u0004 האם הכוונה היא \u0003במנה הנישום,\u0004 כלומר, במנה ששמו אותו לאשה בנדונייתה (שמוסיפים חומש לשבחה), \u0003או במנה המתקבל,\u0004 הסכום שכותב הבעל בכתובה שהוא פחות חמישית?","\u0003אם תמצא\u0004 (תרצה) \u0003לומר\u0004 שמדובר פה ב\u0003מנה המתקבל\u0004 בפועל, האם הכוונה היא שנותן לה ב\u0003יום ראשון\u0004 בלבד, רק פעם אחת, \u0003או\u0004 ב\u0003כל יום ויום? אם תמצא לומר\u0004 שנותן לה \u0003כל יום ויום,\u0004 האם הוא נותן ב\u0003שבת ראשונה\u0004 (בשבוע הראשון) של הנישואין בלבד, \u0003או\u0004 ב\u0003כל שבת ושבת? אם תמצא לומר\u0004 כי נותן לה ב\u0003כל שבת ושבת,\u0004 האם זה רק ב\u0003חדש\u0004 ה\u0003ראשון או\u0004 שמא ב\u0003כל חדש וחדש? אם תמצא לומר\u0004 כי נותן לה ב\u0003כל חדש וחדש,\u0004 האם מדובר דווקא ב\u0003שנה\u0004 ה\u0003ראשונה או\u0004 שמא ב\u0003כל שנה ושנה?\u0004 כל הבעיות הללו שבאו לבאר לכמה זמן נותן שיעור זה של קופה, נשארו כולן ללא פתרון, והריהן \u0003תיקו\u0004 \u0005[תעמודנה]\u0006 במקומן.","אגב כך מסופר, \u0003אמר רב יהודה אמר רב: מעשה בבתו של נקדימון בן גוריון\u0004 שהיה עשיר מופלג, \u0003שפסקו לה חכמים ארבע מאות זהובים לקופה של בשמים לבו ביום.\u0004 ברכה אותם ו\u0003אמרה להם: כך תפסקו לבנותיכם, וענו אחריה אמן.\u0004 כיון שהוזכר שמה מזכירים מה אירע בה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה ברבן יוחנן בן זכאי שהיה רוכב על החמור והיה יוצא מירושלים, והיו תלמידיו מהלכין אחריו\u0004 ללמוד ממנו. \u0003ראה ריבה\u0004 (אשה צעירה) \u0003אחת, שהיתה מלקטת שעורים מבין גללי בהמתן של ערביים,\u0004 שכל כך היתה עניה ורעבה שהיתה מתפרנסת מהשעורים שלא נתעכלו בתוך גללי הבהמות. \u0003כיון שראתה אותו נתעטפה בשערה\u0004 שלא היה לה דבר אחר להתכסות בו, \u0003ועמדה לפניו.\u0004","\u0003אמרה לו: רבי, פרנסני. אמר לה: בתי, מי את?\u0004 שהיה ברור שהיא מכירה אותו, אבל הוא לא הכירה. \u0003אמרה לו: בת נקדימון בן גוריון אני. אמר לה: בתי, ממון של בית אביך\u0004 ל\u0003היכן הלך?\u0004 וכיצד נעשית עניה עד כדי כך? \u0003אמרה לו: רבי,\u0004 האם \u0003לא כדין מתלין מתלא\u0004 \u0005[כך מושלים משל]\u0006 \u0003בירושלים: \"מלח ממון חסר\"?\u0004 כלומר, אין לממון מלח שישמר אותו כדי שלא ילך לאיבוד. \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהמשל היה: \u0003\"\u0004מלח ממון — \u0003חסד\".\u0004 כלומר, מה שמשמר את הממון, הוא עשיית חסד בו. שאל אותה: \u0003ו\u0004הממון \u0003של בית חמיך\u0004 שהיה עושה חסד כראוי \u0003היכן הוא? אמרה לו: בא זה ואיבד את זה,\u0004 שכל הכספים נתערבו ואבדו בבת אחת.","\u0003אמרה לו: רבי, זכור אתה כשחתמת על כתובתי? אמר להן לתלמידיו: זכור אני כשחתמתי על כתובתה של זו, והייתי קורא בה: אלף אלפים דינרי זהב\u0004 היא מקבלת כנדוניה \u0003מבית אביה, חוץ משל חמיה. בכה רבן יוחנן בן זכאי ואמר: אשריכם ישראל, בזמן שעושין רצונו של מקום\u0004 (הקדוש ברוך הוא) \u0003אין כל אומה ולשון שולטת בהם, ובזמן שאין עושין רצונו של מקום,\u0004 הריהו \u0003מוסרן ביד אומה שפלה\u0004 כמו ערביים, \u0003ולא ביד אומה שפלה\u0004 בלבד \u0003אלא ביד בהמתן של אומה שפלה\u0004 שהרי נזקקה ללקוט מבין גללי בהמתן של הערביים. כיון שמן הדברים פה היה נראה שנקדימון בן גוריון לא עשה חסד.","שואלים: \u0003ו\u0004כי \u0003נקדימון בן גוריון לא עבד\u0004 \u0005[עשה]\u0006 \u0003צדקה? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אמרו עליו על נקדימון בן גוריון כשהיה יוצא מביתו לבית המדרש, כלי מילת\u0004 (אריגי צמר משובח) \u0003היו\u0004"],["\u0003מציעין תחתיו\u0004 (תחת רגליו) ללכת עליהם, והוא היה מפקיר אותם \u0003ובאין עניים ומקפלין אותן מאחריו\u0004 לאחר שעבר עליהם, ונוטלים אותם לעצמם. אם כן הרבה צדקה נתן! ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 מה שמסופר עליו שנתן לצדקה באמת \u0003לכבודו הוא דעבד\u0004 \u0005[שעשה],\u0006 שרצה להראות כמה הכסף אינו חשוב בעיניו, \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003כדבעי ליה למיעבד\u0004 \u0005[כמו שהיה צריך לו לעשות],\u0006 \u0003לא עבד\u0004 \u0005[עשה].\u0006 \u0003כדאמרי אינשי\u0004 \u0005[כפי שאומרים האנשים]\u0006 כפתגם עממי: \u0003לפום גמלא, שיחנא\u0004 \u0005[לפי הגמל, המשא],\u0006 שלפי גודלו מטעינים עליו יותר. וכן נקדימון בן גוריון לפי רוב עושרו לא נתן צדקה כראוי.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אמר ר' אלעזר בר' צדוק\u0004 בלשון שבועה: \u0003אראה בנחמה\u0004 (כה אזכה לראות בגאולת ישראל), \u0003אם לא ראיתיה שהיתה מלקטת שעורים מבין טלפי סוסים בעכו. קראתי עליה מקרא זה: \"אם לא תדעי לך היפה בנשים צאי לך בעקבי הצאן ורעי את גדיתיך\u0004 על משכנות הרועים\u0003\"\u0004 (שיר השירים א, ח), \u0003אל תקרי \"גדיותיך\" אלא \"גויותיך\",\u0004 כלומר, שהיא צריכה, לצורך גופה שלה (\"גויותיך\") ללכת בעקבי הצאן, ולהתפרנס מהשיירים.","\u0003אמר רב שמן בר אבא אמר ר' יוחנן:\u0004 אם \u0003הכניסה לו\u0004 חתיכות \u0003זהב\u0004 כנדוניה — \u0003שמין\u0004 (מעריכים) \u0003אותו, והרי הוא כ\u0004פי \u0003שוויו,\u0004 ואין מוסיפים בכתובה על שוויו ולא פוחתים מערכו. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003הזהב הרי הוא\u0004 לענין נדוניה \u0003ככלים.\u0004 ומבררים: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003ככלים של כסף, דפחתי\u0004 \u0005[ש\u0006הם \u0005פוחתים]\u0006 והולכים במשך הזמן, ולפי זה דינם כשאר חפצים שהיא מכניסה בנדוניה וצריך להפחית מערכם בכתובה! ודוחים: \u0003לא,\u0004 הכוונה היא \u0003ככלים של זהב, דלא פחתי\u0004 \u0005[שאינם פוחתים].\u0006 ומקשים: \u0003אם כן,\u0004 זהב הריהו \u0003ככליו מיבעי ליה\u0004 \u0005[צריך\u0006 היה \u0005לו\u0006 לומר\u0005]!\u0006 כלומר, צריך לשנות \"ככליו\" העשויים גם הם מזהב והמוערכים בשווים האמיתי, ולא כ\"כלים\" סתם.","\u0003ועוד\u0004 יש לשאול: \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא אחרת\u0005]:\u0006 \u0003זהב הרי הוא ככלים,\u0004 ואילו \u0003דינרי זהב,\u0004 מטבעות, \u0003הרי הן ככספים,\u0004 ומוסיף הבעל שליש על שווים. \u0003רבן שמעון בן גמליאל אומר: במקום שנהגו שלא לפורטן\u0004 שיש להם שווי קבוע ופורטים אותם למספר קבוע של דינרי כסף — \u0003שמין אותן והרי הן בשוויהן,\u0004 לא פחות ולא יותר. ומבררים: \u0003רבן שמעון בן גמליאל אהייא\u0004 \u0005[על איזה]\u0006 דבר הוא מתייחס? \u0003אילימא אסיפא\u0004 \u0005[אם תאמר על סופה]\u0006 של הברייתא, לגבי דינרי זהב, אם כן \u0003מכלל\u0004 דבריו אתה למד אתה שה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003סבר\u0004 כי \u0003אפילו במקום שנהגו שלא לפורטן\u0004 הרי הם ככספים? \u0003הא לא נפקי\u0004 \u0005[הרי\u0006 הם \u0005אינם יוצאים]\u0006 בהוצאה כאשר אין פורטים אותם אלא משאירים אותם כרכוש קבוע, ומדוע יוסיף הבעל עליהם?","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 התכוון \u0003ארישא\u0004 \u0005[על ראשה]\u0006 של הברייתא, \u0003והכי קאמר\u0004 \u0005[וכך אמר],\u0006 כך צריך להבין את כל הקטע: \u0003זהב הרי הוא ככלים, מאי\u0004 \u0005[מה,\u0006 איזה\u0005]\u0006 \u0003כלים — כלים של כסף.\u0004 ואילו \u0003רבן שמעון בן גמליאל אומר: הרי הוא כדינרין של זהב,\u0004 שערכם קבוע \u0003במקום שנהגו שלא לפורטן\u0004 ולא לעשות בהם עסקים. ועל כל פנים מדברי חכמים יש סתירה למה שאמרנו שדינו של זהב ככלי זהב ולא ככלי כסף!","ודוחים: \u0003לא, לעולם\u0004 תפרש כי אמר דבריו \u0003אסיפא\u0004 \u0005[על סופה\u0006 של הברייתא\u0005]\u0006 ומדובר פה בדינרים, \u0003ו\u0004אם אמנם אינם נפרטים, הרי זה מחמת \u0003דנפקי\u0004 \u0005[שיוצאים]\u0006 ומשתמשים בהם למסחר רק \u0003על ידי הדחק,\u0004 שאמנם הם אינם משמשים למשא ומתן קבוע, אבל בדוחק אפשר להשתמש בהם. \u0003ו\u0004לפי זה \u0003בהא קמיפלגי\u0004 \u0005[וב\u0006נושא \u0005זה חלוקים];\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 תנא קמא, \u0005סבור]:\u0006 \u0003כיון דנפקי\u0004 \u0005[ש\u0006הם \u0005יוצאים]\u0006 אם כי בדוחק, \u0003משבחינן לה\u0004 \u0005[מוסיפים\u0006 עליהם \u0005שבח]\u0006 וכותב לה הבעל תוספת כתובה כדין כספים, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רבן שמעון בן גמליאל, \u0005סבור]:\u0006 \u0003כיון דלא נפקי\u0004 \u0005[שאינם יוצאים]\u0006 \u0003אלא על ידי הדחק,\u0004 לפיכך \u0003לא משבחינן לה\u0004 \u0005[אין מוסיפים לה שבח].\u0006","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 באופן אחר: כל הברייתא \u0003כולה\u0004 כשיטת \u0003רבן שמעון בן גמליאל היא, וחסורי מיחסרא והכי קתני\u0004 \u0005[וחסרה\u0006 הברייתא \u0005וכך\u0006 היא \u0005שנויה]:\u0006 \u0003זהב הרי הוא ככלים, דינרי זהב הרי הן ככספים. במה דברים אמורים — במקום שנהגו לפורטן\u0004 את הדינרים, \u0003אבל במקום שנהגו שלא לפורטן — שמין אותם\u0004 כמה שהם שווים, \u0003והרי הן בשוויהן,\u0004 אלו \u0003דברי רבן שמעון בן גמליאל. שרבן שמעון בן גמליאל אומר: במקום שנהגו שלא לפורטן, שמין אותם והרי הן בשוויהן.\u0004","הסברנו איפוא את הקושיה מן הברייתא ששאלנו, \u0003מכל מקום\u0004 אם דינו של זהב ככלי זהב ויש להעריכו כשוויו, אם כן \u0003\"ככליו\" מיבעי ליה\u0004 \u0005[היה צריך לו\u0006 לומר\u0005],\u0006 שזהב הריהו ככליו ולא ככלים סתם! ואומרים: אכן, \u0003קשיא\u0004 \u0005[קשה\u0006 הדבר\u0005],\u0006 שאין לשון זו בהירה כל צורכה. \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003הכא במאי עסקינן\u0004 \u0005[כאן\u0006 במשנה \u0005במה אנו עוסקים]\u0006 — \u0003בדהבא פריכא\u0004 \u0005[בזהב שבור,\u0006 בגרוטאות של זהב\u0005].\u0006 \u0003רב אשי אמר: בממלא\u0004 \u0005[בגרגרים\u0006 של זהב\u0005]\u0006 אנו עוסקים, ובודאי אין דינם ככלי זהב ממש, אלא שבא לומר שדינם ככלים ולא כדינרים של זהב.","אגב דברים אלה בהערכת חפצים העשויים לשמש במסחר, \u0003אמר ר' ינאי: בשמים של אנטוכיא — הרי הן ככספים.\u0004 משום שבאנטיוכיא היו עושים מסחר בהם, וכאשר אשה מכניסה אותם בנדוניה, יש לדון בהם כאילו הכניסה לו כסף מזומן. וכיוצא בזה \u0003אמר ר' שמואל בר נחמני אמר ר' יוחנן: גמלים של ערביא\u0004 (של ערב) — \u0003אשה גובה פרנא\u0004 (כתובה) \u0003מהם.\u0004 משום ששם הם נושאים ונותנים בהם, והריהם כמו כספים במקום אחר.","וכיוצא בזה \u0003אמר רב פפי: הני תותבי דבי מכסי\u0004 \u0005[אותן השמלות של בית מכסי]\u0006 \u0003אשה גובה פרנא מהם,\u0004 משום שבזה היה מסחרם. \u0003ואמר רב פפי: הני שקי\u0004 \u0005[אותם השקים]\u0006 של המקום \u0003רודיא, ואשלי\u0004 \u0005[והחבלים]\u0006 של המקום \u0003קמחוניא,\u0004 כיון שמסחרם היה בדברים אלה — \u0003אשה גובה פרנא מהן. אמר רבא: מריש הוה אמינא\u0004 \u0005[מתחילה הייתי אומר]\u0006 \u0003הני\u0004 \u0005[אותם]\u0006 \u0003ארנקי\u0004 כספים של העיר \u0003מחוזא, אשה גובה פרנא מהם. מאי טעמא\u0004 \u0005[\u0006ו\u0005מה טעם]?\u0006 — \u0003אסמכתייהו עלייהו\u0004 \u0005[הם סומכים עליהם]\u0006 ודינם כמו קרקעות במקום אחר, \u0003כיון דחזאי דשקלי להו ונפקי\u0004 \u0005[שראיתי ש\u0006הן \u0005לוקחות אותם ויוצאות],\u0006 \u0003וכי משכחי ארעא זבני בהו\u0004 \u0005[וכאשר\u0006 הן \u0005מוצאות קרקע,\u0006 הם \u0005קונות בהם]\u0006 ואינן משאירות את הכסף במזומן, \u0003אמינא אסמכתייהו אארעא הוא\u0004 \u0005[אמרתי\u0006 שגם הם נשענות ו\u0005נסמכות על הקרקע]\u0006 ולא על מטלטלים אלה.","\u0003המשיא את בתו סתם\u0004 בלי לפרש כמה נדוניה הוא נותן — \u0003לא יפחות לה מחמשים זוז. פסק להכניסה ערומה,\u0004 שאמר שאינו נותן לה דבר — \u0003לא יאמר הבעל \"כשאכניסנה לביתי אכסנה בכסותי\", אלא\u0004 מפני הכבוד \u0003מכסה ו\u0004נותן לה בגדים הראויים לה ב\u0003עודה בבית אביה,\u0004 וכך היא מגיעה אליו. \u0003וכן\u0004 גבאי צדקה \u0003המשיא את היתומה — לא יפחות לה מחמשים זוז\u0004 לנדוניה. ו\u0003אם יש בכיס\u0004 של צדקה יותר כסף — \u0003מפרנסין אותה\u0004 בנדוניה ובשאר צרכיה \u0003לפי כבודה.\u0004","\u0003אמר אביי:\u0004 חמישים זוז שאמרנו הם \u0003חמשים זוזי פשיטי\u0004 \u0005[זוזים פשוטים,\u0006 דינרי מדינה\u0005],\u0006 שכל אחד מהם שווה שמינית של זוז (דינר) רגיל. \u0003ממאי\u0004 \u0005[ממה]\u0006 אני יודע שכך הוא — \u0003מדקתני סיפא\u0004 \u0005[מ\u0006מה \u0005ששנה\u0006 ב\u0005סופה]:\u0006 \u0003אם יש בכיס\u0004 — \u0003מפרנסין אותה לפי כבודה, ואמרינן\u0004 \u0005[ואמרנו]\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 פירושו של \u0003כיס\u0004 זה? \u0003אמר רחבה:\u0004 הכוונה היא \u0003ארנקי של צדקה. ואי סלקא דעתין\u0004 \u0005[ואם עולה על דעתנו]\u0006 לומר שכוונתו \u0003חמשים זוזי\u0004 \u0005[זוזים]\u0006 \u0003ממש,\u0004 דינרים רגילים \u0003אם יש בכיס כמה יהבינן\u0004 \u0005[אנו נותנים]\u0006 \u0003לה?\u0004 שהרי חמישים דינר הם סכום גדול לתת בתורת צדקה. \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003חמשים\u0004 זוז הם \u0003זוזי פשיטי\u0004 \u0005[זוזים פשוטים,\u0006 דינרי מדינה\u0005].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003יתום ויתומה שבאו להתפרנס\u0004 מן הצדקה — \u0003מפרנסין את היתומה ואחר כך מפרנסין את היתום.\u0004 וטעמו של דבר — \u0003מפני שהאיש דרכו לחזור על הפתחים, ואין אשה דרכה לחזור,\u0004 ולכן צורכה גדול יותר. \u0003יתום ויתומה\u0004"],["\u0003שבאו לינשא\u0004 כל אחד לעצמו וצריכים עזרה מן הצדקה — \u0003משיאין את היתומה ואחר כך משיאין את היתום.\u0004 וטעמו של דבר — \u0003מפני שבושתה של אשה\u0004 שאיננה נשואה \u0003מרובה משל איש.\u0004","ועוד בענין זה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003יתום שבא לישא\u0004 אשה, דואגים לו ככל האפשר לכל צרכיו: \u0003שוכרין לו בית, ומציעין לו מטה וכל כלי תשמישו, ואחר כך משיאין לו אשה, שנאמר: \"\u0004כי פתוח תפתח את ידך לו... \u0003די מחסרו אשר יחסר לו\"\u0004 (דברים טו, ח), ודרשו חכמים: \u0003\"די מחסרו\" — זה הבית, \"אשר יחסר\" — זה מטה ושלחן, \"לו\" — זו אשה. וכן הוא אומר\u0004 ראיה ש\"לו\" הוא רמז לאשה — \u0003\"אעשה לו עזר כנגדו\"\u0004 (בראשית ב, יח).","באותו ענין \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"די מחסרו\"\u0004 — מכאן אנו למדים ש\u0003אתה מצווה עליו\u0004 (על העני) \u0003לפרנסו, ואי אתה מצווה עליו לעשרו.\u0004 שהחובה היא למלא לו את מחסורו, אבל אין חובה לתת לו עד שיתעשר. ומה שנאמר \u0003\"אשר יחסר לו\"\u0004 הרי זה כולל \u0003אפילו סוס לרכוב עליו ועבד לרוץ לפניו\u0004 לשם כבודו אם רגיל בכך. שלאדם הרגיל בדבר זה, מניעתו הוא בגדר מחסורו שיחסר לו, ואינו נחשב למותרות. ומסופר: \u0003אמרו עליו על הלל הזקן שלקח\u0004 (קנה) \u0003לעני בן טובים אחד\u0004 שהיה רגיל בכך, \u0003סוס לרכוב עליו ועבד לרוץ לפניו. פעם אחת לא מצא עבד לרוץ לפניו ורץ\u0004 הלל עצמו \u0003לפניו שלשה מילין,\u0004 כדי שלאותו עני יתמלא כדי מחסורו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה באנשי גליל העליון שלקחו\u0004 (קנו) \u0003לעני בן טובים אחד מ\u0004העיר \u0003ציפורי\u0004 משקל של \u0003ליטרא בשר בכל יום.\u0004 ותוהים: \u0003ליטרא בשר מאי רבותא\u0004 \u0005[מה הגדולה בזה]?\u0006 הלא אין זו נתינה מרובה כל כך שצריך לספר עליה! \u0003אמר רב הונא:\u0004 הכוונה היא \u0003ליטרא בשר משל עופות,\u0004 שהוא בשר יקר בהרבה. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003בליטרא,\u0004 כלומר, במחיר ליטרא כסף קנו לו \u0003בשר ממש. רב אשי אמר\u0004 להסביר באופן אחר: \u0003התם\u0004 \u0005[שם]\u0006 בגליל העליון \u0003כפר קטן היה,\u0004 וכיון שנתנו לו ליטרא בשר, היו צריכים לשחוט לו בהמה, ו\u0003בכל יומא\u0004 \u0005[יום]\u0006 \u0003הוה מפסדי חיותא אמטולתיה\u0004 \u0005[היו מפסידים בהמה\u0006 אחת \u0005בגללו].\u0006","ועוד בענייני צדקה \u0003ההוא דאתא לקמיה\u0004 \u0005[אחד שבא לפני]\u0006 \u0003ר' נחמיה\u0004 וביקש צדקה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003במה אתה סועד\u0004 כרגיל? \u0003אמר ליה\u0004 \u0005[לו]\u0006 דרכי לסעוד \u0003בבשר שמן ויין ישן.\u0004 שאל אותו: \u0003רצונך שתגלגל עמי\u0004 (שתאכל יחד אתי) \u0003בעדשים?\u0004 שזה היה מאכלו של ר' נחמיה. לבסוף \u0003גלגל עמו\u0004 (האכילו) \u0003בעדשים ומת,\u0004 שלא היה רגיל באוכל זה. \u0003אמר: אוי לו לזה שהרגו נחמיה.\u0004 ותוהים: \u0003אדרבה, \"אוי לו לנחמיה שהרגו לזה\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005].\u0006 \u0003אלא\u0004 הכוונה היתה: \u0003איהו הוא\u0004 \u0005[הוא זה]\u0006 ש\u0003לא איבעי ליה\u0004 \u0005[היה צריך לו]\u0006 \u0003לפנוקי נפשיה כולי האי\u0004 \u0005[לפנק את עצמו כל כך],\u0006 שכיון שהיה מעודן כל כך, הוא עצמו גרם לכך שימות.","ועוד מסופר: \u0003ההוא דאתא לקמיה\u0004 \u0005[אחד שבא לפני]\u0006 \u0003רבא\u0004 לבקש צדקה. \u0003אמר לו: במה אתה סועד\u0004 כרגיל? \u0003אמר לו בתרנגולת פטומה ויין ישן. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ולא חיישת לדוחקא דציבורא\u0004 \u0005[ו\u0006כי \u0005אינך חושש לדוחק הציבור],\u0006 שאתה מטיל עליהם דרישות מרובות אלה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אטו מדידהו קאכילנא\u0004 \u0005[וכי משלהם אני אוכל]?\u0006 הלא \u0003מדרחמנא קאכילנא\u0004 \u0005[משל הקדוש ברוך הוא אני אוכל]!\u0006 \u0003דתנינא\u0004 \u0005[ששנינו]:\u0006 \u0003\"עיני כל אליך ישברו ואתה נותן להם את אכלם בעתו\"\u0004 (תהלים קמה, טו). \u0003\"בעתם\" לא נאמר, אלא \"בעתו\" — מלמד שכל אחד ואחד נותן הקדוש ברוך הוא פרנסתו בעתו,\u0004 כלומר, שנותן לכל אחד כפי מה שצריך, ואם כן, הפרנסה באה מהקדוש ברוך הוא, ובני אדם אינם אלא שליחים, ולכן איני משנה את דרכי.","\u0003אדהכי\u0004 \u0005[בינתיים]\u0006 עד שהם משוחחים, \u0003אתאי אחתיה\u0004 \u0005באה אחותו]\u0006 של \u0003רבא\u0004 ש\u0003לא חזיא ליה\u0004 \u0005[ראתה אותו]\u0006 \u0003תליסרי שני\u0004 \u0005[שלוש עשרה שנה]\u0006 \u0003ואתיא ליה\u0004 \u0005[והביאה לו]\u0006 כמתנה \u0003תרנגולת פטומה ויין ישן. אמר\u0004 רבא בליבו: \u0003מאי דקמא\u0004 \u0005[מהו\u0006 זה \u0005שלפני],\u0006 שפתאום הביאו לי מאכל שאינני רגיל בו? ואז הבין שזו כעין תשובה למה שאמר לאותו עני. \u0003אמר ליה\u0004 \u0005[לו]\u0006 לעני: \u0003נענתי\u0004 (נתרציתי) \u0003לך — קום אכול.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 עני ש\u0003אין לו\u0004 כדי צורכו \u0003ואינו רוצה להתפרנס\u0004 מן הצדקה — \u0003נותנין לו\u0004 כסף \u0003לשום\u0004 (לשם) \u0003הלואה\u0004 בדרך כבוד, \u0003וחוזרין ונותנין לו לשום מתנה,\u0004 אלו \u0003דברי ר' מאיר. וחכמים אומרים: נותנין לו לשום מתנה, וחוזרין ונותנין לו לשום הלואה.\u0004 על דברי חכמים תוהים: \u0003לשום מתנה? הא לא שקיל\u0004 \u0005[הרי אינו\u0006 רוצה \u0005לקחת]\u0006 במתנה! ומשיבים: \u0003אמר רבא\u0004 הכוונה היא \u0003לפתוח לו לשום מתנה,\u0004 כלומר, להציע לו מראש שרוצים לתת לו מתנה, ואם אינו מקבל כלל נותנים לו כהלוואה, אבל אחר כך מבין שנתנו לו מתנה ואין תובעים ממנו להחזיר.","מי ש\u0003יש לו ואינו רוצה להתפרנס\u0004 משל עצמו, אלא לחיות מן הצדקה — \u0003נותנין לו לשום מתנה\u0004 כצדקה, \u0003וחוזרין ונפרעין ממנו.\u0004 ותוהים: אם \u0003חוזרין ונפרעין הימנו תו לא שקיל\u0004 \u0005[שוב אינו לוקח]!\u0006 \u0003אמר רב פפא:\u0004 הכוונה היא \u0003לאחר מיתה\u0004 נפרעים ממנו כל מה שנטל מן הצדקה. \u0003ר' שמעון אומר\u0004 שלא כדברי חכמים: \u0003יש לו\u0004 משל עצמו \u0003ואינו רוצה להתפרנס\u0004 אלא מן הצדקה — \u0003אין נזקקין לו.\u0004 שאין חובה על הציבור לדאוג לאדם זה. \u0003אין לו ואינו רוצה להתפרנס\u0004 מן הצדקה — \u0003אומרים לו: הבא משכון וטול\u0004 הלוואה, \u0003כדי שתזוח\u0004 (שתגבה) \u0003דעתו עליו,\u0004 כלומר, שלא תהיה לו השפלה, אלא יחשוב שנותנים לו הלוואה, אף כי לאמיתו של דבר נותנים לו במתנה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר \"ולא תקפוץ את ידך מאחיך האביון... והעבט תעביטנו די מחסורו...\" (דברים טו, ז-ח). ומדוע נוטלים משכון (עבוט) — אמרו: \u0003\"העבט\" — זה שאין לו ואינו רוצה להתפרנס\u0004 מן הצדקה, \u0003שנותנים לו לשום\u0004 (לשם) \u0003הלואה וחוזרין ונותנין לו לשום מתנה. \"תעביטנו\" —\u0004 הוא \u0003זה שיש לו\u0004 משל עצמו \u0003ואינו רוצה להתפרנס\u0004 אלא מן הצדקה, \u0003שנותנין לו לשום\u0004 (לשם) \u0003מתנה, וחוזרין ונפרעין הימנו לאחר מיתה,\u0004 אלו \u0003דברי ר' יהודה.\u0004","\u0003וחכמים אומרים: יש לו ואינו רוצה להתפרנס\u0004 אלא מן הצדקה — \u0003אין נזקקין לו. ואלא מה אני מקיים,\u0004 וכיצד אני מפרש את ההכפלה \u0003\"\u0004העבט \u0003תעביטנו\"?\u0004 ש\u0003דברה תורה כלשון בני אדם,\u0004 ואין כפל לשון זו מלמדת דבר.","ועוד במעשה הצדקה: \u0003מר עוקבא הוה עניא בשיבבותיה\u0004 \u0005[היה עני בשכנותו]\u0006 \u0003דהוה\u0004 \u0005[שהיה]\u0006 \u0003רגיל\u0004 מר עוקבא \u0003כל יומא\u0004 \u0005[יום]\u0006 \u0003דשדי ליה\u0004 \u0005[לזרוק לו]\u0006 \u0003ארבעה זוזי\u0004 \u0005[זוזים]\u0006 \u0003בצינורא דדשא\u0004 \u0005[בתוך חור הדלת].\u0006 \u0003יום אחד אמר\u0004 אותו עני: \u0003איזיל איחזי מאן קעביד בי ההוא טיבותא\u0004 \u0005[אלך אראה מי עושה לי אותה טובה],\u0006 שלא ידע מי נותן לו את הצדקה. \u0003ההוא יומא נגהא ליה\u0004 \u0005[אותו יום התאחר]\u0006 \u0003מר עוקבא לבי מדרשא\u0004 \u0005[\u0006לבוא \u0005לבית המדרש].\u0006 \u0003אתיא דביתהו בהדיה\u0004 \u0005[באה אשתו יחד אתו]\u0006 לחלק את הצדקה,","\u0003כיון דחזיוה\u0004 \u0005[שראו]\u0006 בני הבית של אותו עני \u0003דקא מצלי ליה לדשא\u0004 \u0005[שמטה את הדלת],\u0006 \u0003נפק בתרייהו\u0004 \u0005[יצא\u0006 העני \u0005אחריהם]\u0006 לראות מי הם הנותנים. \u0003רהוט מקמיה\u0004 \u0005[רצו,\u0006 ברחו \u0005מלפניו],\u0006 שלא רצו שיידע מי הם, \u0003עיילי לההוא אתונא דהוה\u0004 \u0005[נכנסו לכבשן שהיתה]\u0006 \u0003גרופה נורא\u0004 \u0005[האש]\u0006 בו אבל עדיין היה חם מאד, \u0003הוה קא מיקליין כרעיה\u0004 \u0005[היו נשרפות רגליו]\u0006 של \u0003מר עוקבא\u0004 מחמת החום. \u0003אמרה ליה דביתהו\u0004 \u0005[לו אשתו]:\u0006 \u0003שקול כרעיך אותיב אכרעאי\u0004 \u0005[הרם\u0006 את \u0005רגליך ושים על רגלי]\u0006 שאני אינני נכוית. \u0003חלש דעתיה\u0004 \u0005[חלשה,\u0006 נפגעה \u0005דעתו]\u0006 של מר עוקבא, שראה שאשתו צדקת גדולה ממנו שאינה נכוית על ידי האש, \u0003אמרה ליה\u0004 \u0005[לו]\u0006 לפייסו: \u0003אנא שכיחנא בגויה דביתא ומקרבא אהנייתי\u0004 \u0005[אני מצוייה בתוך הבית ו\u0006כשאני נותנת צדקה \u0005קרובה הנאתי],\u0006 לפי שאני נותנת אותה בלחם ומזונות והעני נהנה מיד, ואילו אתה נותן להם כספים שאין בהם הנאה מיד, ולכן שכרי מרובה.","ושואלים: \u0003ומאי כולי האי\u0004 \u0005[ומה\u0006 היה \u0005כל זה]\u0006 שברחו עד כדי כך שנכנסו לתוך כבשן? מדוע עשו כן? ומשיבים: ש\u0003אמר מר זוטרא בר טוביה אמר רב, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003רב הונא בר ביזנא אמר ר' שמעון חסידא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003ר' יוחנן משום ר' שמעון בן יוחי: נוח\u0004 (מוטב) \u0003לו לאדם שימסור עצמו לתוך כבשן האש, ואל ילבין פני חברו ברבים. מנא לן\u0004 \u0005[מניין לנו]\u0006 דבר זה — \u0003מתמר, דכתיב\u0004 \u0005[שנאמר]:\u0006 \"...ויאמר יהודה הוציאוה ותשרף. \u0003היא מוצאת\u0004 והיא שלחה אל חמיה לאמר לאיש אשר אלה לו אנכי הרה\" (בראשית לח, כד-כה), שלא פרסמה שיהודה הוא זה שבא עליה שלא לביישו, למרות שהיתה עלולה להשרף בכבשן האש, ומכאן למדים כמה צריך להזהר כדי שלא להלבין פנים.","ועוד מסופר: \u0003מר עוקבא הוה עניא בשיבבותיה דהוה\u0004 \u0005[היה עני בשכנותו שהיה]\u0006 \u0003רגיל\u0004 מר עוקבא \u0003לשדורי ליה\u0004 \u0005[לשלוח לו]\u0006 \u0003ארבע מאה זוזי\u0004 \u0005[מאות זוזים]\u0006 \u0003כל מעלי יומא דכיפורא\u0004 \u0005[ערב יום כיפור].\u0006 \u0003יומא חד שדרינהו ניהליה\u0004 \u0005[יום אחד שלח\u0006 את הכסף \u0005אליו]\u0006 \u0003ביד בריה\u0004 \u0005[בנו].\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 בחזרה הבן ו\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא צריך\u0004 העני ההוא צדקה. \u0003אמר\u0004 מר עוקבא \u0003מאי חזית\u0004 \u0005[מה ראית]\u0006 שאתה אומר כך? אמר לו: \u0003חזאי דקא מזלפי ליה\u0004 \u0005[ראיתי שמזלפים לו]\u0006 \u0003יין ישן\u0004 על הרצפה לבישום החדר. \u0003אמר\u0004 מר עוקבא: אם הוא \u0003מפנק כולי האי\u0004 \u0005[מפונק כל כך]\u0006 וזקוק אף לכך, הריהו צריך יותר! \u0003עייפינהו ושדרינהו ניהליה\u0004 \u0005[כפל\u0006 את סכום המעות \u0005ושלח אליו].\u0006","\u0003כי קא ניחא נפשיה\u0004 \u0005[כאשר נחה נפשו,\u0006 כשעמד מר עוקבא למות\u0005],\u0006 \u0003אמר: אייתו\u0004 \u0005[הביאו]\u0006 \u0003לי\u0004 את \u0003חושבנאי\u0004 \u0005[חשבון]\u0006 ה\u0003צדקה\u0004 שלי. \u0003אשכח דהוה כתיב ביה\u0004 \u0005[מצא שהיה כתוב בו]\u0006 \u0003שבעת אלפי\u0004 \u0005[אלפים]\u0006 \u0003דינרי סיאנקי\u0004 \u0005[זהב טובים]\u0006 שנתן לצדקה. \u0003אמר: זוודאי קלילי ואורחא רחיקתא\u0004 \u0005[צידתי קלה והדרך רחוקה],\u0006 כלומר, אין סכום זה מספיק בשביל ללכת עמו לחיי העולם הבא. \u0003קם בזבזיה לפלגיה ממוניה\u0004 \u0005[עמד ובזבז את חצי ממונו]\u0006 לצדקה. ושואלים: \u0003היכי עביד הכי\u0004 \u0005[איך עשה כן]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אילעאי: באושא התקינו\u0004 ש\u0003המבזבז\u0004 מנכסיו לצדקה — \u0003אל יבזבז יותר מחומש!\u0004 ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים שלא יבזבז \u0003מחיים,\u0004 שחששו \u0003שמא ירד מנכסיו. אבל לאחר מיתה — לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 איסור ורשאי אדם לתת הרבה מאד לצדקה סמוך למותו.","ועוד בדרכי נתינת הצדקה \u0003ר' אבא הוה צייר זוזי בסודריה\u0004 \u0005[היה צורר מטבעות בסודרו],\u0006 \u0003ושדי ליה לאחוריה\u0004 \u0005[ומטיל אותו לאחוריו],\u0006 \u0003וממצי נפשיה לבי עניי\u0004 \u0005[והיה ממציא\u0006 את \u0005עצמו אל בין העניים]\u0006 שיוכלו לקחת ממנו בלא שיראה מי הם, אבל \u0003ומצלי עיניה\u0004 \u0005[והיה מטה\u0006 את \u0005עיניו]\u0006 להציץ מי הם הלוקחים, לפי שחשש \u0003מרמאי\u0004 (מפני הרמאים) שלא ייקח גנב את הכסף לעצמו.","מסופר: \u0003ר' חנינא הוה ההוא עניא דהוה\u0004 \u0005[היה עני אחד שהיה]\u0006 \u0003רגיל\u0004 ר' חנינא \u0003לשדורי ליה\u0004 \u0005[לשלוח לו]\u0006 \u0003ארבעה זוזי\u0004 \u0005[זוזים]\u0006 \u0003כל מעלי שבתא\u0004 \u0005[ערב שבת].\u0006 \u0003יומא חד שדרינהו ניהליה ביד דביתהו\u0004 \u0005[יום אחד שלח אותם אליו ביד אשתו],\u0006 \u0003אתאי\u0004 \u0005[באה]\u0006 בחזרה \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003לא צריך\u0004 העני לצדקה. שאל אותה: \u0003מאי חזית\u0004 \u0005[מה ראית]\u0006 שאת אומרת כך? אמרה לו: \u0003שמעי דהוה קאמרי ליה\u0004 \u0005[שמעתי שהיו אומרים לו]\u0006 בתוך ביתו: \u0003במה אתה סועד\u0004"],["\u0003בטלי כסף או בטלי זהב\u0004 \u0005[במפות לבנות או במפות צבועות]?\u0006 הרי שאינו נזקק לצדקה! \u0003אמר\u0004 ר' חנינא: \u0003היינו\u0004 \u0005[זהו]\u0006 ש\u0003אמר ר' אלעזר: בואו ונחזיק טובה לרמאין\u0004 שמבקשים צדקה בלי להיות זקוקים לכך, \u0003שאלמלא הן\u0004 שנותנים לנו איזשהו צידוק, \u0003היינו חוטאין בכל יום\u0004 שאין אנחנו נותנים לעניים כל צורכם. ומנין שזה חטא — \u0003שנאמר: \"\u0004ורעה עינך באחיך האביון ולא תתן לו \u0003וקרא עליך אל ה' והיה בך חטא\"\u0004 (דברים טו, ט).","\u0003ותני\u0004 \u0005[ושנה]\u0006 \u0003ר' חייא בר רב מדיפתי, ר' יהושע בן קרחה אומר: כל המעלים עיניו מן הצדקה\u0004 ואיננו נותן — \u0003כאילו עובד עבודה זרה.\u0004 ומנין? — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בענין צדקה: \u0003\"השמר לך פן יהיה דבר עם לבבך בליעל וגו'\"\u0004 (דברים טו, ט), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בעבודה זרה: \u0003\"יצאו אנשים בני בליעל\"\u0004 (דברים יג, יד), \u0003מה להלן\u0004 \"בני בליעל\" הוא \u0003עבודה זרה, אף כאן\u0004 משמעו \u0003עבודה זרה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המסמא את עינו\u0004 (עושה עצמו כאילו הוא עיוור) \u0003והמצבה\u0004 (והמנפח) \u0003את בטנו\u0004 כאילו הוא חולה, \u0003והמקפח את שוקו\u0004 כאילו היתה מכווצת, כדי ליהנות מן הצדקה — \u0003אינו נפטר מן העולם עד שיבא לידי כך\u0004 באמת, כלומר, שכך יקרה לו. ובכלל, \u0003המקבל צדקה ואין צריך לכך — סופו אינו נפטר מן העולם עד שיבא לידי כך,\u0004 שיהא זקוק באמת לצדקה.","\u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]:\u0006 איזהו עני שמותר לו לקבל צדקה — כל שיש לו פחות ממאתיים זוז. אבל \u0003אין מחייבין אותו למכור את ביתו ואת כלי תשמישו\u0004 להשלים לסכום זה, אלא מחשבים רק את סכום הכסף שיש לו. ושואלים: \u0003ולא? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003היה\u0004 קודם לכן \u0003משתמש בכלי זהב — ישתמש בכלי כסף,\u0004 היה משתמש \u0003בכלי כסף — ישתמש בכלי נחושת,\u0004 משמע שמחייבים אותו למכור לפחות מקצת כלי תשמישו!","\u0003אמר רב זביד לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שצריך למכור את כליו היקרים ולקנות כלים זולים זולים יותר — הרי זה \u0003במטה ושולחן, הא\u0004 \u0005[זה]\u0006 שאמרנו שאין מחייבים אותו למכור — הרי זה \u0003בכוסות וקערות.\u0004 ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003כוסות וקערות\u0004 ש\u0003לא\u0004 חייב למכור — משום \u0003דאמר: מאיסי לי\u0004 \u0005[שאומר: מאוסים\u0006 הם \u0005עלי]\u0006 הכלים הזולים, ואיני יכול לאכול בהם. אם כן \u0003מטה ושולחן נמי\u0004 \u0005[גם כן]\u0006 \u0003אמר\u0004 \u0005[\u0006הריהו \u0005אומר]:\u0006 \u0003לא מקבל עילואי\u0004 \u0005[איני יכול לסבול אותם],\u0006 שהם גורמים לי אי נוחיות. \u0003אמר רבא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבה:\u0004 מדובר פה \u0003ב\u0004צעצוע, כגון \u0003מחרישה דכספא\u0004 \u0005[מחרישה של כסף]\u0006 שעל שולחנו, שחפצים כאלה צריך למכור, אבל חפצים שהם עיקר צרכיו — אין מחייבים אותו למוכרם.","\u0003רב פפא אמר: לא קשיא\u0004 \u0005[אין זה קשה],\u0006 שאפשר לפרש: \u0003כאן\u0004 שאמרנו שאינו צריך למכור את כלי תשמישו — הרי זה \u0003קודם שיבא לידי גיבוי\u0004 (לפני גבייה), שאם בשעה שנוטל מן הצדקה אין לו מאתים זוז, אף שאם ימכור את כליו יהיו לו מאתים זוז, מכל מקום אין בית דין מחייבים אותו למכור את כליו, ונוטל כדין מן הצדקה. ואילו \u0003כאן\u0004 שאמרנו שצריך למכור את כלי תשמישו — הרי זה \u0003לאחר שיבא לידי גיבוי,\u0004 שאם בשעה שנטל מן הצדקה היו לו מאתים זוז ונטל מן הצדקה שלא כדין, באופן כזה בית הדין גובה ממנו בחזרה את מה שנטל, ואם אין לו ממה לשלם, הריהו מוכר את כלי תשמישו ומשתמש בזולים יותר.","\u0003יתומה שהשיאתה אמה או אחיה\u0004 כשהיתה קטנה, אפילו \u0003מדעתה\u0004 (מרצונה), \u0003וכתבו לה\u0004 נדוניה \u0003במאה או בחמשים זוז\u0004 — \u0003יכולה היא משתגדיל\u0004 (כאשר היא גדלה) \u0003להוציא מידן\u0004 מידי היורשים את הנדוניה \u0003מה שראוי להנתן לה,\u0004 שהוא עשירית מהנכסים, ומה שהסכימה לפחות מההקצבה הרגילה בעודה קטנה אינו נחשב.","\u0003ר' יהודה אומר:\u0004 זה הכלל הוא \u0003אם השיא\u0004 האב בחייו \u0003את הבת הראשונה\u0004 ומת ונתן לה מנכסיו — \u0003ינתן לשניה כדרך שנתן לראשונה,\u0004 בין אם נתן לראשונה עשירית מנכסיו, בין יותר, או פחות. \u0003וחכמים אומרים:\u0004 אין לדבר זה קיצבה פשוטה, כי \u0003פעמים שאדם\u0004 היה באותה שעה \u0003עני ו\u0004אחר כך \u0003העשיר, או\u0004 שהיה \u0003עשיר והעני,\u0004 ואי אפשר לתת קיצבה לפי מה שנתן לבת הראשונה, \u0003אלא שמין\u0004 (מעריכים) \u0003את הנכסים\u0004 כפי שוויים בשעה שנישאת השניה \u0003ונותנין לה\u0004 חלק מסויים מהם.","\u0003אמר שמואל: לפרנסה,\u0004 כלומר, לענין הזה של נדוניה של הבת היתומה — \u0003שמין באב,\u0004 שמעריכים לפי מעמדו של האב, ולפי מה שהיתה דרכו לתת. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003הבנות ניזונות ומתפרנסות מנכסי אביהן.\u0004 ופרטי הדברים \u0003כיצד?\u0004 — \u0003אין אומרים אילו\u0004 היה \u0003אביה קיים, כך וכך היה נותן לה,\u0004 לפי מעמדו ומנהגו, \u0003אלא שמין\u0004 (מעריכים) \u0003את הנכסים, ונותנין לה\u0004 חלק מסויים. משמע שאין שמין את האב. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה \"מתפרנסות\" — ל\u0003פרנסת הבעל,\u0004 כלומר, לענין נדוניה לנישואין. ודוחים: \u0003אמר רב נחמן בר יצחק: לא,\u0004 הכוונה היא \u0003בפרנסת עצמה\u0004 כלומר, מה שמפרנסים אותה ממש במזונות, שבזה נותנים לה קיצבה, בלא קשר לדרכו של האב.","ומקשים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003ניזונות ומתפרנסות קתני\u0004 \u0005[שנה],\u0006 \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה בכפילות זו היא: \u0003אחת\u0004 (\"מתפרנסות\") — ל\u0003פרנסת הבעל, ואחת\u0004 (\"ניזונות\") — מ\u0003פרנסת עצמה?!\u0004 ודוחים: \u0003לא, אידי ואידי\u0004 \u0005[זה וזה]\u0006 ניזונות ומתפרנסות הכוונה היא \u0003בפרנסת עצמה,\u0004 כלומר, לצרכים שלה, \u0003ולא קשיא\u0004 \u0005[ואינו קשה]\u0006 מכפילות הלשון, כי \u0003הא\u0004 \u0005[זו]\u0006 (\"ניזונות\") — הרי זה \u0003באכילה ובשתיה, והא\u0004 \u0005[וזה]\u0006 (\"מתפרנסות\") — הרי זה \u0003בלבושא וכיסויא\u0004 \u0005[בלבוש ו\u0006שאר \u0005כיסויים].\u0006","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003וחכמים אומרים: פעמים שאדם עני והעשיר או עשיר והעני, אלא שמין הנכסים ונותנין לה.\u0004 ונברר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"עני\"\u0004 שם, \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"עשיר\"? אי נימא\u0004 \u0005[אם נאמר\u0006 כפשוטו\u0005]\u0006 \u0003\"עני\"\u0004 כוונתו \u0003עני\u0004 ממש \u0003בנכסים, \"עשיר\"\u0004 כוונתו \u0003עשיר בנכסים,\u0004 האם \u0003מכלל\u0004 הדברים תאמר שה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]\u0006 ש\u0003אפילו\u0004 כשהיה \u0003עשיר והעני כדמעיקרא יהבינן\u0004 \u0005[כמו\u0006 שנתן \u0005מתחילה אנו נותנים]\u0006 \u0003לה,\u0004 לבת השניה — \u0003הא לית ליה\u0004 \u0005[הרי אין לו],\u0006 ואיך אפשר לקחת מנכסיו סכום שווה?","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא \u0003\"עני\" — עני בדעת, \"עשיר\" — עשיר בדעת,\u0004 כלומר, פעמים שאדם היה באופיו בגדר של עני ומקמץ ופעמים הוא בגדר של עשיר ונוהג ברחבות, ואם כן אף על פי שהוא משתנה בדעתו \u0003וקתני\u0004 \u0005[ושנה]\u0006 בכל זאת \u0003שמין את הנכסים ונותנין לה, אלמא לא אזלינן בתר אומדנא\u0004 \u0005[משמע שאין אנו הולכים אחר אומדן\u0006 דעתו של האב\u0005]\u0006 אלא נותנים סכום קצוב, \u0003ותיובתא\u0004 \u0005[ו\u0006הרי זו \u0005קושיה חמורה]\u0006 על דעת \u0003שמואל!\u0004 ומשיבים: שמואל, \u0003הוא\u0004 ש\u0003אמר כ\u0004שיטת \u0003ר' יהודה. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' יהודה אומר: אם השיא בת הראשונה — ינתן לשניה כדרך שנתן לראשונה.\u0004","ושואלים: אם כך, \u0003ונימא\u0004 \u0005[ושיאמר]\u0006 שמואל במפורש: \u0003הלכה כר' יהודה!\u0004 ומשיבים: \u0003אי אמר\u0004 \u0005[אילו היה אומר]\u0006 \u0003הלכה כר' יהודה, הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי זהו \u0003דוקא\u0004 כאשר \u0003השיאה\u0004 בפועל את הבת הראשונה, \u0003דגלי דעתיה\u0004 \u0005[שגילה דעתו]\u0006 כמה הוא נותן בפועל \u0003אבל\u0004 אם \u0003לא השיאה — לא!\u0004 שמא היה משנה את דעתו, על כן \u0003קא משמע לן טעמא\u0004 \u0005[השמיע לנו\u0006 שה\u0005טעם]\u0006 של \u0003ר' יהודה דאזלינן בתר אומדנא\u0004 \u0005[שהולכים אנחנו אחר אומדן,\u0006 הערכת דעתו\u0005],\u0006 \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 כש\u0003השיאה ולא שנא\u0004 \u0005[ואינו שונה]\u0006 כש\u0003לא השיאה\u0004 עדיין,","\u0003והאי דקתני\u0004 \u0005[וזה ששנה]\u0006 \u0003\"השיאה\" —\u0004 הרי זה \u0003להודיעך כחן דרבנן\u0004 \u0005[של חכמים]\u0006 עד כמה הם מפליגים בדעתם \u0003דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003השיאה וגלי דעתיה\u0004 \u0005[וגילה דעתו]\u0006 כמה הוא רוצה לתת לבתו, \u0003לא אזלינן בתר אומדנא\u0004 \u0005[אין אנחנו הולכים אחר ההערכה].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב חסדא: דרשינן משמך\u0004 \u0005[דורשים אנו בשמך]\u0006 כי \u0003הלכה כר' יהודה\u0004 בענין זה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003יהא רעוא\u0004 \u0005[יהי רצון]\u0006 ש\u0003כל כי הני מילי מעלייתא תדרשו משמאי\u0004 \u0005[דברים טובים כאלה תדרשו בשמי],\u0006 כלומר, אף הוא הסכים לדעה זו.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רבא הכי\u0004 \u0005[כך],\u0006 שהלכה כר' יהודה? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003רבי אומר: בת\u0004 שמת אביה והיא \u0003ניזונת מן האחין,\u0004 כלומר, מן הירושה — \u0003נוטלת\u0004 בנדוניה \u0003עישור\u0004 (עשירית) \u0003נכסים\u0004 שזה הסכום הקצוב. \u0003ואמר רבא: הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כרבי\u0004 ובניגוד לדברי ר' יהודה שעושים זאת לפי אומדן דעתו! משיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 — \u0003דאמידניה\u0004 \u0005[שאמדנו אותו]\u0006 ואנו יכולים להעריך כמה היתה כוונתו לתת, אנו הולכים לפי האומדן, וכר' יהודה. \u0003הא\u0004 \u0005[\u0006ו\u0005זה]\u0006 — ש\u0003לא אמידניה\u0004 \u0005[אמדנו אותו],\u0006 אזי נותנים סתם עישור נכסים.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר, ש\u0003אמר רב אדא בר אהבה: מעשה ונתן לה רבי אחד משנים עשר בנכסים\u0004 לנדוניה! לכאורה \u0003קשיין אהדדי\u0004 \u0005[קשים הם זה על זה]\u0006 שהרי בברייתא אמרו שהוא אומר עישור נכסים, \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי \u0003הא\u0004 \u0005[זה]\u0006 — \u0003דאמידניה\u0004 \u0005[שאמדנו אותו]\u0006 ולפי האומדן נותנים, ובמקרה ההוא אמדו אותו שרצה לתת אחד משנים עשר מנכסיו, \u0003הא\u0004 \u0005[זה]\u0006 — ש\u0003לא אמידניה\u0004 \u0005[אמדנו אותו]\u0006 קבע רבי שיעור עישור נכסים. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של אותה הלכה ש\u0003אמר רבי: בת הניזונת מן האחין נוטלת עישור נכסים. אמרו לו לרבי: לדבריך, מי שיש לו עשר בנות ובן,\u0004 אם כן כיון שיתנו לכל בת עישור נכסים \u0003אין לו לבן במקום בנות כלום,\u0004 ואתה מפקיע את ירושתו שהיא מן התורה!","\u0003אמר להן, כך אני אומר:\u0004 זו שבאה \u0003ראשונה\u0004 להינשא \u0003נוטלת עישור נכסים, שניה —\u0004 נוטלת עשירית \u0003במה ששיירה\u0004 הראשונה, כלומר, לא עישור נכסים מן הסכום הראשון, אלא עישור נכסים ממה שנותר אחר שנטלה הראשונה, \u0003ושלישית\u0004 — עשירית \u0003במה ששיירה\u0004 השניה. אלא שלאחר שנטלה כל אחת את חלקה לפי ערך הנכסים בשעה שנישאה, \u0003חוזרות\u0004 כולן ומביאות את שנטלו בחלקן \u0003וחולקות\u0004 את הכל מחדש לפי מספר הבנות \u0003בשוה,\u0004 כדי שלא ייצא שהראשונה מקבלת הרבה יותר. נמצא שלפי מספר הבנות נותנים עישור אחר עישור של הנכסים הנותרים, ואחר כך מחלקים שכל בת תקבל סכום שווה של נדוניה. ואם כן, לעולם ישאר דבר מה עבור הבן."],["\u0003כל חדא וחדא\u0004 \u0005[אחת ואחת]\u0006 בשעה שנוטלת חלקה הלא \u0003דנפשה שקלה\u0004 \u0005[של עצמה\u0006 היא \u0005לוקחת],\u0006 שהרי כדין היא נוטלת כפי ערך הנכסים באותה שעה וזכתה בחלקה, ומדוע תצטרכנה להחזיר ולחלוק מחדש? ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אם באו כולם להנשא כאחת — חולקות בשוה.\u0004 אבל אם נישאו בזו אחר זו, ראשונה נוטלת עישור ראשון.","ומעירים: \u0003מסייע ליה\u0004 \u0005[לו]\u0006 הדבר \u0003לרב מתנה.\u0004 ש\u0003אמר רב מתנה: אם באו להנשא כולם כאחת — נוטלות עישור אחד.\u0004 ותוהים על הלשון: שכולן יחד נוטלות רק \u0003עישור אחד סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר? \u0003אלא\u0004 יש לתקן ולומר: \u0003נוטלות עישור כאחד,\u0004 שנוטלות לפי חשבון עישור, אבל חוזרות וחולקות כולן בשווה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הבנות בין בגרו עד שלא\u0004 (לפני) \u0003נישאו ובין נישאו עד שלא בגרו — איבדו מזונותיהן,\u0004 שאינן ניזונות עוד מן הירושה, \u0003ולא איבדו פרנסתן\u0004 (נדונייתן) אם בגרו, אלו \u0003דברי רבי. ר' שמעון בן אלעזר אומר: אף איבדו פרנסתן,\u0004 שאם בגרו לפני שנישאו, אינן מקבלות את הנדוניה. \u0003כיצד הן עושות\u0004 כדי שלא תפסדנה? — \u0003שוכרות להן בעלים,\u0004 כלומר, דואגות להינשא קודם שיתבגרו \u0003ומוציאין להן פרנסתן.\u0004","\u0003אמר רב נחמן, אמר לי\u0004 רב \u0003הונא: הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כ\u0004שיטת \u0003רבי. איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן\u0004 ממה ששנינו במשנה: \u0003יתומה שהשיאתה אמה או אחיה מדעתה, וכתבו לה\u0004 נדוניה \u0003במאה או בחמשים זוז, יכולה היא משתגדיל להוציא מידם מה שראוי להנתן לה.\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום ש\u0003קטנה\u0004 היתה, \u0003הא\u0004 \u0005[הרי]\u0006 אם היתה \u0003גדולה\u0004 כשנישאת, מניחים כי \u0003ויתרה\u0004 על היתר! וקשה אם כן לרב נחמן שפסק כרבי שלא איבדה פרנסתה כשנישאת.","ודוחים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שלא ויתרה על היתר — הרי זה באופן \u0003דמחאי\u0004 \u0005[שמחתה]\u0006 בשעת קבלת הנדוניה המופחתת, \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שויתרה — הרי זה כש\u0003לא מחאי\u0004 \u0005[מחתה],\u0006 שאנו מניחים שאכן ויתרה על השאר.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לפרש, ש\u0003אם\u0004 לא תאמר \u0003כן, קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003רבי\u0004 על דברי \u0003רבי. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003רבי אומר: בת הניזונת מן האחין,\u0004 אם באה להינשא \u0003נוטלת עישור נכסים.\u0004 ומכאן נדייק: \u0003ניזונת,\u0004 שבאה להינשא בעודה קטנה — \u0003אין\u0004 \u0005[כן]\u0006 נוטלת עישור עישור נכסים, ואולם זו \u0003שאינה ניזונת,\u0004 שבאה להינשא משבגרה — \u0003לא,\u0004 ואם כן הדברים הם ממש היפך דברי רבי בברייתא הקודמת,","\u0003אלא לאו שמע מינה\u0004 \u0005[\u0006האם \u0005לא תלמד מכאן]\u0006 \u0003הא\u0004 \u0005[זה] —\u0006 \u0003דמחאי\u0004 \u0005[שמחתה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 — ש\u0003לא מחאי\u0004 \u0005[מחתה].\u0006 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרבא: אמר לן\u0004 \u0005[לנו]\u0006 \u0003רב אדא בר אהבה משמך: בגרה — אינה צריכה למחות,\u0004 ואפילו אם לא מחתה לא איבדה את עישור הנכסים, וכן אם \u0003נישאת אינה צריכה למחות. בגרה ונישאת — צריכה למחות.\u0004","ותוהים: \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר רבא הכי\u0004 \u0005[כך]?\u0006 \u0003והא איתיביה\u0004 \u0005[והרי הקשה לו]\u0006 לעיל \u0003רבא לרב נחמן\u0004 מדין \u0003יתומה\u0004 שנישאת, \u0003ושני ליה\u0004 \u0005[ותירץ לו]:\u0006 \u0003הא\u0004 \u0005[זה] —\u0006 \u0003דמחי\u0004 \u0005[שמוחה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 — ש\u0003לא מחי\u0004 \u0005[מוחה],\u0006 משמע שצריכה למחות, ואם לא מחתה — איבדה נדונייתה! ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שהיעדר מחאה אינו נחשב לויתור — הרי זה באופן \u0003דקא מיתזנא מינייהו\u0004 \u0005[שהיא ניזונת מהם],\u0006 מן האחים, אף לאחר נישואיה, ולכן מתביישת למחות. \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שאם לא מחתה ודאי ויתרה — הרי זה באופן \u0003דלא קא מיתזנא מינייהו\u0004 \u0005[שאינה ניזונת מהם].\u0006","\u0003אמר רב הונא אמר רבי: פרנסה\u0004 (נדוניה) \u0003אינה כתנאי כתובה.\u0004 מבררים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אינה כתנאי כתובה\"? אי נימא\u0004 \u0005[אם נאמר]\u0006 כך: ש\u0003אילו פרנסה טרפא ממשעבדי\u0004 \u0005[טורפת מן\u0006 הנכסים \u0005המשועבדים],\u0006 שגם אם מכרו האחים מן הנכסים, יש זכות לבת לטרוף מן הלקוחות, \u0003ותנאי כתובה\u0004 אחר \u0003לא טרפא ממשעבדי\u0004 \u0005[אינה טורפת מ\u0006נכסים \u0005משועבדים],\u0006 \u0003מאי קא משמע לן\u0004 \u0005[מה\u0006 חידוש \u0005השמיע לנו\u0006 בזה\u0005],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מעשים בכל יום\u0004 ש\u0003מוציאין לפרנסה\u0004 מן הלקוחות, \u0003ואין מוציאין למזונות.\u0004","\u0003ואלא\u0004 תאמר שההבדל הוא בכך, ש\u0003אילו פרנסה גביא נמי ממטלטלי\u0004 \u0005[גובה\u0006 הבת \u0005גם כן מן המטלטלים\u0006 של האב\u0005]\u0006 \u0003ותנאי כתובה ממקרקעי גביא, ממטלטלי לא גביא\u0004 \u0005[מקרקעות גובה, ממטלטלים אינה גובה].\u0006","והרי \u0003ל\u0004שיטת \u0003רבי אידי ואידי מיגבא גביא\u0004 \u0005[זה וזה\u0006 היא \u0005גובה]\u0006 גם ממטלטלים, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אחד נכסים שיש להן אחריות\u0004 (קרקעות) \u0003ואחד נכסים שאין להן אחריות\u0004 (כגון מטלטלים) — \u0003מוציאין\u0004 מהם \u0003למזון האשה ולבנות,\u0004 אלו \u0003דברי רבי.\u0004","\u0003אלא מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"פרנסה אינה כתנאי כתובה\" — לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003האומר\u0004 בצוואתו \u0003\"אל יזונו בנותיו מנכסיו\" — אין שומעין לו,\u0004 שכיון שמזונות הבנות הן תנאי כתובה, אינו יכול לבטלו. אבל אם אמר \u0003\"אל יתפרנסו בנותיו מנכסיו\" — שומעין לו, שהפרנסה אינה כתנאי כתובה,\u0004 אלא תקנה שחלה על האב או יורשיו, ויכול לומר שאינו רוצה לתת."],["\u0003תלה ליה\u0004 \u0005[לו]\u0006 \u0003רב\u0004 במכתב ששלח \u0003לרבי ביני חטי\u0004 \u0005[בין השורות]\u0006 והוסיף שאלה זו: \u0003האחין ששיעבדו\u0004 את נכסיהם, \u0003מהו\u0004 הדין, האם מוציאים משעבוד זה לנדוניית הבנות? \u0003הוה יתיב\u0004 \u0005[היה יושב]\u0006 \u0003ר' חייא קמיה\u0004 \u0005[לפניו,\u0006 לפני רבי\u0005]\u0006 בשעה שהגיע המכתב. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' חייא: האם הכוונה בשאלתו היא ל\u0003מכרו או\u0004 ל\u0003משכנו?\u0004 שהרי לשון \"שיעבדו\" איננה ברורה ואפשר להבינה גם במשמעות של מכירה, שמכרו את הנכסים והרי זה שיעבוד של קנין, או שהכוונה לשיעבוד של משכנתא בלבד. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי: \u0003מאי נפקא מינה\u0004 \u0005[מה יוצא ממנה,\u0006 מה ההבדל בזה\u0005]?\u0006 הלא \u0003בין מכרו בין שמשכנו מוציאין לפרנסה ואין מוציאין למזונות!\u0004","ושואלים לעצם הענין: \u0003ורב\u0004 עצמו, \u0003אי\u0004 \u0005[אם]\u0006 דין \u0003מכרו\u0004 נכסים \u0003קמיבעיא ליה\u0004 \u0005[נסתפק לו],\u0006 אם כן \u0003נכתוב ליה\u0004 \u0005[שיכתוב לו]\u0006 במפורש \u0003\"\u0004האחים ש\u0003מכרו\"? אי\u0004 \u0005[אם]\u0006 דין \u0003משכנו קא מיבעיא ליה\u0004 \u0005[נסתפק לו],\u0006 אם כן \u0003נכתוב ליה\u0004 \u0005[שיכתוב לו]\u0006 \u0003\"\u0004האחים ש\u0003משכנו\"?!\u0004","ומשיבים: \u0003רב תרוייהו קמבעיא ליה\u0004 \u0005[\u0006ב\u0005שניהם נסתפק לו]\u0006 \u0003וסבר\u0004 \u0005[וחשב]:\u0006 \u0003אי כתיבנא ליה\u0004 \u0005[אם כותב אני לו]\u0006 שאלה רק בענין \u0003מכרו, הא ניחא\u0004 \u0005[זה נוח]\u0006 \u0003אי שלח\u0004 \u0005[אם ישלח]\u0006 \u0003לי\u0004 בתשובה ש\u0003מוציאין —\u0004 אם כן אבין ש\u0003כל שכן\u0004 אם רק \u0003משכנו\u0004 ודאי מוציאים. אבל \u0003אי שלח\u0004 \u0005[אם ישלח]\u0006 \u0003לי\u0004 תשובה ש\u0003אין מוציאין, אכתי\u0004 \u0005[עדיין]\u0006 בענין \u0003משכנו קמיבעיא\u0004 \u0005[יסתפק]\u0006 \u0003לי\u0004 ולהיפך:","\u0003אי כתיבנא ליה\u0004 \u0005[אם כותב אני לו]\u0006 רק בענין \u0003משכנו, אי שלח\u0004 \u0005[אם ישלח]\u0006 \u0003לי\u0004 בתשובה ש\u0003אין מוציאין\u0004 — אבין ש\u0003כל שכן\u0004 אם \u0003מכרו\u0004 אין מוציאים. אבל \u0003אי שלח\u0004 \u0005[אם ישלח]\u0006 \u0003לי\u0004 בתשובה ש\u0003מוציאין,\u0004 אם כן \u0003אכתי\u0004 \u0005[עדיין]\u0006 בענין \u0003מכרו קא מיבעיא\u0004 \u0005[יסתפק]\u0006 \u0003לי,\u0004 ולכן \u0003אכתוב ליה\u0004 \u0005[לו]\u0006 שאלה בענין \u0003שיעבדו,\u0004 ש\u0003משמע הכי\u0004 \u0005[כך]\u0006 \u0003ומשמע הכי\u0004 \u0005[כך]\u0006 ואקבל תשובה מלאה לשאלה.","\u0003ור' יוחנן אמר: אחד זה ואחד זה,\u0004 בין לפרנסה בין למזונות, \u0003אין מוציאין. איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003לר' יוחנן,\u0004 האם \u0003לא שמיע ליה\u0004 \u0005[שמע]\u0006 \u0003הא\u0004 \u0005[\u0006את הפסק \u0005הזה]\u0006 של \u0003רבי ואי שמיע ליה הוה מקבל ליה\u0004 \u0005[ואם היה שומע אותו היה מקבל אותו],\u0006 \u0003או דלמא שמיע ליה\u0004 \u0005[שמא שמע אותו]\u0006 \u0003ולא מקבל ליה\u0004 \u0005[קיבל אותו]?\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 הוכחה ממה \u0003דאתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו אמוראים בבעיה הבאה: \u0003מי שמת והניח שתי בנות ובן, וקדמה\u0004 הבת \u0003הראשונה ונטלה עישור נכסים\u0004 לנדונייתה כדין בת במקום בן, \u0003ולא הספיקה שניה לגבות\u0004 גם היא \u0003עד שמת הבן\u0004 ונשארה הנחלה כולה לשתי הבנות, והן מתחלקות בירושה,","\u0003אמר ר' יוחנן: שניה ויתרה.\u0004 כלומר, השניה מקבלת רק מחצית מן הירושה שנשארה, ולא מקבלת גם את חלקה בעישור הנכסים מן החלק של הבת הראשונה. \u0003אמר ר' חנינא,\u0004 הלא \u0003גדולה מזו אמרו: מוציאין לפרנסה ואין מוציאין למזונות,\u0004 שאפילו כשהיו הנכסים משועבדים לאחרים מוציאים לפרנסה, \u0003ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 כי ה\u0003שניה ויתרה\u0004 אפילו כשהנכסים לא נמכרו?!","\u0003ואם איתא\u0004 \u0005[יש]\u0006 שלא שמע ר' יוחנן מעולם הלכה זו של רבי, \u0003נימא ליה\u0004 \u0005[שיאמר לו]\u0006 ר' יוחנן: \u0003מאן\u0004 \u0005[מי]\u0006 \u0003אמרה\u0004 להלכה זו שמוציאים לפרנסה? אלא ודאי שמע הלכה זו, ולא קיבלה. ודוחים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003לעולם\u0004 תאמר ש\u0003לא שמיע ליה\u0004 \u0005[שמע אותה]\u0006 \u0003וכי שמיע ליה קביל\u0004 \u0005[ואם היה שומע\u0006 אותה הלכה בשם רבי, היה \u0005מקבל],\u0006 \u0003ו\u0004אולם דחה את דברי ר' חנינא כי \u0003שאני התם\u0004 \u0005[ושונה שם],\u0006 במקרה שמת הבן, \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003רווח ביתא\u0004 \u0005[בבית],\u0006 שכיון שמקבלת מחצית הירושה כולה, שוב אינה מקפידה לקבל עישור נכסים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יימר לרב אשי: אלא מעתה\u0004 לפי סברה זו, אם \u0003אשכחה\u0004 \u0005[מצאה]\u0006 הבת \u0003מציאה בעלמא\u0004 \u0005[סתם]\u0006 \u0003דאיכא\u0004 \u0005[ש\u0006אף בכך \u0005יש]\u0006 \u0003רווח ביתא\u0004 \u0005[בבית]\u0006 \u0003הכי נמי דלא יהבינן\u0004 \u0005[כך גם כן שאין אנו נותנים]\u0006 \u0003לה עישור נכסים?!\u0004 ואם כן פשוט, שגם אם יש לה עכשיו יותר כסף משלה, לא בטלה זכותה על הנכסים. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא רווח ביתא מהני נכסי קאמינא\u0004 \u0005[אני רווח הבית מאותם הנכסים\u0006 שהשאיר האב \u0005אמרתי],\u0006 שאינה מקפידה ליטול חלקה מהם כשיש לה חלק בירושה, אבל אם הרויחה באופן אחר, ודאי אינה מוותרת.","לעצם זכות הבנות לפרנסה \u0003אמר אמימר: בת יורשת הויא\u0004 \u0005[היא],\u0006 שלענין זכותה לקבל נדוניה מן הנכסים, דינה כדין יורשת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לאמימר:\u0004 לפי שיטה זו \u0003אילו בעי לסלוקה בזוזי הכי נמי\u0004 \u0005[אם\u0006 היה \u0005רוצה\u0006 היורש \u0005לסלק אותה בזוזים,\u0006 בכסף, \u0005כך גם כן]\u0006 ש\u0003לא מצי לסלוקה\u0004 \u0005[\u0006היה \u0005יכול לסלק אותה]\u0006 והיה חיוב לתת לה מן הקרקעות עצמם כדין ירושה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן]\u0006 כך אני סבור. חזר ושאל רב אשי: \u0003אי בעי לסלוקה בחדא ארעא, הכי נמי דלא מצי מסלק לה?\u0004 \u0005[אם\u0006 היה \u0005רוצה לסלק אותה\u0006 ולשלם לה \u0005בקרקע אחת\u0006 מסויימת, \u0005כך גם כן שאינו יכול לסלק אותה],\u0006 שהרי אם היא יורשת יש לה זכות בקרקעות כולם, והיא זכאית להתחלק בכולם? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006","ואילו \u0003רב אשי\u0004 עצמו \u0003אמר: בת בעלת חוב הויא\u0004 \u0005[היא],\u0006 כלומר, דינה כדין בעל חוב לכל ענין. ומעירים: \u0003ואף אמימר הדר ביה\u0004 \u0005[חזר בו]\u0006 משיטה זו שיורשת היא. ש\u0003אמר רב מניומי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב ניחומי: הוה קאימנא קמיה\u0004 \u0005[הייתי עומד לפני]\u0006 \u0003אמימר, ואתאי האי איתתא לקמיה, דהות קא בעיא\u0004 \u0005[ובאה אשה אחת לפניו, שרצתה]\u0006 \u0003עישור נכסים\u0004 מנכסי אביה. \u0003וחזיתיה לדעתיה\u0004 \u0005[וראיתי את דעתו]\u0006 של אמימר \u0003דאי בעי לסלוקה בזוזי הוי מסלק לה\u0004 \u0005[שאם היה רוצה לסלק אותה בכספים\u0006 ולשלם לה את הסכום הזה בכסף \u0005היה\u0006 יכול \u0005לסלק אותה].\u0006 וכיצד הבנתי שזו דעת אמימר — \u0003דשמעי מאחי דהוו קאמרי\u0004 \u0005[ששמעתי את האחים\u0006 של אותה אשה \u0005שהיו אומרים]\u0006 \u0003לה: אילו הוה לן זוזי, סליקנא בזוזי\u0004 \u0005[אילו היה לנו זוזים,\u0006 כסף, \u0005היינו מסלקים\u0006 אותך \u0005בזוזים,\u0006 בכסף\u0005]\u0006 \u0003ואישתיק\u0004 \u0005[ושתק]\u0006 אמימר \u0003ולא אמר להו\u0004 \u0005[להם]\u0006 \u0003ולא מידי\u0004 \u0005[דבר].\u0006 משמע שאף הוא הסכים שדינה כדין בעל חוב והיו יכולים לעשות כן, שלולא זה היה צריך לומר להם שאינם רשאים לסלק אותה בכסף.","ומעירים: \u0003והשתא\u0004 \u0005[ועכשיו]\u0006 ש\u0003אמרת\u0004 והגעת למסקנה שהבת הזו \u0003בעלת חוב הויא\u0004 \u0005[היא],\u0006 אם כן יש לשאול בעלת חוב של מי היא: \u0003דאבא\u0004 \u0005[של האב]\u0006 \u0003או\u0004 של \u0003אחי\u0004 \u0005[האחים]?\u0006 ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה]\u0006 מיהו החייב לה? שהרי על כל פנים היא גובה חלקה מן הירושה! ומשיבים: \u0003למיגבא\u0004 \u0005[לגבות]\u0006 \u0003ל\u0004קרקע \u0003בינונית שלא בשבועה, וזיבורית\u0004 (קרקע גרועה) \u0003בשבועה.\u0004 שאם היא בעלת חוב של האב — הרי מת האב, וכשהיא גובה מנכסי היתומים יכולה לגבות רק מקרקע זיבורית, ורק בשבועה. ואם היא בעלת חוב של הבנים — יכולה לקבל מקרקע בינונית ובלא שבועה כמו שאר בעלי חובות שלהם.","אם כן \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 ומספרים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 הוכחה לכך ממה ש\u0003רבינא אגביה לברתיה\u0004 \u0005[הגבה,\u0006 נתן, \u0005לבתו]\u0006 של \u0003רב אשי ממר בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אשי,\u0004 שהיתה צריכה לקבל מן הירושה עישור נכסים, והגבה לה מקרקע \u0003בינונית, ושלא בשבועה.\u0004 ואת חלק הנכסים שגבה \u0003מבריה\u0004 \u0005[מבנו]\u0006 של \u0003רב סמא בריה\u0004 \u0005[בנו]\u0006 השני של \u0003רב אשי\u0004 (שרב סמא מת, וחלקו בירושת רב אשי עבר לבנו), הגבה לה מקרקע \u0003זבורית, בשבועה.\u0004 שהרי במקרה זה בודאי נחשב הדבר כגביית חוב מן היתום בן רב סמא, שהיא בעלת החוב שלו, ודינה בזיבורית. ואם כן רואים שלדעתו הבת היא בעלת חוב של האחים.","ועוד בענין זה, \u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמיה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף לרבה בר רב הונא זוטא\u0004 \u0005[הקטן]\u0006 \u0003מנהרדעא: כי אתיא הא איתתא לקמך, אגבה\u0004 \u0005[כאשר תבוא אשה זו,\u0006 מוסרת מכתב זה, \u0005לפניך, הגבה לה]\u0006 \u0003עישור נכסים אפילו מאיצטרובלא\u0004 \u0005[ממקום הריחיים]\u0006 שגם הוא נחשב לקרקע. \u0003אמר רב אשי: כי הוינן בי\u0004 \u0005[כאשר היינו\u0006 ב\u0005בית]\u0006 \u0003רב כהנא\u0004 כתלמידים, \u0003הוה מגבינן\u0004 \u0005[היינו גובים]\u0006 את עישור הנכסים \u0003אפילו מעמלא דביתי\u0004 \u0005[משכירות הבתים],\u0006 משום שכסף זה בא מפירות הקרקעות.","מסופר: \u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003רב ענן לרב הונא\u0004 מכתב זה: \u0003הונא חברין\u0004 \u0005[חברינו],\u0006 \u0003שלם\u0004 \u0005[שלום]!\u0006 \u0003כי אתיא הא איתתא לקמך אגבה\u0004 \u0005[כאשר תבוא אשה זו\u0006 מוסרת המכתב \u0005לפניך, הגבה לה]\u0006 \u0003עישור נכסי\u0004 \u0005[\u0006מן \u0005הנכסים].\u0006 \u0003הוה יתיב\u0004 \u0005[היה יושב]\u0006 \u0003רב ששת קמיה\u0004 \u0005[לפניו]\u0006 לפני רב הונא, ו\u0003אמר ליה\u0004 \u0005[לו]\u0006 לרב ששת: \u0003זיל אימא ליה\u0004 \u0005[לך אמור לו,\u0006 לרב ענן\u0005]\u0006 מה שאומר לך, וכיון שידע שלא יהיה נוח הדבר לרב ששת, הוסיף: \u0003ובשמתא יהא מאן\u0004 \u0005[ובנידוי יהיה מי]\u0006 ש\u0003לא אמר ליה\u0004 \u0005[יאמר לו]\u0006 בדיוק בלשון שאומר. וכך אמור לו: \u0003\"ענן ענן!\u0004 האם להגבות לה \u0003ממקרקעי\u0004 \u0005[מקרקעות]\u0006 \u0003או ממטלטלי\u0004 \u0005[ממטלטלים]\u0006 \u0003\"?\u0004 ועוד שאל אותו: \u0003\"ומאן יתיב בי מרזיחא ברישא\u0004 \u0005[ומי יושב\u0006 ב\u0005בית המרזח בראש]\u0006\"?","\u0003אזל\u0004 \u0005[הלך]\u0006 \u0003רב ששת לקמיה\u0004 \u0005[לפני]\u0006 \u0003רב ענן ואמר ליה\u0004 \u0005[לו]\u0006 כך: \u0003מר\u0004 \u0005[אדוני]\u0006 הוא \u0003רבה\u0004 \u0005[גדול],\u0006 \u0003ו\u0004אולם \u0003רב הונא\u0004 הוא \u0003רביה דרבה\u0004 \u0005[רבו של הרב],\u0006 \u0003ו\u0004נוסף לכך אף \u0003שמותי שמית מאן\u0004 \u0005[נידה\u0006 את \u0005מי]\u0006 ש\u0003לא אמר ליה\u0004 \u0005[יאמר לו\u0006 (לך)\u0005]\u0006 בלשון זה, \u0003ואי לאו דשמית\u0004 \u0005[ואם לא שהיה מנדה]\u0006 \u0003לא הוה קאמינא\u0004 \u0005[הייתי אומר\u0006 זאת\u0005],\u0006 שרצה להקדים ולהתנצל על שהוא אומר לו דברים קשים אלה: \u0003\"ענן, ענן,\u0004 האם להגבות לאשה זו \u0003ממקרקעי\u0004 \u0005[מקרקעות]\u0006 \u0003או ממטלטלי\u0004 \u0005[ממטלטלים],\u0006 \u0003ומאן יתיב בי מרזיחא ברישא\u0004 \u0005[ומי יושב\u0006 ב\u0005בית המרזח בראש]\u0006\"?","\u0003אזל\u0004 \u0005[הלך]\u0006 \u0003רב ענן לקמיה\u0004 \u0005[לפני]\u0006 \u0003מר עוקבא\u0004 ראש הגולה \u0003ואמר ליה\u0004 \u0005[לו]\u0006 בתרעומת: \u0003חזי מר\u0004 \u0005[יראה אדוני]\u0006 \u0003היכי\u0004 \u0005[איך]\u0006 \u0003שלח לי רב הונא\u0004 שליחות בזלזול \u0003\"ענן ענן\", ועוד \"מרזיחא\"\u0004 ש\u0003שלח לי\u0004 בשליחות הזו \u0003לא ידענא מאי ניהו\u0004 \u0005[איני יודע מה הוא].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 מר עוקבא: \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003לי איזי\u0004 \u0005[ידידי]\u0006"],["\u0003גופא דעובדא היכי הוה\u0004 \u0005[גוף המעשה איך היה],\u0006 כיצד הגיעו הדברים לידי כך? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי והכי הוה\u0004 \u0005[כך וכך היה]\u0006 ה\u0003מעשה\u0004 וסיפר לו. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003גברא דלא ידע מאי ניהו\u0004 \u0005[אדם שאינו יודע מהו\u0006 פירוש\u0005]\u0006 \u0003\"מרזיחא\", שלח ליה\u0004 \u0005[שולח לו]\u0006 \u0003לרב הונא\u0004 מכתב וכותב לו \u0003\"הונא חברין\u0004 \u0005[חברינו]\u0006 \u0003\"?\u0004 אלא היית צריך לכתוב לו בלשון כבוד, ובצדק נפגע רב הונא. ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מרזיחא\"? — אבל, דכתיב\u0004 \u0005[שנאמר]:\u0006 \"כי \u0003כה אמר ה' אל תבא בית מרזח\u0004 ואל תלך לספוד ואל תנד להם\" (ירמיה טז, ה).","\u0003אמר ר' אבהו\u0004 באותו ענין: \u0003מנין לאבל שמיסב בראש\u0004 כשבאים לנחמו — \u0003שנאמר: \"אבחר דרכם ואשב ראש ואשכון כמלך בגדוד כאשר אבלים ינחם\"\u0004 (איוב כט, כה) ותוהים: הלא \u0003\"ינחם\" אחרים משמע,\u0004 שהמנחם את האבל הוא היושב בראש! \u0003אמר רב נחמן בר יצחק:\u0004 כיון שאין ניקוד במקרא, אפשר לפרשו כאילו \u0003\"ינחם\" כתיב\u0004 \u0005[נאמר],\u0006 כלומר, כאשר האבל מתנחם הוא יושב בראש.","\u0003מר זוטרא אמר: מהכא\u0004 \u0005[מכאן]\u0006 יש ראיה לדבר: \u0003\"וסר מרזח סרוחים\"\u0004 (עמוס ו, ז) — מי שהוא \u0003מר\u0004 (ממורמר באבלו) \u0003וזח,\u0004 כלומר, שדעתו זזה ממקומה בגלל אבלו — הוא \u0003נעשה שר לסרוחים\u0004 (ליושבים), לאלה הבאים לבקרו ויושבים איתו.","ולסיכום ההלכה \u0003אמר רבא: הלכתא\u0004 \u0005[הלכה\u0006 היא\u0005]:\u0006 גובים מן היורשים \u0003ממקרקעי\u0004 \u0005[מקרקעות]\u0006 \u0003ולא ממטלטלי\u0004 \u0005[ממטלטלים],\u0006 \u0003בין למזוני\u0004 \u0005[למזונות],\u0006 \u0003בין לכתובה, בין לפרנסה,\u0004 לצורך נדוניה של הבנות.","\u0003המשליש מעות,\u0004 שמוסר מעות בידי אדם שלישי \u0003ל\u0004צורך נדוניית \u0003בתו\u0004 שיקנה עבורה שדה לכשתינשא, \u0003והיא אומרת\u0004 לאחר שנישאה: \u0003נאמן בעלי עלי\u0004 ותנו לו את הכסף והוא יקנה בו נכסים עבורי — \u0003יעשה השליש מה שהושלש בידו,\u0004 לפי ההוראות שניתנו לו על ידי אביה, והוא יקנה עבורה קרקע, אלו \u0003דברי ר' מאיר. ר' יוסי אומר:\u0004 אין כל תועלת שהשליש יקנה קרקע, \u0003וכי אינה,\u0004 כלומר, אילו ההשלשה הזו לא היתה כסף \u0003אלא שדה\u0004 ממש בידי השליש, \u0003והיא\u0004 האשה היתה \u0003רוצה למוכרה\u0004 — הלא היתה מוכרת, \u0003הרי\u0004 גם כשלא מכרה, \u0003היא,\u0004 השדה, כאילו \u0003מכורה\u0004 כבר \u0003מעכשיו,\u0004 וכיון שאין דרך להבטיח שהשדה יישאר ביד האשה ולא תמכרנו, הרי גם כשההשלשה היתה במעות רשאית לתיתם לבעלה. ומוסיפים: \u0003במה דברים אמורים — בגדולה\u0004 (מבוגרת), \u0003אבל בקטנה,\u0004 כיון ש\u0003אין מעשה קטנה כלום\u0004 — אין שומעים לה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המשליש מעות\u0004 אצל אדם שלישי \u0003לחתנו\u0004 (עבור חתנו) על מנת \u0003ליקח\u0004 (לקנות) \u0003מהן שדה לבתו, והיא אומרת: ינתנו\u0004 המעות האלה \u0003לבעלי\u0004 וישקיע אותם כפי דעתו, אם היה זה \u0003מן הנשואין,\u0004 לאחר שכבר נשאה — \u0003הרשות בידה, מן האירוסין — יעשה השליש\u0004 בכסף כפי \u0003מה שהושלש בידו,\u0004 לפי התנאי שהתנה אביה, והוא יקנה לה שדה, אלו \u0003דברי ר' מאיר. ר' יוסי אומר:\u0004 אם היתה \u0003ה\u0004אשה שאמרה זאת \u0003גדולה\u0004 (מבוגרת) — \u0003בין מן הנשואין ובין מן האירוסין הרשות בידה. קטנה — בין מן הנשואין בין מן האירוסין יעשה השליש מה שהושלש בידו.\u0004","ומבררים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם],\u0006 בין ר' מאיר ור' יוסי, הלכה למעשה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שבענין \u0003קטנה מן הנשואין איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005],\u0006 ש\u0003ר' מאיר סבר\u0004 כי \u0003הרשות בידה,\u0004 ששומעים לה, \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' יוסי למימר\u0004 \u0005[לומר]\u0006 כי \u0003אפילו מן הנשואין נמי\u0004 \u0005[גם כן]\u0006 \u0003גדולה — אין\u0004 \u0005[כן],\u0006 הרשות בידה למסור לבעלה, \u0003קטנה — לא.\u0004","\u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של המשנה: \u0003אבל בקטנה — אין מעשה קטנה כלום.\u0004 ונברר: \u0003הא מאן קתני לה\u0004 \u0005[\u0006הלכה \u0005זו מי שנה אותה]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כי \u0003ר' יוסי\u0004 שנאה — \u0003הא מרישא שמעת מינה\u0004 \u0005[הרי\u0006 כבר \u0005מן ההתחלה\u0006 של המשנה \u0005אתה שומע\u0006 את הסברה \u0005הזו],\u0006 שכן \u0003אמר ר' יוסי: וכי אינה אלא שדה והיא רוצה למוכרה — הרי היא מכורה מעכשיו.\u0004 אם כן לגבי \u0003גדולה\u0004 שהיא \u0003בת זביני\u0004 \u0005[\u0006רשות ל\u0005מכירה] —\u0006 \u0003אין\u0004 \u0005[כן]\u0006 שומעין לה, \u0003קטנה דלאו\u0004 \u0005[שלא]\u0006 \u0003בת זביני\u0004 \u0005[\u0006רשות ל\u0005מכירה]\u0006 \u0003היא — לא\u0004 שומעין לה!","\u0003אלא\u0004 ודאי שקטע אחרון זה שיטת \u0003ר' מאיר היא, וחסורי מיחסרא והכי קתני\u0004 \u0005[וחסרה\u0006 המשנה \u0005וכך\u0006 היא \u0005שנויה]:\u0006 \u0003יעשה השליש מה שהושלש בידו. במה דברים אמורים — מן האירוסין, אבל מן הנשואין — הרשות בידה. במה דברים אמורים — בגדולה, אבל בקטנה אין מעשה קטנה כלום.\u0004 הרי שגם לרבי מאיר אין רשות ביד קטנה למסור לבעלה. \u0003אלא\u0004 צריך לומר כי לענין \u0003גדולה מן האירוסין איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005],\u0006 שלדעת ר' מאיר, מן האירוסין אין לה רשות, ולדעת ר' יוסי, כיון שהיא גדולה — שומעים לה.","\u0003איתמר\u0004 \u0005[נאמר],\u0006 שנחלקו אמוראים בהלכה זו, ש\u0003רב יהודה אמר\u0004 בשם \u0003שמואל: הלכה כר' יוסי,\u0004 ו\u0003רבא אמר\u0004 בשם \u0003רב נחמן: הלכה כר' מאיר.\u0004","מסופר, כי החכם \u0003אילפא\u0004 כאשר לא מינו אותו לראש ישיבה, משום שהיה במקום אחר, ומינו במקומו את ר' יוחנן, חשש שיאמרו שהעדיפו את ר' יוחנן על פניו משום שאינו חכם כמותו, ולכן \u0003תלא נפשיה באיסקריא דמכותא\u0004 \u0005[תלה\u0006 את \u0005עצמו בתורן הספינה]\u0006 ו\u0003אמר: איכא דאתי דאמר\u0004 \u0005[\u0006אם \u0005יש\u0006 מי \u0005שיבוא ויאמר]\u0006 \u0003לי מילתא דבי\u0004 \u0005[דבר ש\u0006נשנה בברייתות הנשנות \u0005בבית\u0006 מדרשם\u0005]\u0006 של \u0003ר' חייא ור' אושעיא ולא פשיטנא ליה ממתניתין\u0004 \u0005[אפתור לו\u0006 אותה \u0005ממשנתנו]\u0006 להוכיח שהיא רמוזה במשנה, \u0003נפילא מאסקריא וטבענא\u0004 \u0005[נופל אני מן התורן וטובע],\u0006 שרצה להראות כמה גדול כוחו בתורה.","\u0003אתא ההוא סבא תנא ליה\u0004 \u0005[בא זקן אחד\u0006 ו\u0005שנה לו]\u0006 ברייתא זו: \u0003האומר \"תנו שקל לבני בשבת\u0004 (בכל שבוע) \u0003\", וראוין\u0004 לפי צרכיהם \u0003ליתן להם סלע\u0004 (שהוא שני שקלים) — \u0003נותנין להם סלע. ואם אמר \"אל תתנו להם אלא שקל\" — אין נותנין להם אלא שקל\u0004 בלבד. כי רואים שהקפיד בדבר, ועושים את רצונו. ואם הם נזקקים ליותר — יטלו את השאר מן הצדקה. \u0003ואם אמר \"אם מתו\u0004 בני \u0003יירשו אחרים תחתיהם\",\u0004 שאם ימותו בקטנותם בלא יורשים תעבור נחלתם לאחרים במקומם, \u0003בין שאמר \"תנו\u0004 שקל \u0003\", בין שאמר \"אל תתנו\u0004 אלא שקל \u0003\"\u0004— \u0003אין נותנים להם אלא שקל,\u0004 שהרי מדבריו רואים שהוא מקפיד בדבר, ורוצה שתשאר הנחלה גם לאחרים. ושאל אותו: היכן רמוזה הלכה זו במשנתנו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אילפא: \u0003הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]?\u0006 —"],["\u0003ר' מאיר היא,\u0004 ש\u0003אמר: מצוה לקיים דברי המת.\u0004 שהרי כבר אמר במשנתנו שהשליש צריך לעשות מה שהושלש בידו, גם אם האשה תשנה אחר כך מן הדברים.","\u0003אמר רב חסדא אמר מר עוקבא: הלכתא\u0004 \u0005[הלכה\u0006 היא\u0005]:\u0006 \u0003בין שאמר \"תנו\u0004 שקל \u0003\"\u0004\u0003ובין שאמר \"אל תתנו\u0004 אלא שקל \u0003\"\u0004— \u0003נותנין להם כל צורכם.\u0004 ותוהים: \u0003הא קיימא לן\u0004 \u0005[הרי מוחזק בידינו]\u0006 ש\u0003הלכה כ\u0004שיטת \u0003ר' מאיר\u0004 ש\u0003אמר: מצוה לקיים דברי המת,\u0004 ומדוע אין מקיימים את דבריו? ומשיבים: \u0003הני מילי במילי אחרניתא\u0004 \u0005[דברים אלה\u0006 אמורים דווקא \u0005בדברים אחרים],\u0006 שודאי מצוה לקיים את דברי המת, \u0003אבל בהא מינח ניחא ליה\u0004 \u0005[ב\u0006מקרה \u0005זה נוח לו]\u0006 שיתפרנסו בניו בכבוד, \u0003והא\u0004 \u0005[וזה]\u0006 ש\u0003אמר הכי\u0004 \u0005[כך],\u0006 שהוא נותן להם שקל בלבד — \u0003לזרוזינהו\u0004 \u0005[לזרז אותם]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא],\u0006 שרצה שינהגו חסכון בממונם.","\u0003תנן התם\u0004 \u0005[שנינו שם,\u0006 במשנה במסכת גיטין\u0005]:\u0006 \u0003הפעוטות מקחן מקח וממכרן מכר במטלטלים,\u0004 אבל לא בקרקעות, שאינם יכולים לקנות או למכור קרקעות, עד שיגדלו.","\u0003אמר רפרם: לא שנו\u0004 הלכה זו \u0003אלא\u0004 כ\u0003שאין שם אפוטרופוס\u0004 לנכסי המת שנתמנה על ידי האב או על ידי בית־דין, \u0003אבל\u0004 אם \u0003יש שם אפוטרופוס — אין מקחן מקח, ואין ממכרן מכר.\u0004","\u0003ממאי\u0004 \u0005[ממה\u0006 מנין\u0005]\u0006 יודע הוא דבר זה? — \u0003מדקתני\u0004 \u0005[מ\u0006מה \u0005ששנה]\u0006 במשנתנו: שכשיש שליש (שהוא כאפוטרופוס) \u0003אין מעשה קטנה כלום.\u0004 ומקשים: \u0003ודלמא היכא דאיכא\u0004 \u0005[ושמא במקום שיש]\u0006 \u0003שליש שאני\u0004 \u0005[שונה]\u0006 הדין, אבל במקום שאין שליש המחזיק במטלטלים, שמא יש לקטנים רשות למכור? ומשיבים על כך: \u0003אם כן ליתני\u0004 \u0005[שישנה]\u0006 \u0003אבל בקטנה יעשה שליש מה שהושלש בידו. מאי\u0004 \u0005[מה]\u0006 ההדגשה במילים \u0003\"אין מעשה קטנה כלום\"? שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003אפילו בעלמא\u0004 \u0005[בכלל],\u0006 כאשר יש אפוטרופוס לנכסים שהוא דומה לשליש, אין רשות לקטנה לעשות דבר מדעתה.","","\u0003המדיר את אשתו מליהנות לו\u0004 שאוסר עליה בנדר כל הנאה ממנו, אם הדיר אותה \u0003עד שלשים יום — יעמיד פרנס,\u0004 ימנה אדם אחר, והוא יפרנסנה. ואם הדיר אותה \u0003יתר מיכן\u0004 \u0005[יותר מזה] —\u0006 \u0003יוציא\u0004 (יגרש) \u0003ויתן כתובה\u0004 לאשה.","","\u0003ר' יהודה אומר:\u0004 יש לחלק: אם היה זה \u0003בישראל\u0004 שהבעל הוא ישראל, שיכול לחזור ולשאת את גרושתו, אם הדיר אותה \u0003חדש אחד — יקיים, ושנים — יוציא ויתן כתובה.\u0004 אבל \u0003בכהן\u0004 שהוא אסור בגרושה, וגם בגרושתו שלו, ואם יגרש את אשתו שוב אינו רשאי להחזירה — נותנים לו זמן נוסף; \u0003שנים\u0004 (שני חדשים) — \u0003יקיים, ושלשה\u0004 — \u0003יוציא ויתן כתובה.\u0004","ועוד: \u0003המדיר את אשתו\u0004 שאוסר עליה בנדר \u0003שלא תטעום אחד מכל הפירות — יוציא ויתן כתובה. ר' יהודה אומר: בישראל — יום אחד יקיים, שנים — יוציא ויתן כתובה, ובכהן — שנים יקיים, שלשה — יוציא ויתן כתובה.\u0004 \u0003המדיר את אשתו שלא תתקשט באחד מכל המינין\u0004 של בשמים — \u0003יוציא ויתן כתובה. ר' יוסי אומר:\u0004 יש להבחין בין סוגי נשים; \u0003בעניות\u0004 — דין זה הוא רק ב\u0003שלא נתן קצבה,\u0004 שלא קבע זמן קצוב לאיסור להתקשט, \u0003ובעשירות\u0004 שרגילות להתקשט יותר, אם הדיר אותה מלהתקשט \u0003שלשים יום\u0004 — יוציא ויתן כתובה.","על עצם הענין שאדם מדיר את אשתו מליהנות לו תוהים: \u0003וכיון\u0004 שהוא \u0003משועבד לה\u0004 לתת לה מזונות, לפי ההסכם שבכתובה, \u0003היכי מצי מדיר לה\u0004 \u0005[איך\u0006 הוא \u0005יכול להדיר אותה]?\u0006 \u0003כל כמיניה דמפקע\u0004 \u0005[האם בכוחו להפקיע]\u0006 \u0003לה\u0004 את \u0003שיעבודה?\u0004","\u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 אשה שאמרה \u0003\"קונם,\u0004 אסור עלי בנדר, \u0003שאיני עושה לפיך\",\u0004 כלומר, איני עושה בשבילך מלאכה — \u0003אינו צריך להפר,\u0004 שלא חל נדר זה כלל. \u0003אלמא\u0004 \u0005[מכאן]\u0006 \u0003כיון דמשעבדא ליה\u0004 \u0005[שמשועבדת\u0006 היא \u0005לו]\u0006 מכוח תקנת חכמים לעשות לו מלאכה, \u0003לאו כל כמינה דמפקע ליה לשיעבודיה\u0004 \u0005[אין זה בכוחה להפקיע לו את שעבודו]\u0006 — \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003כיון\u0004 ש\u0003משועבד\u0004 הוא \u0003לה\u0004 למזונותיה, \u0003לאו כל כמיניה דמפקע\u0004 \u0005[אין זה בכוחו שיפקיע]\u0006 \u0003לה\u0004 את \u0003שיעבודה!\u0004","\u0003אלא\u0004 כך צריך לומר: \u0003מתוך שיכול לומר לה\u0004 בכל עת \u0003\"צאי מעשה ידיך במזונותיך\",\u0004 כלומר, קחי לעצמך את שכר מלאכתך ופרנסי את עצמך משלך, והרשות בידו לעשות כן,"],["\u0003נעשה כ\u0004אילו היה \u0003אומר לה \"צאי מעשה ידיך במזונותיך\".\u0004 ומקשים: \u0003ואם איתא להא\u0004 \u0005[יש ל\u0006קבל הלכה \u0005זו]\u0006 של \u0003רב הונא אמר רב,\u0004 ש\u0003אמר רב הונא אמר רב: יכולה אשה שתאמר לבעלה \"איני ניזונת ואיני עושה\",\u0004 אלא אני אעבוד ואפרנס את עצמי, אם כן, כאשר אמרה \u0003\"קונם\u0004 (אסור כקרבן) יהיה מה \u0003שאני עושה לפיך\", אמאי\u0004 \u0005[מדוע]\u0006 \u0003אינו צריך להפר? לימא\u0004 \u0005[נאמר]\u0006 גם כאן: \u0003מתוך שיכולה לומר \"איני ניזונת ואיני עושה\" — נעשה כמי שאומרת לו\u0004 בזמן שנדרה: \u0003\"איני ניזונת ואיני עושה\"\u0004 ואין סיבה שלא יחול נדרה ויצטרך איפוא להפר לה.","\u0003אלא\u0004 יש לחזור ממה שאמרנו, ו\u0003לא תימא\u0004 \u0005[אל תאמר]\u0006 \u0003\"נעשה\u0004 כאומר לה כן \u0003\"\u0004, \u0003אלא\u0004 משנתנו \u0003באומר לה\u0004 במפורש: \u0003\"צאי מעשה ידיך במזונותיך\".\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003פרנס למה לה?\u0004 שאם היא עובדת ומפרנסת את עצמה — לשם מה יעמיד לה פרנס? ומשיבים: \u0003בדלא ספקה\u0004 \u0005[ב\u0006זמן \u0005שאין מספיק לה]\u0006 מה שהיא עובדת כדי לפרנסה. ושואלים: \u0003אי בדלא ספקה\u0004 \u0005[אם בשאין מספיק לה] —\u0006 \u0003הדר קושיין לדוכתיה\u0004 \u0005[חוזרת קושייתנו למקומה]:\u0006 כיצד יכול הוא לבטל את שעבודו מלפרנסה? \u0003אמר רב אשי:\u0004 מדובר כאן \u0003במספקת\u0004 בשכר עבודתה \u0003לדברים גדולים,\u0004 לעיקר מזונותיה, \u0003ואינה מספקת לדברים קטנים.\u0004","ועדיין מקשים: \u0003הני\u0004 \u0005[אותם]\u0006 \u0003דברים קטנים\u0004 שאמרת, \u0003היכי דמי\u0004 \u0005[איך הם בדיוק]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 מדובר באופן ש\u0003רגילה בהו\u0004 \u0005[בהם] —\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 היא \u0003רגילה בהו\u0004 \u0005[בהם],\u0006 והרי הם כשאר צרכיה ההכרחיים שהוא משועבד לתת לה, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא רגילה בהו\u0004 \u0005[בהם] —\u0006 \u0003פרנס\u0004 אם כן \u0003למה לה?\u0004 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לאופן שהיתה \u0003רגילה\u0004 בדברים קטנים אלה \u0003בבית נשא\u0004 \u0005[אביה],\u0006 \u0003וקא מגלגלא בהדיה\u0004 \u0005[והיתה מגלגלת\u0006 וסובלת \u0005עמו]\u0006 בתנאי החיים שלו, \u0003דאמרה ליה\u0004 \u0005[שאומרת לו]:\u0006 \u0003עד האידנא\u0004 \u0005[עכשיו]\u0006 ש\u0003לא אדרתן\u0004 \u0005[הדרת אותי\u0006 ממך\u0005] —\u0006 \u0003גלגילנא בהדך\u0004 \u0005[גלגלתי,\u0006 סבלתי, \u0005איתך]\u0006 לפי התנאים שלך, \u0003השתא דאדרתן\u0004 \u0005[עכשיו שהדרת אותי\u0006 ממך\u0005] —\u0006 \u0003לא מצינא דאיגלגל בהדך\u0004 \u0005[אינני יכולה\u0006 עוד \u0005להתגלגל איתך]\u0006 בתנאים שלך, ואני רוצה לחזור למצב שבו הייתי בבית אבי.","ושואלים: \u0003ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה]\u0006 ש\u0003עד שלשים יום\u0004 יכול להעמיד לה פרנס? ומשיבים: \u0003עד שלשים יום לא שמעי בה אינשי ולא זילא בה מילתא\u0004 \u0005[אין אנשים שומעים עליה ואין מגנה אותה הדבר],\u0006 שניזונת על ידי פרנס, ואולם \u0003טפי\u0004 \u0005[יותר\u0006 מזה\u0005] —\u0006 \u0003שמעי בה אינשי וזילא בה מילתא\u0004 \u0005[שומעים עליה אנשים ומגנה אותה הדבר],\u0006 ולכן צריך להחליט אם רוצה לגרשה או לקיימה.","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 כתשובה לשאלה איך הוא יכול להדירה והלא הוא משועבד לה, שמדובר כאן \u0003שהדירה כשהיא ארוסה,\u0004 שעדיין אינו משועבד לה לפרנסה. ותוהים: \u0003ארוסה מי אית\u0004 \u0005[האם\u0006 בכלל \u0005יש]\u0006 \u0003לה מזוני\u0004 \u0005[מזונות]\u0006 משל בעלה, וממה הוא מדיר אותה? ומשיבים: \u0003שהגיע זמן\u0004 שנקבע לנישואין \u0003ולא נשאו. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הגיע זמן ולא נשאו — אוכלות משלו\u0004 משל הבעל \u0003ואוכלות בתרומה\u0004 אם הוא כהן.","ושואלים אם כן: \u0003ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה]\u0006 שיכול להעמיד לה פרנס \u0003עד שלשים יום?\u0004 ומשיבים: \u0003עד שלשים יום — עביד\u0004 \u0005[עושה]\u0006 ה\u0003שליח\u0004 את \u0003שליחותיה\u0004 \u0005[שליחותו]\u0006 והוא דואג לצרכיה כראוי, \u0003טפי\u0004 \u0005[יותר\u0006 מזה\u0005] —\u0006 \u0003לא עביד\u0004 \u0005[עושה]\u0006 ה\u0003שליח\u0004 את \u0003שליחותיה\u0004 \u0005[שליחותו]\u0006 ומתחיל לזלזל בה, ואינה יכולה לסבול עוד.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שמדובר באופן \u0003שהדירה כשהיא ארוסה ונישאת,\u0004 ולכן חייב במזונותיה. ותוהים: אם \u0003נישאת\u0004 לו אחר שהדירה — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003סברה,\u0004 חשבה, \u0003וקבלה\u0004 על עצמה את הדבר, ומדוע כופים אותו לגרשה! ומשיבים: \u0003דאמרה\u0004 \u0005[ש\u0006היא \u0005אומרת]:\u0006 \u0003כסבורה אני שאני יכולה לקבל\u0004 על עצמי לחיות באופן זה, ואולם \u0003עכשיו\u0004 אני רואה ש\u0003אין אני יכולה לקבל.\u0004","ומקשים: \u0003אימר דאמרינן הכי\u0004 \u0005[אמור שאנו אומרים כך]\u0006 ל\u0003גבי מומין\u0004 שהאשה או האיש יכולים לטעון סבור הייתי שאני יכול לסבול זאת, אבל \u0003לענין מזוני\u0004 \u0005[מזונות]\u0006 \u0003מי אמרינן הכי\u0004 \u0005[האם אנו אומרים כך]?\u0006 אלא, אם קיבלה — קיבלה, ואינה יכולה לחזור בה! \u0003אלא מחוורתא כדשנינן מעיקרא\u0004 \u0005[מחוור,\u0006 ברור, \u0005כפי שתירצנו מתחילה]\u0006 שמדובר פה כשמתגלגלת איתו בדוחק, או כשהגיע הזמן ולא נישאה.","שנינו במשנה שהמדיר את אשתו בהנאה ממנו — \u0003עד שלשים יום יעמיד פרנס.\u0004 על עצם הענין תוהים: \u0003ו\u0004כי ה\u0003פרנס לאו שליחותיה קא עביד\u0004 \u0005[לא\u0006 את \u0005שליחותו\u0006 של הבעל הוא \u0005עושה]?\u0006 ואם הדיר אותה הנאה ממנו, איך יכול הוא להנותה על ידי שליח? והרי שלוחו כמותו! \u0003אמר רב הונא:\u0004 כאן מדובר לא כשהוא ממנה ממש שליח, אלא \u0003באומר\u0004 באופן כללי: \u0003\"כל הזן\u0004 את אשתי \u0003אינו מפסיד\",\u0004 ונמצא שהעושה זאת — מדעת עצמו הוא עושה, אף על פי שאחר כך יפרע לו הבעל.","ושואלים: \u0003וכי אמר הכי לאו שליחותיה קעביד\u0004 \u0005[וכאשר\u0006 אדם \u0005אומר כך,\u0006 וכי \u0005אין\u0006 הוא \u0005עושה את שליחותו]\u0006 ואינו נחשב לשליחו? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003מי שהיה מושלך בבור, ואמר: \"כל השומע קולו\u0004 (=קולי) \u0003יכתוב גט לאשתו\u0004 (=לאשתי) \u0003\"\u0004— \u0003הרי אלו,\u0004 השומעים, \u0003יכתבו\u0004 גט \u0003ויתנו\u0004 לאשתו. משמע שהם נחשבים כשליחים, שאם לא כן אינם יכולים לכתוב גט עבורו. ואף בפרנס תהיה אם כן לשון זו נחשבת לשליחות!","ודוחים: \u0003הכי השתא\u0004 \u0005[איך אתה משווה]?!\u0006 \u0003התם קאמר\u0004 \u0005[שם\u0006 בגט הוא \u0005אומר]\u0006 \u0003\"יכתוב\",\u0004 כלומר, שהורה וציווה לעשות כן, \u0003הכא מי קאמר\u0004 \u0005[כאן האם\u0006 הוא \u0005אומר]\u0006 \u0003\"יזון\"? \"כל הזן\" קאמר\u0004 \u0005[הוא אומר]!\u0006 ואין זו שליחות, אלא אמירה כוללת.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' אמי: בדליקה\u0004 שנפלה בשבת \u0003התירו לומר\u0004 בפני הגוים: \u0003\"כל המכבה אינו מפסיד\".\u0004 ונדייק: \u0003בדליקה למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]?\u0006 \u0003לאו למעוטי כי האי גוונא\u0004 \u0005[\u0006האם \u0005לא למעט כגון זה]?\u0006 שרק בדליקה שיש בה חששות מכמה צדדים — התירו לומר לשון זו שיש בה צד שליחות, אבל במקרה אחר — לא התירו, משום שהעושה על פי ציווי כזה הרי הוא כשליח! ודוחים: \u0003לא,\u0004 הכוונה היא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003שאר איסורים\u0004 של \u0003שבת,\u0004 שרק בדליקה התירו לומר בפני גוים \"כל המכבה לא יפסיד\" אבל לא התירו לומר כן באיסורי שבת אחרים.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבה\u0004 ממקום אחר, ששנינו: \u0003המודר הנאה מחבירו,\u0004 מי שהדירו חבירו מלהנות מנכסיו \u0003ואין לו מה יאכל,\u0004 וחבירו רוצה לפרנסו ואינו יכול מפני הנדר — \u0003ילך\u0004 חבירו \u0003אצל חנוני\u0004 שהוא \u0003רגיל אצלו, ויאמר לו: \"איש פלוני מודר הנאה ממני, ואיני יודע מה אעשה לו\".\u0004 ואז \u0003הוא,\u0004 החנווני, \u0003נותן לו\u0004 לאיש שאין לו מה לאכול, \u0003ובא\u0004 החנווני אחר כך \u0003ונוטל מזה\u0004 שאמר לו. ומכאן נלמד: \u0003הכי\u0004 \u0005[כך]\u0006 \u0003הוא דשרי\u0004 \u0005[שמותר]\u0006 לעשות, שלא אמר לחנווני אלא ברמז, \u0003אבל\u0004 לומר בלשון \u0003\"כל הזן אינו מפסיד\" — לא,\u0004 אסור לומר, שהרי הוא כשלוחו!","ודוחים: בלשון \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 \u0003קאמר\u0004 \u0005[אמר],\u0006 והכוונה היא כך: \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר שמותר לומר בלשון כללית \u0003\"כל הזן\u0004 את פלוני \u0003אינו מפסיד\" — משום דלעלמא קאמר\u0004 \u0005[ש\u0006הרי \u0005לעולם,\u0006 לכל, הוא \u0005אומר]\u0006 ואין כאן שליחות כלל, \u0003אבל האי\u0004 \u0005[זה],\u0006 החנווני, \u0003כיון\u0004 שהוא \u0003רגיל אצלו וקאזיל קאמר ליה\u0004 \u0005[והולך ואומר לו],\u0006 הייתי אומר שהרי זה \u0003כמאן דאמר ליה\u0004 \u0005[כמי שאומר לו]\u0006 במפורש \u0003\"זיל, הב ליה את\u0004 \u0005[לך, תן לו אתה]\u0006 \u0003\" דמי\u0004 \u0005[נחשב],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין זה נחשב כאילו אמר לו במפורש \"לך, תן לו\", ואינו נחשב כשליח.","כיון שהוזכרה הלכה זו, דנים בה \u0003גופא\u0004 \u0005[לגופה]:\u0006 \u0003המודר הנאה מחבירו ואין לו מה יאכל, הולך אצל חנוני הרגיל אצלו, ואומר לו: \"איש פלוני מודר הנאה ממני, ואיני יודע מה אעשה לו\". הוא\u0004 החנווני \u0003נותן לו\u0004 לאיש מזונותיו, \u0003ובא\u0004 החנווני לאחר מכן \u0003ונוטל מזה\u0004 שהדירו. וכן אם היה \u0003ביתו\u0004 של אותו אדם צריך \u0003לבנות,\u0004 או צריך \u0003גדירו לגדור,\u0004 או \u0003שדהו לקצור\u0004 ואין לו מי שיעשה זאת, והאיש שהדירו הנאה רוצה לסייע לו — \u0003הולך\u0004 המדיר \u0003אצל פועלין הרגילין אצלו, ואומר להן: \"איש פלוני מודר הנאה ממני ואיני יודע מה אעשה לו\". הן עושין עמו\u0004 עם אותו אדם, \u0003ובאין ונוטלים שכרן מזה\u0004 שאמר להם.","\u0003היו מהלכין\u0004 שניהם \u0003בדרך, ואין עמו\u0004 לזה שהדירוהו הנאה \u0003מה יאכל — נותן\u0004 המדיר \u0003לאחר לשום\u0004 (לשם) \u0003מתנה, והלה,\u0004 זה שמודר, \u0003נוטל ואוכל, ומותר.\u0004 שהרי לא לו נתן. \u0003ואם אין שם אחר,\u0004 אלא שהיו רק שניהם מהלכים יחד — \u0003מניח\u0004 את האוכל \u0003על גבי הסלע או על גבי הגדר, ואומר: \"הרי הן מופקרין לכל מי שיחפוץ\", והלה,\u0004 המודר, \u0003נוטל ואוכל, ומותר. ור' יוסי אוסר\u0004 בכגון זה. \u0003אמר רבא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יוסי — גזירה\u0004 היא שגזר \u0003משום\u0004"],["\u0003מעשה\u0004 שהיה ב\u0003בית חורון,\u0004 שאחד נדר הנאה מאביו וכדי שיוכל אביו לבוא לשמחה שלו, נתן את כל נכסיו במתנה לאחר. ומאחר ומקבל המתנה חשש שמא יש בכך משום עבירה על הנדר, הלך והקדישם. וכשאמר לו הנותן כי לא נתנם לו כדי שיקדישם, אמר לו המקבל בתשובה, שאם אכן כן שאין בידו הרשות להקדיש את הנכסים שקיבל — אין זו נחשבת כמתנה, ואם כן אף אינו יכול להאכיל בדרך זו את אביו מהסעודה. וכדבריו הורו חכמים להלכה. ואם כן, במקרה שלנו, חכמים אינם חוששים לזה שיש כאן הערמה גלויה ור' יוסי חושש לכך.","שנינו במשנה ש \u0003ר' יהודה אומר\u0004 שהמדיר את אשתו מלהנות ממנו, אם הבעל הוא \u0003ישראל, חדש אחד\u0004 יקיים, ואם הוא כהן יכול לקיים שני חדשים. ותוהים: מה שאמר לגבי ישראל, הלא \u0003היינו\u0004 \u0005[זו]\u0006 עצמה דעתו של \u0003תנא קמא\u0004 \u0005[התנא הראשון]\u0006 שאמר שלושים יום? \u0003אמר אביי:\u0004 באמת לגבי ישראל לא חידש דבר, אלא את הדין לגבי \u0003כהנת\u0004 (אשת כהן) \u0003אתא לאשמועינן\u0004 \u0005[בא להשמיע לנו],\u0006 וזהו החידוש בדבריו. \u0003רבא אמר: חדש מלא וחדש חסר איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005],\u0006 לדעת תנא קמא שלושים יום דווקא, ולדעת ר' יהודה חודש אחד — בין שהוא מלא ובין שהוא חסר.","\u0003אמר רב:\u0004 מה שקבעו זמן למי שהדיר את אשתו מלהנות לו, \u0003לא שנו\u0004 כן \u0003אלא במפרש,\u0004 שקבע זמן מסויים לנדר, \u0003אבל\u0004 אם נדר \u0003בסתם,\u0004 בלא הגדרת זמן \u0003— יוציא לאלתר\u0004 (יגרש מיד) \u0003ויתן כתובה. ושמואל אמר: אפילו\u0004 כשהדירה \u0003בסתם, לא יוציא\u0004 מיד. והטעם לכך — \u0003שמא ימצא פתח לנדרו\u0004 ויתיר את הנדר.","ושואלים: \u0003והא איפלגו ביה חדא זימנא\u0004 \u0005[והרי\u0006 כבר \u0005נחלקו בכך\u0006 תנאים \u0005פעם אחת],\u0006 במקרה דומה, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 (לעיל כתובות סא, ב): \u0003המדיר את אשתו מתשמיש המטה, בית שמאי אומרים:\u0004 אם הדירה עד \u0003שתי שבתות\u0004 (שבועות) — יקיים, ואם לאו — יוציא ויתן כתובה. \u0003ובית הלל אומרים שבת\u0004 (שבוע) \u0003אחת. ואמר רב: מחלוקת\u0004 זו היא דווקא \u0003במפרש\u0004 לכמה זמן הוא מדירה, \u0003אבל\u0004 כאשר מדירה \u0003בסתם,\u0004 בלא הגדרת זמן — \u0003יוציא לאלתר ויתן כתובה. ושמואל אמר: אפילו\u0004 כשהדירה \u0003בסתם נמי\u0004 \u0005[גם כן]\u0006 \u0003לא יוציא, שמא ימצא פתח לנדרו.\u0004 ואם כן מדוע צריכה מחלוקת זו להיאמר פעמיים?","ומשיבים: \u0003צריכא\u0004 \u0005[צריכה]\u0006 המחלוקת הזו להיאמר; \u0003דאי איתמר\u0004 \u0005[שאילו היה נאמר]\u0006 רק \u0003בההיא,\u0004 בענין תשמיש, היינו אומרים: \u0003בההיא קאמר\u0004 \u0005[אומר]\u0006 \u0003רב\u0004 שיוציא לאלתר — \u0003משום\u0004 ש\u0003לא אפשר\u0004 שיקיים הבעל את חובתו כלפיה \u0003ב\u0004אמצעות \u0003פרנס,\u0004 שהרי אי אפשר לעשות את התשמיש על ידי אחר, \u0003אבל בהא\u0004 \u0005[בזו],\u0006 בענין מזונותיה, ש\u0003אפשר\u0004 לבעל לקיים את נדרו \u0003ב\u0004אמצעות \u0003פרנס — אימא\u0004 \u0005[אמור]\u0006 ש\u0003מודה ליה\u0004 \u0005[לו]\u0006 \u0003לשמואל\u0004 שלא יוציא מיד. ולהיפך: \u0003ואי אתמר בהא\u0004 \u0005[ואילו היה נאמר\u0006 רק \u0005בזו]\u0006 בענין מזונות, היינו אומרים: \u0003בהא קאמר\u0004 \u0005[בזו אומר]\u0006 \u0003שמואל\u0004 שלא יוציא — \u0003משום\u0004 ש\u0003אפשר בפרנס, אבל ב\u0004הלכה \u0003ההיא\u0004 של מדיר אשתו מתשמיש \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003מודה ליה\u0004 \u0005[לו]\u0006 \u0003לרב\u0004 שכיון שאי אפשר שיקיים הבעל את חובתו באמצעות שליח — יגרש מיד, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שתיאמר המחלוקת בשני המקרים.","\u0003תנן\u0004 \u0005[שנינו\u0006 בהמשך משנתנו\u0005]:\u0006 \u0003המדיר את אשתו שלא תטעום אחד מכל הפירות — יוציא\u0004 מיד \u0003ויתן כתובה.\u0004 ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003לרב,\u0004 אין סתירה מהרישא לסיפא, כי \u0003כאן\u0004 בסיפא מדובר \u0003בסתם,\u0004 ואז יגרש מיד, ואילו \u0003כאן\u0004 ברישא במדירה הנאה ממנו מדובר \u0003במפרש\u0004 זמן מסויים, \u0003אלא לשמואל\u0004 שאינו מחלק בין המפרש לסתם, \u0003קשיא\u0004 \u0005[קשה]!\u0006","ומתרצים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן,\u0006 בסיפא, \u0005במה אנו עוסקים]\u0006 — \u0003כגון שנדרה היא\u0004 הנאה מהפירות, \u0003וקיים לה איהו\u0004 \u0005[הוא]\u0006 את הנדר הזה ולא הפירו, וכיון שהיא נדרה וודאי לא תבקש פתח להתירו, לכן יוציא אותה מיד. \u0003וקסבר\u0004 \u0005[וסבור]\u0006 \u0003ר' מאיר,\u0004 שסתם משנה היא כשיטתו, שכאשר הוא מקיים את נדרה הרי זה כאילו \u0003הוא נותן אצבע בין שיניה,\u0004 שדרך הטבע שתנשוך אותה, ואם כן האשמה תלויה בו, ולכן צריך גם לתת לה כתובה כשמוציאה.","ושואלים: \u0003ו\u0004האם \u0003סבר ר' מאיר\u0004 שבמקרה כזה \u0003הוא נותן אצבע בין שיניה? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003האשה שנדרה\u0004 הנאה \u0003ב\u0004דברים שה\u0003נזיר\u0004 אסור בהם, \u0003ושמע בעלה ולא הפר לה, ר' מאיר ור' יהודה אומרים: היא\u0004 עצמה \u0003נתנה אצבע בין שיניה\u0004 ונשכה אותה, כלומר, היא גרמה לעצמה, \u0003לפיכך אם רצה הבעל להפר\u0004 נדר זה — \u0003יפר. ואם אמר אי אפשי\u0004 (אין רצוני) \u0003באשה נדרנית — תצא\u0004 האשה \u0003שלא בכתובה.\u0004","\u0003ר' יוסי ור' אלעזר אומרים:\u0004 כיון שלא הפר לה — הרי זה כאילו \u0003הוא נותן אצבע בין שיניה, לפיכך, אם רצה הבעל להפר — יפר. ואם אמר: אי אפשי באשה נדרנית — יוציא ויתן כתובה!\u0004 ומתרצים: \u0003איפוך\u0004 \u0005[הפוך]\u0006 את השיטות, ואמור כך: \u0003ר' מאיר ור' יהודה אומרים: הוא נותן\u0004 אצבע בין שיניה, ו\u0003ר' יוסי ור' אלעזר אומרים: היא נתנה\u0004 אצבע בין שיניה.","ומקשים: \u0003ו\u0004האם \u0003סבר ר' יוסי היא נתנה? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 המדיר את אשתו שלא תתקשט באחד מכל המינים, \u0003ר' יוסי אומר: בעניות\u0004 כ\u0003שלא נתן קצבה\u0004 לזמן בו היא אסורה — יוציא ויתן כתובה. ולפי ההסבר האחרון שהסברנו המשנה מדברת באופן שהאשה נדרה והבעל קיים, משמע שאף הוא מודה שהאחריות מוטלת עליו והרי זה כאילו הוא נתן אצבע בין שיניה, ולכן צריך לתת לה כתובה!","ומתרצים: \u0003אימא\u0004 \u0005[אמור]\u0006 ושנה את הגירסה בברייתא כך: \u0003ר' מאיר ור' יוסי אומרים: הוא נותן,\u0004 ו\u0003ר' יהודה ור' אלעזר אומרים: היא נתנה,\u0004 ואז לא תהיה סתירה גם לשיטת ר' יוסי במשנתנו. ומקשים עוד: \u0003ו\u0004האם \u0003סבר ר' יהודה היא נתנה? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו\u0005]\u0006 בענין המדיר את אשתו שלא תטעום אחד מכל הפירות, ש\u0003ר' יהודה אומר: בישראל\u0004 אם הדירה ל\u0003יום אחד\u0004 — \u0003יקיים,\u0004 שנים — יוציא ויתן כתובה, ולפי הפירוש שפירשנו מדובר שנדרה היא וקיים הוא, משמע שסובר שהוא נתן אצבע בין שיניה!","ומתרצים: \u0003אימא\u0004 \u0005[אמור]\u0006 תקן את הנוסח באותה מחלוקת כך: \u0003ר' מאיר ור' יהודה ור' יוסי אומרים: הוא נותן\u0004 אצבע בין שיניה, \u0003ור' אלעזר אומר: היא נתנה. ואם תמצא\u0004 (תרצה) \u0003לומר\u0004 כי \u0003זוגי זוגי קתני\u0004 \u0005[זוגות זוגות שנה]\u0006 התנא, \u0003אימא\u0004 \u0005[אמור]\u0006 כך: \u0003ר' מאיר ור' אלעזר אומרים: היא נתנה\u0004 אצבע בין שיניה, \u0003ר' יהודה ור' יוסי אומרים: הוא נותן\u0004 בין שיניה. \u0003והא סתמא דלא\u0004 \u0005[וסתם\u0006 משנה \u0005זו\u0006 שלנו \u0005אינה]\u0006 \u0003כ\u0004שיטת \u0003ר' מאיר,\u0004 אלא כשיטת חכמים אחרים.","מאחר והסברנו את המשנה בנדרה היא וקיים הוא, שואלים מצד אחר: \u0003וסבר ר' יוסי\u0004 כי \u0003בעניות\u0004 כ\u0003שלא נתן קצבה\u0004 צריך לגרש, מכיון שלא הפר לה, \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003בעל מצי מיפר\u0004 \u0005[יכול להפר]\u0006 כשהאשה נודרת שלא תתקשט. \u0003ורמינהו\u0004 \u0005[ומטילים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו במשנה אחרת: \u0003אלו דברים שהבעל מיפר — דברים שיש בהן עינוי נפש,\u0004 כגון שהאשה אומרת \u0003\"\u0004תיאסר עלי הנאת רחיצה \u0003אם ארחץ\",\u0004 או שנשבעה \u0003\"אם לא ארחץ\",\u0004 כלומר שלא תרחץ כלל. או שנדרה \u0003\"אם אתקשט\",\u0004 או שנשבעה \u0003\"אם לא אתקשט\",\u0004 שיש בהם צער לאשה. \u0003אמר ר' יוסי: אין אלו נדרי עינוי נפש\u0004 והבעל אינו יכול להפר נדרים כאלה, \u0003ואלו הן נדרי עינוי נפש:\u0004 כגון שנדרה \u0003\"שלא אוכל בשר\", ו\"שלא אשתה יין\", ו\"שלא אתקשט\u0004"],["\u0003בבגדי צבעונין\",\u0004 משום שיש לה בכך גנאי וגם בזיון לאחרים ולבעלה. אבל דברים אחרים שעושה לעצמה, אינם בכלל נדרי עינוי נפש! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן\u0006 במשנתנו \u0005במה אנו עוסקים] —\u0006 שנדרה שלא תתקשט \u0003בדברים שבינו לבינה,\u0004 כלומר, שלא תשתמש באמצעים להסיר את שער הערווה.","ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 שאם נדרה ב\u0003דברים שבינו לבינה\u0004 (המפריעים ליחסים שביניהם) \u0003הבעל מיפר, אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי אף באופן כזה \u0003אין הבעל מיפר, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 \u0003דאתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו אמוראים בשאלה זו: אשה שנדרה שלא תתקשט ב\u0003דברים שבינו לבינה,\u0004 כגון זה, \u0003רב הונא אמר: הבעל מיפר, רב אדא בר אהבה אמר: אין הבעל מיפר,\u0004 שאין הדבר מפריע לקיום יחסי אישות ביניהם, ובלשון משל אמר \u0003שלא מצינו שועל שמת בעפר פיר\u0004 (החור שהוא חי בו) ואף כאן אף שמגדלת שיער, כיון שהוא מכיר אותה היטב לא יינזק על ידי כך.","\u0003אלא הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון דתלינהו\u0004 \u0005[שתלתה]\u0006 \u0003לקישוטיה בתשמיש המטה,\u0004 שנדרה באופן כזה שענין קישוטיה תלוי בנדר אחר לגבי תשמיש המיטה. וכגון ש\u0003אמרה\u0004 בלשון: \u0003\"יאסר הנאת תשמישך עלי אם אתקשט\", כדאמר\u0004 \u0005[כמו שאמר]\u0006 \u0003רב כהנא,\u0004 שנדר בסגנון זה אוסר את התשמיש, ודבר זה הוא ודאי ענין שבינו לבינה שרשאי הבעל להפר.","ש\u0003אמר רב כהנא:\u0004 אם האשה אומרת \u0003\"\u0004תיאסר \u0003הנאת תשמישי עליך\"\u0004 שיהא הוא אסור ליהנות מן התשמיש עימה — הרי הוא \u0003כופה ומשמשתו,\u0004 שאין היא יכולה לאסור עצמה עליו מפני שמשועבדת לו לענין תשמיש. אבל אם אמרה \u0003\"\u0004תיאסר \u0003הנאת תשמישך עלי\" — יפר,\u0004 שאף על פי שהיא משועבדת לו לביאה, כיון שאסרה עליה הנאת תשמיש, אסור לו להכריח אותה ליהנות מכך, \u0003לפי שאין מאכילין לאדם דבר האסור לו. ו\u0004מקשים: גם אם נדרה שאם תתקשט תיאסר בהנאת תשמיש —","\u0003לא תתקשט ולא תאסר!\u0004 וכיון שיכולה שלא לבא לידי איסור תשמיש, שוב אינו יכול להפר לה נדר זה, שהרי הנדר על הקישוט כשלעצמו אינו סוג נדר שרשאי הבעל להפר! ומשיבים: \u0003אם כן קרו\u0004 \u0005[קוראים]\u0006 \u0003לה \"מנוולת\"\u0004 כשאינה מתקשטת ואינה יכולה לעמוד בבזיון זה.","ומקשים מצד אחר: \u0003ותתקשט ותאסר\u0004 בתשמיש ועדיין הוא מקיים אותה, כפי שאמרו לגבי המדיר אשתו מתשמיש, \u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004דעת \u0003בית שמאי — שתי שבתות, אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004דעת \u0003בית הלל שבת אחת,\u0004 ומדוע אמרו שיגרשנה מיד? ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שנותנים זמן לבעל כדי שימצא פתח לנדרו הרי זה דווקא \u0003היכא דאדרה איהו\u0004 \u0005[במקום שהוא הדיר אותה]\u0006 \u0003דסברה\u0004 \u0005[ש\u0006היא \u0005חושבת]:\u0006 \u0003מירתח רתח עילואי והשתא מותיב דעתיה\u0004 \u0005[\u0006הוא \u0005כועס עלי, ועכשיו תתיישב דעתו]\u0006 וימצא דרך להתיר את הנדר. \u0003אבל הכא\u0004 \u0005[כאן],\u0006 כפי שהסברנו את המשנה, ש\u0003נדרה איהי\u0004 \u0005[היא]\u0006 \u0003ושתיק\u0004 \u0005[ו\u0006הוא \u0005שתק]\u0006 ולא הפר \u0003לה, סברה\u0004 \u0005[\u0006היא \u0005חושבת]\u0006 \u0003מדאישתק\u0004 \u0005[מ\u0006כיון \u0005ש\u0006הוא \u0005שותק]\u0006 — משמע כי \u0003מיסנא הוא דסני לי\u0004 \u0005[שהוא שונא אותי]\u0006 ולכן היא רוצה להתגרש.","שנינו במשנה בענין המדיר את אשתו שלא תתקשט, ש\u0003ר' יוסי אומר: בעניות\u0004 כ\u0003שלא נתן קצבה\u0004 לזמן בו תהא אסורה — יוציא ויתן כתובה. ושואלים: \u0003וכמה קצבה\u0004 זו? אם נותן קיצבה בודאי יש לדבר שיעור, וזמן ארוך מאוד אינו בכלל זה, ומהו השיעור? \u0003אמר רב יהודה אמר שמואל:\u0004 קצבה זו היא \u0003שנים עשר חדש,\u0004 ויותר מכך הרי זה כלא נתן קצבה ומוציאה ונותן כתובתה. \u0003רבה בר בר חנה אמר ר' יוחנן: עשר שנים. רב חסדא אמר\u0004 בשם \u0003אבימי: רגל\u0004 (אחד משלושה רגלים), \u0003שכן בנות ישראל מתקשטות ברגל,\u0004 ואם נדר ליותר מרגל נחשב כלא נתן קצבה, וחייב לגרשה.","\u0003ובעשירות\u0004 יכול להדירן מלהתקשט \u0003שלשים יום.\u0004 ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה,\u0006 מדוע\u0005]\u0006 \u0003שלשים יום\u0004 דווקא? \u0003אמר אביי: שכן אשה חשובה\u0004 ועשירה \u0003נהנית מריח קשוטיה\u0004 שהתקשטה עוד קודם, עד \u0003שלשים יום,\u0004 ולאחר מכן היא מרגישה שהיא מתנוולת.","\u0003המדיר את אשתו,\u0004 שאוסר עליה בנדר \u0003שלא תלך לבית אביה\u0004 — \u0003בזמן שהוא\u0004 (האב) \u0003עמה בעיר,\u0004 אם היה הנדר עד \u0003חודש אחד — יקיים,\u0004 ואם היה הנדר \u0003שנים — יוציא ויתן כתובה. ובזמן שהוא\u0004 (האב) \u0003בעיר אחרת,\u0004 אם הדירה בעלה עד \u0003רגל אחד — יקיים,\u0004 שאף על פי שדרך האשה ללכת ברגל לבקר את הוריה, יכולה היא להימנע פעם אחת. ואם הדירה מללכת לבית אביה \u0003שלשה\u0004 רגלים — \u0003יוציא ויתן כתובה.\u0004","ועוד, \u0003המדיר את אשתו שלא תלך לבית האבל\u0004 לנחם, \u0003או לבית המשתה\u0004 (החתונה) — \u0003יוציא ויתן כתובה.\u0004 ומדוע? — \u0003מפני שנועל בפניה. ואם היה טוען\u0004 שאינו רוצה שתלך לשם \u0003משום דבר אחר\u0004 (שחושש משום פריצות שיש שם) — \u0003רשאי.\u0004","\u0003אמר לה\u0004 לאשתו: \u0003\"על מנת שתאמרי לפלוני מה שאמרת לי\", או\u0004 שאמר לה: \u0003\"\u0004על מנת שתאמרי לו \u0003מה שאמרתי לך\", או\u0004 שאמר לה \u0003שתהא ממלאה ומערה\u0004 (שופכת) \u0003לאשפה — יוציא ויתן כתובה.\u0004 ובגמרא יבוארו הדברים האלה לפרטיהם.","על הפיסקה הראשונה במשנה שואלים: \u0003הא גופא קשיא\u0004 \u0005[זו,\u0006 המשנה \u0005עצמה\u0006 \u0005קשה]:\u0006 \u0003אמרת\u0004 מצד אחד שאם הדירה מללכת לבית אביה \u0003רגל אחד — יקיים,\u0004 ומכאן נדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם אסר עליה שלא תלך \u0003שנים — יוציא ויתן כתובה, אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של הלכה זו\u0005]:\u0006 \u0003שלשה — יוציא ויתן כתובה,\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003שנים — יקיים.\u0004 הרי שהדיוקים של הרישא והסיפא סותרים זה את זה!","\u0003אמר אביי: סיפא אתאן\u0004 \u0005[בסוף הגענו]\u0006 \u0003ל\u0004מקרה של \u0003כהנת\u0004 (אשת כהן), שבה נתנו יותר זמן עד שיהיה חייב לגרשה, שהרי לאחר הגירושין אינו יכול להחזירה. \u0003ו\u0004שיטת \u0003ר' יהודה היא\u0004 שמחלק גם במשנה הקודמת בין אשת ישראל לאשת כהן. \u0003רבה בר עולא אמר: לא קשיא\u0004 \u0005[אינו קשה],\u0006 ויש להסביר באופן אחר: \u0003כאן,\u0004 מה שמובן בתחילת ההלכה במשנה כי כשהדירה מללכת לבית אביה שני רגלים יוציא ויתן כתובה, הרי זה \u0003ברדופה\u0004 שהיתה רגילה ולהוטה תמיד ללכת לבית אביה, ואם מדיר אותה יותר מרגל אחד — הריהו בשבילה צער גדול, וצריך לגרש, ואילו \u0003כאן,\u0004 מה שמשמע מהמשך ההלכה כי בשהדירה שני רגלים לא יוציא — הרי זה \u0003בשאינה רדופה\u0004 ללכת לבית אביה. כיון שהזכרנו ענין זה של אשה רדופה ללכת לבית אביה מביאים ענין אחר שהוזכר בו ביטוי זה.","על הכתוב \u0003\"אז הייתי בעיניו כמוצאת שלום\"\u0004 (שיר השירים ח, י), \u0003אמר ר' יוחנן:\u0004 כוונתו \u0003ככלה שנמצאת שלמה\u0004 (מושלמת) \u0003בבית חמיה, ורדופה\u0004 (להוטה) \u0003לילך ולהגיד שבחה בבית אביה,\u0004 כמה דברים טובים אומרים עליה בבית בעלה.","וכדומה בזה על הכתוב \u0003\"והיה ביום ההוא נאם ה' תקראי אישי ולא תקראי לי עוד בעלי\"\u0004 (הושע ב, יח), \u0003אמר ר' יוחנן: ככלה בבית חמיה\u0004 לאחר שכבר נישאה וחיה עם בעלה וקוראת לו בלשון אישות (שיש בה גם משמעות של ביאה) ואינה מתביישת, \u0003ולא ככלה\u0004 שהיא עדיין מאורסת וגרה \u0003בבית אביה,\u0004 שקוראת לו רק \"בעלי\".","שנינו במשנה ש \u0003המדיר את אשתו\u0004 מללכת לבית המשתה ולבית האבל יוציא, מפני שנועל בפניה. ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 במקרה שאוסרה שלא תלך \u0003לבית המשתה\u0004"],["\u0003איכא\u0004 \u0005[יש]\u0006 \u0003נועל בפניה\u0004 שמונע ממנה אפשרות של שמחה, \u0003אלא לבית האבל — מאי\u0004 \u0005[מה]\u0006 \u0003נועל בפניה איכא\u0004 \u0005[יש]\u0006 בכך? \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003למחר\u0004 (בעתיד) \u0003היא מתה ואין כל בריה סופדה,\u0004 שלא ידאג לה אדם, כשם שהיא לא דאגה לאחרים. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 בסגנון אחר: \u0003אין כל בריה סופנה\u0004 (קוברה), שאדם שאינו עוסק בכבוד אחרים, בין החיים ובין המתים, הריהו גורם בכך שהבריות אינן מכבדות אותו.","וכן \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003היה ר' מאיר אומר: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"טוב ללכת אל בית\u0004 ־ \u0003אבל מלכת אל בית משתה באשר הוא סוף כל האדם והחי יתן אל לבו\"\u0004 (קהלת ז, ב), \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"והחי יתן אל לבו\" —\u0004 שיתן אל לבו \u0003דברים של מיתה,\u0004 שאף הוא סופו למות, \u0003דספד\u0004 \u0005[\u0006זה \u0005שסופד\u0006 לאחרים\u0005] —\u0006 \u0003יספדוניה\u0004 \u0005[יספידו אותו],\u0006 \u0003דקבר\u0004 \u0005[\u0006זה \u0005שקובר\u0006 אחרים\u0005]\u0006 — \u0003יקברוניה\u0004 \u0005[יקברו אותו],\u0006 \u0003דידל\u0004 \u0005[\u0006זה \u0005שנושא\u0006 את המת\u0005] —\u0006 \u0003ידלוניה\u0004 \u0005[ישאו אותו],\u0006 \u0003דלואי\u0004 \u0005[\u0006זה \u0005שמלווה\u0006 את המת\u0005] —\u0006 \u0003ילווניה\u0004 \u0005[ילוו אותו],\u0006 \u0003דטען\u0004 \u0005[\u0006זה \u0005שטוען\u0006 אחרים\u0005] —\u0006 \u0003יטענוניה\u0004 \u0005[יטענו אותו],\u0006 הרי שמי שאינו בא לבית האבל ומשתתף באבלו — אף בו אין נוהגים כבוד.","שנינו במשנה: \u0003ואם היה\u0004 הבעל \u0003טוען\u0004 שאינו רוצה שתלך אשתו לבית האבל או לבית המשתה \u0003משום דבר אחר — רשאי.\u0004 ושואלים: \u0003מאי\u0004 מה פירוש \u0003\"דבר אחר\"? אמר רב יהודה אמר שמואל:\u0004 שטוען \u0003משום בני אדם פרוצין שמצויין שם,\u0004 שאינו רוצה שתהא אשתו ביניהם. \u0003אמר רב אשי: לא אמרן\u0004 \u0005[אמרנו]\u0006 שיכול לומר כן \u0003אלא דאיתחזק\u0004 \u0005[שהוחזק\u0006 הדבר\u0005]\u0006 שאכן מצויים שם אנשים כאלה, \u0003אבל\u0004 אם \u0003לא איתחזק\u0004 \u0005[הוחזק\u0006 הדבר\u0005]\u0006 — \u0003לא כל כמיניה\u0004 \u0005[אין זה בכוחו]\u0006 לומר שהוא חושש מפני אנשים פרוצים.","שנינו במשנה: \u0003ואם אמר לה על מנת שתאמרי\u0004 מה שאמרת לי או מה שאמרתי לך וכו'. ושואלים: \u0003ותימא\u0004 \u0005[ותאמר]!\u0006 וכי איזו בעיה יכולה להיווצר כתוצאה מדבריה? \u0003אמר רב יהודה אמר שמואל:\u0004 הכוונה היא \u0003דברים של קלון,\u0004 כלומר, דברים שבינו לבינה, שמתביישת לומר אותם בפני אחרים, ובכגון זה אינו יכול לאלץ אותה, ולכן יוציא ויתן כתובה.","שנינו במשנה בין המקרים בהם צריך הבעל להוציא ולתת כתובה: \u0003או\u0004 שאומר לה הבעל \u0003שתהא ממלאה ומערה לאשפה.\u0004 ושואלים: \u0003ותיעביד\u0004 \u0005[ושתעשה]\u0006 כן! \u0003אמר רב יהודה אמר שמואל:\u0004 הכוונה היא \u0003שתמלא ונופצת,\u0004 כלומר, לשון נקיה היא, שהוא רוצה שתנקוט באמצעים כדי שלא תתעבר, ובכגון זה יכולה היא למחות. \u0003במתניתא תנא\u0004 \u0005[בברייתא שנה]:\u0006 \u0003שתמלא עשרה כדי מים ותערה לאשפה,\u0004 שהוא דבר שיש בו טירחה לשווא ונראה כמעשה שטות.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003שמואל\u0004 המסביר שהכוונה שכופה עליה שתימנע מהריון — \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003יוציא ויתן כתובה. אלא למתניתא\u0004 \u0005[ל\u0006פי שיטת \u0005הברייתא]\u0006 \u0003מאי נפקא\u0004 \u0005[מה יוצא]\u0006 \u0003לה מינה\u0004 \u0005[מזה]?\u0006 \u0003תיעביד\u0004 \u0005[תעשה\u0006 כן\u0005]!\u0006 \u0003אמר רבה בר בר חנה אמר ר' יוחנן: מפני שנראית כשוטה\u0004 אם היא עושה מעשה שאין לו טעם, ומשום כך היא יכולה לתבוע להתגרש.","\u0003אמר רב כהנא: המדיר את אשתו שלא תשאל ושלא תשאיל\u0004 כלים שנוהגים להשאילם, כגון \u0003נפה וכברה וריחים ותנור — יוציא ויתן כתובה.\u0004 ומדוע? מפני \u0003שמשיאה,\u0004 שגורם לה בכך, \u0003שם רע בשכינותיה.\u0004 ששכנותיה תחשובנה עליה רעות ויחשדוה בקמצנות או ביהירות.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה גם כן\u0006 בברייתא \u0005כך]:\u0006 \u0003המדיר את אשתו שלא תשאל ושלא תשאיל נפה וכברה ריחים ותנור — יוציא ויתן כתובה, מפני שמשיאה שם רע בשכינותיה. וכן היא שנדרה שלא תשאל ושלא תשאיל נפה וכברה וריחים ותנור,\u0004 או שנדרה \u0003שלא תארוג בגדים נאים לבניו — תצא שלא בכתובה, מפני שמשיאתו\u0004 (גורמת לו) \u0003שם רע בשכיניו,\u0004 שתולים בו את חסרונותיה, שסבורים שעל פי הוראתו היא נוהגת.","\u0003ואלו\u0004 הנשים ש\u0003יוצאות שלא בכתובה: העוברת על דת משה\u0004 (דיני התורה) \u0003ויהודית\u0004 (מנהג בנות ישראל שאינם מפורשים בכתובים). ומפרטים: \u0003ואיזו היא\u0004 העוברת על \u0003דת משה? —\u0004 כגון ש\u0003מאכילתו\u0004 אוכל \u0003שאינו מעושר,\u0004 או \u0003משמשתו\u0004 (משמשת עימו) כשהיא \u0003נדה, ולא קוצה\u0004 (מפרישה) \u0003לה חלה\u0004 מן העיסה, \u0003ונודרת ואינה מקיימת.\u0004 אלו הם דברים שהם דת משה, כלומר, דיני תורה.","\u0003ואיזוהי דת יהודית?\u0004 — כגון ש\u0003יוצאה\u0004 מחוץ לביתה \u0003ו\u0004שער \u0003ראשה פרוע\u0004 (גלוי), או שהיתה \u0003טווה בשוק ומדברת עם כל אדם. אבא שאול אומר: אף המקללת יולדיו\u0004 (הוריו) של בעלה \u0003בפניו. ר' טרפון אומר: אף הקולנית. ואיזוהי קולנית? — לכשהיא מדברת בתוך ביתה ושכיניה שומעין קולה.\u0004","שנינו במשנה בין הדברים הנחשבים לאשה כעבירה על דת משה: \u0003מאכילתו\u0004 דבר \u0003שאינו מעושר.\u0004 ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד היה הדבר בדיוק]?\u0006 \u0003אי דידע\u0004 \u0005[אם ש\u0006הוא \u0005יודע\u0006 שאינו מעושר\u0005] —\u0006 \u0003נפרוש\u0004 \u0005[שיפרוש]\u0006 ולא יאכל. \u0003אי דלא ידע\u0004 \u0005[אם שאינו יודע\u0006 שהאוכל אינו מעושר\u0005] —\u0006 אם כן \u0003מנא ידע\u0004 \u0005[מנין\u0006 הוא \u0005יודע]\u0006 שעשתה כן? ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא כגון שבפעם אחרת \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003\"פלוני כהן תיקן לי את הכרי\",\u0004 כלומר, עישר בשבילי את התבואה, \u0003ואזיל שייליה, ואשתכח שיקרא\u0004 \u0005[והלך\u0006 אחר כך ו\u0005שאל אותו, ונמצא\u0006 שהוא \u0005שקר],\u0006 ומכאן מוכח שאיננה מעשרת.","עוד שנינו במשנה בין הדברים הנחשבים כעבירה על דת משה: \u0003ומשמשתו נדה,\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי דידע\u0004 \u0005[אם ש\u0006הוא \u0005יודע]\u0006 \u0003בה\u0004 שהיא נדה — \u0003נפרוש\u0004 \u0005[שיפרוש\u0006 ממנה\u0005],\u0006 \u0003אי דלא ידע\u0004 \u0005[אם שאינו יודע] —\u0006 \u0003נסמוך עילוה\u0004 \u0005[שיסמוך עליה].\u0006 ש\u0003אמר רב חיננא בר כהנא אמר שמואל: מנין לנדה שסופרת לעצמה\u0004 ונאמנת על כך — \u0003שנאמר: \"וספרה לה שבעת ימים\"\u0004 (ויקרא טו, כח) \u0003\"לה\"\u0004 כוונתו — \u0003לעצמה\u0004 וסומכים עליה. ואם כן, מדוע לא יאמין לה?","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לכגון \u0003דאמרה ליה\u0004 \u0005[שאומרת לו]:\u0006 \u0003פלוני חכם טיהר לי את הדם\u0004 שאמר שאינו דם נדה, \u0003ואזל שייליה, ואשתכח שיקרא\u0004 \u0005[והלך\u0006 אחר כך \u0005שאל אותו, ונמצא\u0006 שהוא \u0005שקר].\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שהיה זה כמו הדבר שאמר \u0003רב יהודה,\u0004 ש\u0003אמר רב יהודה: הוחזקה נדה בשכינותיה,\u0004 כלומר, שהשכנות יודעות שהיא נדה — ואם שימש עמה \u0003בעלה לוקה עליה משום נדה.\u0004 ומדובר כאן באשה שהוחזקה בין שכנותיה כנדה ולא סיפרה לו ומשמשת אותו, ואחר כך נודע לו מפי השכנות.","עוד שנינו: \u0003ולא קוצה לה חלה.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי דידע\u0004 \u0005[אם ש\u0006הוא \u0005יודע\u0006 שלא הפרישה\u0005] —\u0006 \u0003נפרוש\u0004 \u0005[שיפרוש]\u0006 ולא יאכל, \u0003אי דלא ידע\u0004 \u0005[אם שאיננו יודע] —\u0006 \u0003מנא ידע\u0004 \u0005[מנין\u0006 הוא \u0005יודע\u0006 להאשים אותה\u0005]?\u0006 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לכגון \u0003דאמרה ליה\u0004 \u0005[שאומרת לו]:\u0006 \u0003פלוני גבל\u0004 (האיש שמלאכתו ללוש ולעשות עיסות) \u0003תיקן לי את העיסה\u0004 והפריש ממנה חלה, \u0003ואזיל שייליה, ואשתכח שיקרא\u0004 \u0005[והלך שאל אותו, ונמצא\u0006 שהוא \u0005שקר].\u0006","עוד שנינו במשנה: \u0003ונודרת ואינה מקיימת.\u0004 ומדוע עליו להוציאה בשל כך — ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003בעון נדרים\u0004 שאין מקיימים אותם — \u0003בנים מתים, שנאמר:\u0004 \"טוב אשר לא תדור משתדור ולא תשלם. \u0003אל תתן את פיך לחטיא את בשרך...\u0004 למה יקצוף האלהים על קולך וחיבל את מעשה ידך\" (קהלת ה ד-ה), \u0003ואיזו הן מעשה ידיו של אדם — הוי אומר בניו ובנותיו. רב נחמן אמר: מהכא\u0004 \u0005[מכאן]\u0006 יש ראיה לדבר, ממה שנאמר: \u0003\"לשוא הכיתי את בניכם\"\u0004 (ירמיה ב, ל), \u0003\"לשוא\"\u0004 כוונתו — \u0003על עסקי שוא,\u0004 שאתם נודרים ואינכם מקיימים.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003היה ר' מאיר אומר: כל היודע באשתו שנודרת ואינה מקיימת\u0004 — לא יגרשנה, אלא \u0003יחזור וידירנה.\u0004 ותוהים: \u0003ידירנה?! במאי\u0004 \u0005[במה]\u0006 \u0003מתקן לה\u0004 (אותה) אם מדיר אותה? \u0003אלא\u0004 הכוונה היא: \u0003יחזור ויקניטנה\u0004 (וירגיזנה) \u0003כדי שתדור בפניו ו\u0004אחר כך \u0003יפר לה. אמרו לו:\u0004 אין זו תקנה מועילה, לפי ש\u0003אין אדם דר עם נחש בכפיפה\u0004 (בסל) אחד, שאין יכול למנוע אותה כל הזמן מלנדור, ומוטב שיוציאנה.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 כיוצא בזה, \u0003היה ר' יהודה אומר: כל היודע באשתו שאינה קוצה לו חלה — יחזור ויפריש אחריה. אמרו לו:\u0004 אם אינה קוצה לו חלה צריך הוא לגרשה, שכן \u0003אין אדם דר עם נחש בכפיפה.\u0004","ומסבירים: \u0003מאן דמתני לה\u0004 \u0005[מי ששונה אותה],\u0006 את התקנה הזו שיתקן אחריה \u0003אהא\u0004 \u0005[על זו],\u0006 לענין חלה, \u0003כל שכן\u0004 ששונה אותה אף \u0003אהך\u0004 \u0005[על זו]\u0006 של נדרים (שיחזור ויקניטנה כדי שתידור לפניו ויפר לה), שאינם דבר של יום יום, \u0003אבל מאן דמתני אהך\u0004 \u0005[מי ששונה\u0006 אותה \u0005על זו\u0006 של נדרים\u0005]\u0006 שיחזור ויקניטנה, \u0003אבל הא\u0004 \u0005[בזו]\u0006 של חלה אין לומר כן, שכן \u0003זימנין דמקרי ואכיל\u0004 \u0005[פעמים ש\u0006הוא \u0005מזדמן ואוכל]\u0006 ואף ר' מאיר מסכים שאינו יכול להישמר כל כך ולכן יגרשנה.","שנינו במשנה: \u0003ואיזוהי\u0004 העוברת על \u0003דת יהודית\u0004 (מנהגי בנות ישראל)? — זו ש\u0003יוצאה וראשה פרוע.\u0004 ותוהים: \u0003ראשה פרוע\u0004 אינו רק ממנהג בנות ישראל אלא \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003היא דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]:\u0006 \u0003\"ופרע את ראש האשה\"\u0004 (במדבר ה, יח), \u0003ותנא\u0004 \u0005[ושנה\u0006 החכם\u0005]\u0006 \u0003דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 מכאן \u0003אזהרה לבנות ישראל שלא יצאו בפרוע ראש,\u0004 שאם נאמר שפורעים את ראש הסוטה, מכאן שאשה נשואה מכסה את ראשה בדרך כלל. ומסבירים: \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006"],["\u0003קלתה\u0004 (סל שלה) \u0003שפיר דמי\u0004 \u0005[יפה,\u0006 כשר הדבר\u0005],\u0006 ואולם משום \u0003דת יהודית אפילו קלתה נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור\u0004 וצריכה כיסוי ראש ממש.","\u0003אמר ר' אסי אמר ר' יוחנן:\u0004 המכסה שער ראשה ב\u0003קלתה — אין בה משום פרוע ראש\u0004 (גילוי שיער). \u0003הוי\u0004 \u0005[היה עוסק\u0006 ומתקשה\u0005]\u0006 \u0003בה ר' זירא: היכא\u0004 \u0005[היכן]\u0006 מדובר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהולכת כך \u0003בשוק —\u0004 הלא בכלל עבירה על \u0003דת יהודית היא,\u0004 כפי שאמרנו! \u0003ואלא\u0004 תאמר שהולכת כך \u0003בחצר\u0004 — \u0003אם כן לא הנחת בת לאברהם אבינו שיושבת\u0004 (שמותרת לשבת) \u0003תחת בעלה,\u0004 שרוב הנשים אינן מקפידות לכסות ראשן כראוי בתוך חצירן! \u0003אמר אביי ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב כהנא:\u0004 מה שאמר ר' יוחנן שאין בקילתה משום פרוע ראש, הכוונה היא לאופן שהולכת \u0003מחצר לחצר ודרך מבוי,\u0004 שהם מקומות שעשויים להיות בו אנשים זרים, אבל לא ברשות הרבים ממש.","בין הדברים האסורים לאשה משום עבירה על דת יהודית, שנינו במשנה גם את זו ה \u0003טווה בשוק. אמר רב יהודה אמר שמואל:\u0004 הכוונה היא \u0003במראה זרועותיה לבני אדם,\u0004 שתוך כדי טוויה מפשילה את השרוול מזרועותיה. \u0003רב חסדא אמר\u0004 בשם \u0003אבימי: בטווה ורד כנגד פניה,\u0004 שטווה בחוט אדום היוצא כנגד פניה להראות את יופיה, ויש בכך צד של פריצות. \u0003ומדברת עם כל אדם. אמר רב יהודה אמר שמואל:\u0004 הכוונה היא לזו ה\u0003משחקת עם בחורים.\u0004","\u0003אמר רבה בר בר חנה: זימנא חדא הוה קאזילנא בתריה\u0004 \u0005[פעם אחת הייתי מהלך אחרי]\u0006 \u0003רב עוקבא, חזיתיה לההיא ערביא דהוה יתבה קא שדיא פילכה\u0004 \u0005[ראיתי ערביה אחת שהיתה יושבת\u0006 ו\u0005מחזיקה פלך],\u0006 \u0003וטווה ורד כנגד פניה. כיון דחזיתינן\u0004 \u0005[שראתה אותנו],\u0006 \u0003פסיקתיה לפילכה שדיתיה\u0004 \u0005[קרעה את הפלך\u0006 מן החוט ו\u0005זרקה אותו].\u0006 \u0003אמרה לי: עולם\u0004 \u0005[בחור],\u0006 \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי פלך. אמר בה רב עוקבא מילתא\u0004 \u0005[דבר],\u0006 שאמר שזו היא דוגמה של דרך פריצות הנזכרת במשנה. ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003אמר בה,\u0004 מה הדבר שהזכיר במעשה זה מבין הדברים המנויים במשנה? \u0003רבינא אמר: \"טווה בשוק\" אמר בה. רבנן אמרי\u0004 \u0005[חכמים אומרים]:\u0006 \u0003\"מדברת עם כל אדם\" אמר בה.\u0004","שנינו במשנה, \u0003אבא שאול אומר: אף המקללת יולדיו בפניו\u0004 נחשבת כעוברת על דת יהודית. \u0003אמר רב יהודה אמר שמואל:\u0004 לא דווקא בפני הבעל ממש, אלא אף \u0003במקללת יולידיו בפני מולידיו,\u0004 שמקללת את הורי הבעל בפני ילדיו, שאף על פי שאינם אלא בני בנים, מכל מקום יש בכך בזיון. \u0003וסימניך \"אפרים ומנשה כראובן ושמעון יהיו לי\"\u0004 (בראשית מח, ה), ללמדנו שבני בנים הריהם כבנים והרי זה כמקללת בפניו ממש. \u0003אמר רבה:\u0004 כגון \u0003דאמרה ליה\u0004 \u0005[שאומרת לו]:\u0006 \u0003ניכליה אריא לסבא\u0004 \u0005[שיאכל אריה את הסב],\u0006 \u0003באפי בריה\u0004 \u0005[בפני בנו]\u0006 של בעלה.","שנינו במשנה, ש \u0003ר' טרפון אומר: אף הקולנית\u0004 נחשבת כעוברת על דת יהודית. ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"קולנית\"? אמר רב יהודה אמר שמואל: במשמעת קולה על עסקי תשמיש,\u0004 שמתווכחת ורבה עם בעלה בקול רם בענייני תשמיש עד שהשכנים שומעים וגורמת לו בכך בושה. \u0003במתניתא תנא\u0004 \u0005[בברייתא שנה]:\u0006 \u0003במשמשת בחצר זו,\u0004 ומפני שכואב לה הריהי צועקת \u0003ונשמע קולה בחצר אחרת.\u0004","ואומרים: אם כך, \u0003וניתנייה גבי מומין במתניתין\u0004 \u0005[ושישנה\u0006 דבר \u0005זה לגבי המומים\u0006 המוזכרים \u0005במשנתנו]\u0006 שבסוף הפרק, שאם עושה כן מחמת כאב הלא מום הוא, ולא חסרון בהתנהגותה! \u0003אלא מחוורתא כדשנין מעיקרא\u0004 \u0005[מחוור,\u0006 ברור, \u0005כפי שהסברנו קודם]\u0006 שהיא קולנית מפני חוסר צניעותה.","\u0003המקדש את האשה על מנת שאין עליה נדרים, ו\u0004אחר כך \u0003נמצאו עליה נדרים — אינה מקודשת,\u0004 שעם ביטול התנאי בטלו הקידושין. ואם \u0003כנסה סתם\u0004 בלא כל תנאי \u0003ונמצאו עליה נדרים — הריהי מקודשת, ואולם אם מצא\u0004 בה חסרון שלא הודיעה לו עליו מתחילה — \u0003תצא שלא בכתובה.\u0004","קידשה \u0003על מנת שאין בה מומין ונמצאו בה מומין — אינה מקודשת. כנסה סתם ונמצאו בה מומין — תצא שלא בכתובה.\u0004 ואלה הם המומים שאמרו: \u0003כל המומין הפוסלין בכהנים\u0004 שנמנו במסכת בכורות, שיש בהם שינוי צורה ניכר — כל אלה \u0003פוסלין\u0004 גם \u0003בנשים.\u0004","על דברי המשנה מעירים: \u0003ותנן נמי גבי\u0004 \u0005[ושנינו גם כן\u0006 במשנה במסכת\u0005]\u0006 \u0003קדושין כי האי גוונא\u0004 \u0005[כגון זה],\u0006 כלומר, אותה משנה עצמה, המקדש את האשה וכו', ולשם מה הכפילות? ומסבירים: \u0003הכא\u0004 \u0005[כאן]\u0006 ענין \u0003כתובות איצטריכא ליה\u0004 \u0005[היה צריך לו]\u0006 להשמיענו, שהוא ענין המסכת, ומתוך זה \u0003תנא\u0004 \u0005[שנה]\u0006 גם דין \u0003קדושין\u0004 ברישא \u0003אטו\u0004 \u0005[אגב\u0006 ששנה\u0005]\u0006 דין \u0003כתובות. התם\u0004 \u0005[שם]\u0006 במסכת קדושין ענין \u0003קדושין אצטריכא ליה\u0004 \u0005[היה צריך לו\u0006 להשמיע\u0005]\u0006 ומתוך זה \u0003תנא\u0004 \u0005[שנה]\u0006 גם דין \u0003כתובות\u0004 בסיפא \u0003אטו\u0004 \u0005[אגב]\u0006 ענין \u0003קדושין.\u0004","\u0003אמר ר' יוחנן משום ר' שמעון בן יהוצדק: באלו נדרים אמרו\u0004 במשנתנו שתצא שלא בכתובה — כגון שאמרה \u0003שלא תאכל בשר, ושלא תשתה יין, ושלא תתקשט בבגדי צבעונים. תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא בתוספתא על משנתנו \u0005גם כן כך],\u0006 \u0003באלו נדרים אמרו: דברים שיש בהן עינוי נפש;\u0004 וכגון שנדרה \u0003שלא תאכל בשר ושלא תשתה יין ושלא תתקשט בבגדי צבעונין.\u0004","\u0003הוי\u0004 \u0005[עסק,\u0006 התקשה\u0005]\u0006 \u0003בה רב פפא: אהייא\u0004 \u0005[על איזו]\u0006 פיסקה במשנה מוסבים דברים אלה? \u0003אילימא ארישא\u0004 \u0005[אם תאמר על ראשה]\u0006 של המשנה — במי שקידש את האשה על מנת שאין עליה נדרים, הרי \u0003כיון\u0004 שגילה דעתו \u0003דקא קפיד\u0004 \u0005[\u0006ש\u0005מקפיד]\u0006 בענין נדרים — \u0003אפילו כל מילי\u0004 \u0005[דבר]\u0006 \u0003נמי\u0004 \u0005[גם כן]!\u0006 ואפילו נדרים בדברים בלתי חשובים, כיון שקידשה על תנאי ולא נתקיים בה התנאי — בטלו הקידושין. \u0003אלא\u0004 צריך לומר כי אמר זאת \u0003אסיפא\u0004 \u0005[על סופה\u0006 של המשנה\u0005],\u0006 שאם כנסה סתם ונמצאו עליה נדרים תצא בלא כתובה— לא בכל הנדרים אמרו, אלא בנדרים אלה שיש בהם עינוי נפש ניכר.","\u0003רב אשי אמר: לעולם\u0004 תפרש שמדובר פה \u0003ארישא\u0004 \u0005[על ראשה\u0006 של המשנה\u0005]\u0006 שהתנה איתה שאין עליה נדרים, \u0003ו\u0004אולם רצו לומר כי \u0003מידי דקפדי בה אינשי\u0004 \u0005[ודבר שמקפידים בו אנשים\u0006 בדרך כלל\u0005] —\u0006 \u0003הוה קפידיה קפידא\u0004 \u0005[הרי הקפדתו\u0006 היא \u0005הקפדה]\u0006 ומועילה לבטל את הקידושין, ואילו \u0003מידי דלא קפדי בה אינשי\u0004 \u0005[דבר שאין מקפידים בו אנשים] —\u0006 \u0003לא הוי קפידיה קפידא\u0004 \u0005[אין הקפדתו הקפדה]\u0006 ואין זה נקרא ביטול התנאי.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שדנו חכמים בשאלה הבאה: \u0003קידשה\u0004 את האשה \u0003על תנאי,\u0004 כגון על תנאי שאין עליה נדרים, \u0003וכנסה\u0004 (נשאה) אחר כך \u0003סתם\u0004 בלא כל תנאי, ואחר כך התברר שלא התקיים התנאי, \u0003רב אמר:\u0004 אף על פי שרשאי להוציאה בלא כתובה — לא בטלו הקידושין, ו\u0003צריכה הימנו\u0004 (ממנו) \u0003גט. ושמואל אמר:\u0004 הקידושין בטלים מעיקרם ולפיכך \u0003אינה צריכה הימנו גט. אמר אביי:\u0004"],["\u0003לא תימא טעמיה\u0004 \u0005[אל תאמר\u0006 ש\u0005טעמו]\u0006 של \u0003רב\u0004 המצריך גט, הוא זה: ש\u0003כיון שכנסה\u0004 (נשאה) \u0003סתם\u0004 ולא חזר והזכיר את התנאי, משמע כי \u0003אחולי אחליה לתנאיה\u0004 \u0005[מחל על תנאו]\u0006 לגמרי ולכן חייב גם בכתובתה אם יגרשנה, \u0003אלא טעמא\u0004 \u0005[הטעם]\u0006 של \u0003רב\u0004 הוא זה: \u0003לפי שאין אדם עושה בעילתו בעילת זנות.\u0004 שכאשר יודע שיכולה להיות אפשרות של ביטול הקידושין ותימצא בעילתו בעילת זנות, לכך הוא בועל עכשיו לשם קידושין, אבל אינו מוחל לגמרי על התנאי, ואם יתברר שלא נתקיים תנאו תצא בלא כתובה.","ושואלים: \u0003הא פליגי\u0004 \u0005[הרי\u0006 כבר \u0005נחלקו]\u0006 \u0003בה חדא זימנא\u0004 \u0005[פעם אחת],\u0006 בבעיה עקרונית זו אם אדם עושה בעילתו זנות, \u0003דאתמר\u0004 \u0005[שנאמר]:\u0006 \u0003קטנה\u0004 שהשיאוה אמה או אחיה \u0003שלא מיאנה\u0004 בבעלה בקטנותה, אף על פי שהיתה יכולה למאן, \u0003והגדילה,\u0004 ובא עליה בעלה משגדלה ואחר כך מיאנה ו\u0003עמדה ונישאת\u0004 לאחר — \u0003רב אמר: אין צריכה גט משני,\u0004 שאין קידושיו תופסים, שכיון שלא מיאנה בקטנותה ובא עליה משגדלה, נישואיה הראשונים תופסים. שכיון שיודע שאין בקידושי קטנה כלום, ודאי ביאתו זו היתה לשם קידושין, והנישואין השניים אין בהם ממש.","\u0003ושמואל אמר: צריכה גט משני,\u0004 שלא התכוון בעלה הראשון בביאתו משגדלה לשם קידושין חדשים, ולא היה זה אלא המשך הקשר הראשון בהיותה קטנה, ואינה נחשבת אשתו, ומשום כך חלו הנישואין השניים.","ומסבירים: \u0003צריכא\u0004 \u0005[צריך]\u0006 לפרש את המחלוקת בשני המקרים, גם במקדש על תנאי וגם בקטנה שלא מיאנה ונישאה. \u0003דאי אתמר\u0004 \u0005[שאילו\u0006 היה \u0005נאמר]\u0006 רק \u0003ב\u0004הלכה \u0003ההיא,\u0004 בקטנה שלא מיאנה, היינו אומרים שרק \u0003ב\u0004הלכה \u0003ההיא קאמר\u0004 \u0005[אמר]\u0006 \u0003רב משום דליכא תנאה\u0004 \u0005[שאין תנאי]\u0006 בקידושין, ולכן כשגדלה בא עליה לשם קידושין אלה, ויודע היה שלא תפסו, \u0003אבל בהא דאיכא תנאה\u0004 \u0005[בזו שיש תנאי]\u0006 ועברה על התנאי, \u0003אימא מודי ליה\u0004 \u0005[אמור\u0006 ש\u0005מודה לו]\u0006 רב \u0003לשמואל\u0004 שלא בעל לשם קידושין, ואינה צריכה גט.","ולהיפך: \u0003ואי אתמר בהא\u0004 \u0005[ואילו\u0006 היה \u0005נאמר\u0006 רק \u0005בזו]\u0006 בענין קידושין, היינו אומרים: \u0003בהא קאמר\u0004 \u0005[בזו אמר]\u0006 \u0003שמואל\u0004 שאין הקידושין חלים כשבא עליה, משום שהיה תנאי והיא לא עמדה בתנאי, \u0003אבל בהך\u0004 \u0005[בההיא],\u0006 בקטנה שלא מיאנה, \u0003אימא מודי ליה\u0004 \u0005[אמור\u0006 ש\u0005מודה לו]\u0006 שמואל \u0003לרב,\u0004 על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שתי המחלוקות בשני המקרים במפורש. ומעתה מביאים ראיות לשיטות השונות.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003כנסה סתם ונמצאו עליה נדרים — תצא שלא בכתובה.\u0004 ונדייק מכאן: \u0003כתובה הוא דלא בעיא\u0004 \u0005[שאינה צריכה]\u0006 ולא מגיע לה, \u0003הא גיטא בעיא\u0004 \u0005[הרי גט\u0006 היא \u0005צריכה],\u0006 \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר פה במקרה כפי שאמרנו, ש\u0003קידשה על תנאי וכנסה סתם,\u0004 ואם כן \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא לשיטת \u0003שמואל\u0004 מן המשנה!"],["\u0003לא,\u0004 שם מדובר במקרה ש\u0003קידשה סתם\u0004 ולא הזכיר תנאי כלשהו, \u0003וכנסה\u0004 (נשאה) \u0003סתם.\u0004","ושואלים: \u0003אבל\u0004 לפי הסבר זה, אם \u0003קידשה על תנאי וכנסה סתם — הכי נמי\u0004 ש\u0003לא בעיא גיטא\u0004 \u0005[כך גם כן שלא תצטרך גט]?\u0006 אם כן, \u0003אדתני\u0004 \u0005[עד ש\u0006הוא \u0005שונה]\u0006 במשנה את המקרה של \u0003המקדש את האשה על מנת שאין עליה נדרים, ונמצאו עליה נדרים אינה מקודשת, ליתני\u0004 \u0005[שישנה]\u0006 במקום זה הלכה שיש בה חידוש גדול יותר: קידשה על תנאי ואחר כך \u0003כנסה סתם ונמצאו עליה נדרים, אינה מקודשת,\u0004 וממנו נלמד: \u0003וכל שכן הא\u0004 \u0005[זו]\u0006 שרק קידשה על תנאי ולא כנסה.","ומשיבים: \u0003הכי נמי קאמר\u0004 \u0005[כך גם כן אמר]\u0006 במשנה, כלומר, כך באמת צריכים להבין את המשנה: \u0003המקדש את האשה על מנת שאין עליה נדרים וכנסה סתם, ונמצאו עליה נדרים — אינה מקודשת.\u0004 ואם \u0003קידשה סתם וכנסה סתם —\u0004 הריהי מקודשת והרי זו \u0003תצא שלא בכתובה.\u0004","לעצם עניינה של הלכה זו, לשיטת שמואל, שואלים: \u0003כתובה הוא דלא בעיא\u0004 \u0005[שאינה צריכה],\u0006 \u0003הא גיטא\u0004 \u0005[הרי גט] —\u0006 \u0003בעיא\u0004 \u0005[צריכה].\u0006 ויש לשאול: \u0003ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה]\u0006 \u0003כתובה דלא בעיא\u0004 \u0005[שאינה צריכה] —\u0006 משום \u0003דאמר\u0004 \u0005[ש\u0006הוא \u0005אומר]:\u0006 \u0003אי אפשי באשה נדרנית\u0004 והרי זה כמקח טעות, \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003גט נמי\u0004 \u0005[גם כן]\u0006 \u0003לא תיבעי\u0004 \u0005[תצטרך],\u0006 שהרי רואים שהוא מקפיד בדבר, ונמצא שהיו קידושיו בטעות!","\u0003אמר רבה:\u0004 אמנם מעיקר הדין בטלו הקידושין, ומה שאמרו ש\u0003צריכה גט\u0004 הרי זה \u0003מדבריהם,\u0004 מדברי סופרים, שכיון שלא קבע תנאי זה במפורש לפיכך אמרו חכמים שלא תצא אלא בגט. \u0003וכן אמר רב חסדא: צריכה גט מדבריהם. רבא אמר\u0004 הסבר אחר מדוע צריכה גט ואינה מקבלת כתובה: ה\u0003תנא ספוקי מספקא ליה\u0004 \u0005[מסופק\u0006 בדבר\u0005]\u0006 ואינו בטוח מה דין הקידושין, ולכן, \u0003גבי ממונא לקולא\u0004 \u0005[לגבי ממון\u0006 יש \u0005להקל],\u0006 ולכן פסק שאין מוציאים מן האיש את דמי הכתובה, ואילו \u0003גבי איסורא לחומרא\u0004 \u0005[לגבי איסור\u0006 של אשת איש פסק \u0005להחמיר]\u0006 ומפני הספק צריכה גט.","\u0003אמר רבה: מחלוקת\u0004 רב ושמואל היא \u0003בטעות שתי נשים.\u0004 שאותו אדם נשא אשה אחת על מנת שאין עליה נדרים, ואשה אחרת נשא סתם, ונחלקו רב ושמואל אם מהתנאי שהתנה במפורש עם אשה אחת מוכח שהוא מקפיד גם לגבי האשה האחרת בענין נדרים עד כדי ביטול הקידושין אם לא התקיים התנאי, \u0003אבל בטעות אשה אחת\u0004 שמתנה לפני הקידושין על מנת שאין עליה נדרים, וכנסה סתם ונמצא שיש עליה נדרים — \u0003דברי הכל,\u0004 אף רב מודה שאינה מקודשת כלל ולפיכך \u0003אין צריכה הימנו\u0004 (ממנו) \u0003גט.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: והא מתניתין\u0004 \u0005[והרי משנתנו]\u0006 שעניינה \u0003טעות אשה אחת היא\u0004 שהרי אין נזכרת בה אשה אחרת, \u0003וקמותבינן תיובתא מיניה\u0004 \u0005[ואנו מקשים קושיה ממנה]\u0006 על שמואל, משמע שרב ושמואל אף במקרה זה הם חלוקים!","\u0003אלא\u0004 יש לחזור מהתירוץ הקודם ולומר כי \u0003אי אתמר, הכי אתמר\u0004 \u0005[אם נאמר\u0006 בשם רבה, \u0005כך נאמר],\u0006 \u0003אמר רבה: מחלוקת בטעות אשה אחת כעין שתי נשים,\u0004 שקידש אשה על תנאי וגירשה בעודה ארוסה, ואחר כך חזר ונשא אותה ולא הזכיר את התנאי. ובזה נחלקו רב ושמואל: האם יש לומר שבעילתו היא כקידושין וכאילו קידש אחרת ובקידושין השניים ביטל את התנאי הראשון, שהרי לא חזר והתנה, או שמא על דעת התנאי הראשון נשא אותה שוב. \u0003אבל בטעות אשה אחת גרידתא\u0004 \u0005[בלבד],\u0006 שקידש אותה על תנאי וכנסה, והתברר שהתנאי לא התקיים — \u0003דברי הכל אינה צריכה הימנו\u0004 (ממנו) \u0003גט.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 ממה ששנינו: \u0003קידשה\u0004 את האשה \u0003בטעות,\u0004 או קידשה בדבר שערכו \u0003פחות משוה פרוטה, וכן קטן שקידש\u0004 אשה ולהלכה אין קידושיו קידושין, \u0003אף על פי ששלח סבלונות\u0004 (מתנות) לכלה \u0003לאחר מיכן,\u0004 ואף שערכן יותר משוה פרוטה, והגדיל הקטן — \u0003אינה מקודשת,\u0004 והטעם בזה — \u0003ש\u0004ודאי \u0003מחמת קדושין הראשונים שלח. ואם בעלו\u0004 כל אלה לאחר הקידושין בזמן הראוי — \u0003קנו\u0004 את הנשים, שמן הסתם נתכוונו לקנות אותן קנין קידושין בביאה זו. \u0003ר' שמעון בן יהודה משום ר' ישמעאל אמר:\u0004 אף \u0003אם בעלו — לא קנו,\u0004 שמן הסתם בעלו על דעת קידושין ראשונים — ולא קנו.","\u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 בברייתא זו ש\u0003טעות אשה אחת היא,\u0004 שהרי מדובר פה על אשה שקידש אותה בטעות ואחר כך בעל, \u0003ופליגי\u0004 \u0005[ו\u0006הם \u0005חלוקים].\u0006 \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה במה שאמרו קידשה בטעות היא \u0003טעות\u0004 שטעה בתנאי \u0003נדרים\u0004 וחשב שאין עליה נדרים?","ומשיבים: \u0003לא,\u0004 כאן מדובר ב\u0003טעות\u0004 בהלכה, שקידש אשה ב\u0003פחות משוה פרוטה\u0004 ולא ידע שאין אשה מתקדשת בפחות משוה פרוטה\u0003.\u0004 ומקשים: \u0003פחות משוה פרוטה\u0004 הלא \u0003בהדיא קתני לה\u0004 \u0005[בפירוש שנה אותה]\u0006 לאחר כך בדין מיוחד: \u0003קידשה בטעות ופחות משוה פרוטה!\u0004 ומתרצים: \u0003פרושי קא מפרש\u0004 \u0005[מפרש\u0006 הוא\u0005]\u0006 את הדברים שאמר קודם: \u0003קידשה בטעות כיצד? כגון\u0004 ש\u0003קידשה בפחות משוה פרוטה\u0004 ובודאי לא בעל אותה על דעת קידושין כאלו.","ושואלים: לפי זה \u0003במאי קא מיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון הם \u0005חלוקים]?\u0006 ומשיבים: \u0003מר\u0004 \u0005[חכם זה,\u0006 התנא קמא\u0005]\u0006 \u0003סבר\u0004 כי \u0003אדם יודע שאין קדושין תופסין בפחות משוה פרוטה, ו\u0004כיון שיודע שקידושיו הראשונים לא תפסו לכן ודאי \u0003גמר\u0004 בדעתו (החליט) \u0003ובעל\u0004 אותה \u0003לשם קדושין\u0004 ונקנתה לו קנין גמור בבעילה זו. \u0003ומר\u0004 \u0005[וחכם זה,\u0006 ר' שמעון בן יהודה\u0005]\u0006 \u0003סבר\u0004 ש\u0003אין אדם יודע שאין קדושין תופסין בפחות משוה פרוטה, וכי קא\u0004 \u0005[וכאשר הוא]\u0006 \u0003בעל\u0004 אותה אחר כך, \u0003אדעתא\u0004 \u0005[על דעת]\u0006 ה\u0003קדושין הראשונים\u0004 הוא ש\u0003בעל\u0004 ולא היה כאן קנין קידושין חדש.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 אביי ממה ששנינו: אמר לאשה בשעת בעילה \u0003\"הריני בועליך\u0004 לשם קידושין \u0003על מנת שירצה אבא\"\u0004 ואחר כך כנסה סתם, \u0003אף על פי שלא רצה האב\u0004 — בכל אופן \u0003מקודשת\u0004 בבעילה זו. \u0003ר' שמעון בן יהודה אומר משום ר' שמעון:\u0004 אם \u0003רצה האב — מקודשת,\u0004 ואם \u0003לא רצה האב — אינה מקודשת,\u0004 שעל דעת התנאי הראשון בא עליה. \u0003והא הכא\u0004 \u0005[והרי כאן],\u0006 במקרה זה, \u0003דכי\u0004 \u0005[שכמו]\u0006 \u0003טעות אשה אחת דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 \u0003ופליגי\u0004 \u0005[ו\u0006הם \u0005חלוקים]\u0006 האם הקידושין הללו בטלים מעיקרם או לא!","ודוחים: לא בענין זה נחלקו אלא \u0003התם בהא קמיפלגי\u0004 \u0005[שם ב\u0006דבר \u0005זה\u0006 הם \u0005חלוקים],\u0006 \u0003מר\u0004 \u0005[חכם זה,\u0006 תנא קמא\u0005]\u0006 \u0003סבר\u0004 ש\u0003\"על מנת שירצה האב\"\u0004 כוונתו — \u0003על מנת שישתוק האב,\u0004 כלומר, שאם לא ימחה האב יחולו הקידושין, \u0003והא שתיק ליה\u0004 \u0005[והרי שותק לו]\u0006 ולכן תפסו הקידושין. \u0003ומר\u0004 \u0005[וחכם זה,\u0006 ר' שמעון בן יהודה\u0005]\u0006 \u0003סבר\u0004 שהיתה כוונתו \u0003על מנת שיאמר אבא\u0004 במפורש \u0003\"הן\"\u0004 \u0005[כן],\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לא אמר אבא \"הן\",\u0004 והמחלוקת היא איפוא בפירושה של השתיקה לענין זה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 עוד אביי לרבה ממה ששנינו בברייתא: \u0003מודים חכמים לר' אליעזר בקטנה שהשיאה אביה ונתגרשה\u0004 בעודה קטנה \u0003והיא\u0004 אז מבחינת הדין במעמד של \u0003יתומה בחיי האב,\u0004 משום שלאחר שנישאה שוב אין לאב רשות להשיאה לאיש. \u0003ו\u0004אחר כך בעודה קטנה \u0003החזירה\u0004 בעלה שהיתה נשואה לו, ומת הבעל ולא היו להם ילדים — הרי היא \u0003חולצת ולא מתיבמת,\u0004","\u0003מפני שגירושיה\u0004 מבעלה היו \u0003גירושין גמורין,\u0004 שהאב רשאי לקבל גיטה מיד בעלה והוא גט גמור ואסורה ליבם משום גרושת אחיו, \u0003ואין חזרתה\u0004 לבעלה לאחר מכן \u0003חזרה גמורה.\u0004 שכיון שאביה אין לו עוד רשות להשיאה, וכשחזרה לבעלה עשתה זאת כשהיא קטנה ונישואי קטנה אינם נישואין גמורים.","\u0003במה דברים אמורים — שגירשה כשהיא קטנה והחזירה כשהיא קטנה, אבל\u0004 אם \u0003גירשה כשהיא קטנה, והחזירה כשהיא גדולה, או שהחזירה כשהיא קטנה וגדלה אצלו\u0004 (נעשתה גדולה בעודה אצלו) אנו אומרים שהנישואין השניים תפסו, ודינה כנשואה גמורה, \u0003ו\u0004אם \u0003מת — או חולצת או מתיבמת\u0004 כדין כל אלמנה אחרת."]]};
